// Content for Lead the Way (node g33, ages 15-18, Chapter 5): NEW v2 build to GDD 33 (mechanic-embodying),
// the structural-equality → leadership node (Thread E · Gender & Respect). "You don't need a title or a megaphone
// to lead: be the ally, set the example, lift others, and change the room you're in, whatever your gender." 84
// researched, India-grounded, even-handed scenarios across the-gaps → what-allyship-is → lead-by-example →
// lift-as-you-climb → call-in-not-out → your-leadership-style, each encoded as one of the shared v2 play actions
// (reflect / branch / strike-rewrite / sort / role-play / match / spot): no binary "tap the right card". Lead:
// branch (your move), strike-rewrite (bust the myth), reflect. Allyship is everyone's job and MEN LEADING ON
// GENDER EQUALITY IS STRENGTH, NOT BETRAYAL (the key India reframe). Understands the real gaps (pay ~34% in
// India, women's leadership gap, unpaid-care load) and turns understanding into quiet, everyday leadership: lead
// by example, lift as you climb, call IN over call OUT, lead from your values. India: engaging boys/men as allies
// is a top lever; respect families (persuasion over confrontation); Women's Reservation Act 2023; India's own
// role models. Safety first: witnessing harm routes to a trusted adult/teacher, 181, 112, Childline 1098.
// Builds on g26 (Equalize) & g27 (Stand Up); sets up g34 (Change Makers). gameId "lead-the-way".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"lw-001","cat":"the-gaps","type":"sort","hook":"Sort: a real, measured gap, or a comforting myth?","items":[{"id":"a","text":"Women earn notably less for similar work"},{"id":"b","text":"\"There's no pay gap anymore\""},{"id":"c","text":"Women do far more unpaid care"},{"id":"d","text":"\"Care work isn't really work\""},{"id":"e","text":"Few women reach top leadership roles"},{"id":"f","text":"\"It's all completely equal now\""}],"bins":[{"id":"real","label":"Real gap","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"The pay, care and leadership gaps are real and measured; denying them is a myth.","persona":"any","source":"pay gap / unpaid care (verified)"},
  {"id":"lw-002","cat":"the-gaps","type":"match","hook":"Match each gap to a true fact about it.","pairs":[{"left":"Pay gap (India)","right":"Women earn far less for similar work"},{"left":"Unpaid care","right":"Women do far more of it"},{"left":"Leadership","right":"Few women reach the top"},{"left":"Labour force","right":"Under a quarter of women take part"},{"left":"Reservation Act","right":"A third of seats kept for women"}],"relearn":"Pay, care, leadership and participation gaps are real and measured.","persona":"any","source":"structural gaps (verified)"},
  {"id":"lw-003","cat":"the-gaps","type":"strike-rewrite","hook":"\"The pay gap is just because women choose easier jobs.\"","myth":{"un":"The pay gap is just women choosing easier jobs.","re":"Much of it is bias and the unpaid-care load women carry, not 'choice'.","why":"Women earn less even for similar work."},"relearn":"Much of the pay gap is bias and the care load, not 'easier choices'.","persona":"any","source":"pay gap"},
  {"id":"lw-004","cat":"the-gaps","type":"strike-rewrite","hook":"\"Unpaid housework and care aren't real work.\"","myth":{"un":"Unpaid housework and care aren't real work.","re":"It's enormous, essential work, in India women average around 283 minutes a day of it.","why":"It's invisible in GDP but it holds families and economies up."},"relearn":"Unpaid care is huge, essential work, and women do most of it.","persona":"any","source":"unpaid care (verified)"},
  {"id":"lw-005","cat":"the-gaps","type":"strike-rewrite","hook":"\"Women just aren't interested in leadership.\"","myth":{"un":"Women just aren't interested in leadership.","re":"Barriers and bias, not interest, keep women out of top roles.","why":"Where barriers fall, women lead in every field."},"relearn":"It's barriers and bias, not lack of interest, behind the leadership gap.","persona":"Sneha","source":"leadership gap"},
  {"id":"lw-006","cat":"the-gaps","type":"reflect","hook":"Lensy: India passed a law reserving a third of legislative seats for women. Step toward closing the leadership gap?","prompt":"What do you think?","options":["Yes","A real step","Good to know"],"affirm":"The Women's Reservation Act is a concrete move toward more women in leadership.","relearn":"India's Women's Reservation Act reserves a third of legislative seats for women.","persona":"any","source":"Women's Reservation Act 2023 (verified)"},
  {"id":"lw-007","cat":"the-gaps","type":"sort","hook":"Sort: helps close a gap, or widens it?","items":[{"id":"a","text":"Sharing care work at home"},{"id":"b","text":"Assuming only women should cook and clean"},{"id":"c","text":"Backing women into leadership"},{"id":"d","text":"Paying women less for the same job"},{"id":"e","text":"Encouraging a girl into engineering"},{"id":"f","text":"Steering girls away from science"}],"bins":[{"id":"close","label":"Closes a gap","valence":"pos"},{"id":"widen","label":"Widens it","valence":"neg"}],"key":{"a":"close","b":"widen","c":"close","d":"widen","e":"close","f":"widen"},"relearn":"Sharing care and backing women closes gaps; bias and steering widen them.","persona":"any","source":"structural equality"},
  {"id":"lw-008","cat":"the-gaps","type":"reflect","hook":"Lensy: when care work is shared fairly, women have more time for paid work and leadership. See the link?","prompt":"What do you think?","options":["Yes","It's connected","Sharing helps"],"affirm":"The unpaid-care load and the pay/leadership gaps are linked; sharing care helps close all of them.","relearn":"Sharing unpaid care frees women's time for paid work and leadership.","persona":"any","source":"links / unpaid care"},
  {"id":"lw-009","cat":"the-gaps","type":"strike-rewrite","hook":"\"Equality just means men losing out.\"","myth":{"un":"Closing these gaps just means men lose out.","re":"Equality isn't zero-sum; it lifts everyone, men included.","why":"Fairer homes and stronger economies benefit all."},"relearn":"Closing the gaps isn't men losing; equality lifts everyone.","persona":"Vijay","source":"not zero-sum (links g26)"},
  {"id":"lw-010","cat":"the-gaps","type":"sort","hook":"Sort: a structural cause of the gap, or victim-blaming?","items":[{"id":"a","text":"Bias in hiring and pay"},{"id":"b","text":"\"Women just don't try hard enough\""},{"id":"c","text":"The unpaid-care load on women"},{"id":"d","text":"\"It's individual laziness\""},{"id":"e","text":"Being steered away from leadership"},{"id":"f","text":"\"They simply lack ambition\""}],"bins":[{"id":"structural","label":"Structural","valence":"pos"},{"id":"blame","label":"Victim-blaming","valence":"neg"}],"key":{"a":"structural","b":"blame","c":"structural","d":"blame","e":"structural","f":"blame"},"relearn":"Bias, the care load and steering are structural; 'they don't try' is victim-blaming.","persona":"any","source":"structural vs blame"},
  {"id":"lw-011","cat":"the-gaps","type":"match","hook":"Match the lever to the gap it helps close.","pairs":[{"left":"Shared care at home","right":"Frees women's time"},{"left":"Fair pay for equal work","right":"Closes the pay gap"},{"left":"Backing women leaders","right":"Closes the leadership gap"},{"left":"Reserved legislative seats","right":"More women in lawmaking"},{"left":"Encouraging girls into STEM","right":"Widens their career paths"}],"relearn":"Shared care, fair pay, backing leaders, reserved seats and STEM access each close a gap.","persona":"any","source":"levers"},
  {"id":"lw-012","cat":"the-gaps","type":"reflect","hook":"Lensy: knowing the gaps are real and fixable, do you feel like you could be part of the fix?","prompt":"What do you think?","options":["Yes","I can help","Part of the fix"],"affirm":"The gaps are made by choices and systems, which means people, including you, can help change them.","relearn":"The gaps are real and fixable, and you can be part of closing them.","persona":"any","source":"agency"},
  {"id":"lw-013","cat":"the-gaps","type":"reflect","hook":"Lensy: this game is about turning that understanding into leadership. Ready to lead on it?","prompt":"What do you think?","options":["Yes","Let's lead","Ready"],"affirm":"Understanding the gaps is step one; leading to close them is what's next.","relearn":"Understanding the gaps becomes leadership when you act to close them.","persona":"any","source":"bridge to leadership"},
  {"id":"lw-014","cat":"the-gaps","type":"sort","hook":"Sort: an accurate picture, or a comforting myth?","items":[{"id":"a","text":"Gaps remain despite real progress"},{"id":"b","text":"\"It's all completely equal now\""},{"id":"c","text":"Change is possible and happening"},{"id":"d","text":"\"Nothing can ever change\""},{"id":"e","text":"The gaps are measured, not invented"},{"id":"f","text":"\"These gaps are just made up\""}],"bins":[{"id":"accurate","label":"Accurate","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"accurate","b":"myth","c":"accurate","d":"myth","e":"accurate","f":"myth"},"relearn":"Gaps remain but change is real; 'all equal', 'never changes' and 'made up' are myths.","persona":"any","source":"realism + hope"},
  {"id":"lw-015","cat":"the-gaps","type":"reflect","hook":"Lensy: which gap do you most want to help close?","prompt":"Pick one.","options":["The pay gap","The leadership gap","The care-work gap","All of them"],"affirm":"Whichever you choose, leading on it makes a real difference.","relearn":"Pay, leadership and care gaps are all real places to lead change.","persona":"any","source":"motivation"},
  {"id":"lw-016","cat":"what-allyship-is","type":"strike-rewrite","hook":"\"You need a title or a stage to lead.\"","myth":{"un":"You need a title or a stage to lead.","re":"Quiet, everyday leadership, modelling respect and lifting others, is real leadership.","why":"Most change comes from ordinary people, not megaphones."},"relearn":"You don't need a title or a stage; quiet everyday leadership is real.","persona":"any","source":"leadership reframe"},
  {"id":"lw-017","cat":"what-allyship-is","type":"strike-rewrite","hook":"\"Gender equality is women's job, not boys' problem.\"","myth":{"un":"Gender equality is women's job, not boys' problem.","re":"It's everyone's job; engaging men and boys as allies is one of the strongest levers.","why":"Change is faster and fairer when everyone leads."},"relearn":"Equality is everyone's job; men and boys leading is a powerful lever.","persona":"Vijay","source":"allyship for all (HeForShe)"},
  {"id":"lw-018","cat":"what-allyship-is","type":"strike-rewrite","hook":"\"A boy who supports equality is betraying his side or is weak.\"","myth":{"un":"A boy supporting equality is betraying his side or is weak.","re":"Leading on equality is a sign of strength and maturity, and it frees boys too.","why":"There are no 'sides' in fairness; everyone gains."},"relearn":"A boy leading on equality shows strength and maturity, not betrayal.","persona":"Arjun","source":"male allyship as strength (India reframe)"},
  {"id":"lw-019","cat":"what-allyship-is","type":"strike-rewrite","hook":"\"Allyship is just posting a hashtag.\"","myth":{"un":"Allyship is just posting a hashtag.","re":"Real allyship is listening, amplifying, and showing up consistently, not a performance.","why":"Actions over time, not slogans, are what help."},"relearn":"Active allyship is listening, amplifying and showing up, not a hashtag.","persona":"any","source":"active allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-020","type":"sort","hook":"Sort: active allyship, or just performance?","items":[{"id":"a","text":"Listening to those affected"},{"id":"b","text":"A one-off post for likes"},{"id":"c","text":"Amplifying a silenced voice"},{"id":"d","text":"Claiming credit for 'caring'"},{"id":"e","text":"Showing up again next week"},{"id":"f","text":"Posting once, then nothing"}],"bins":[{"id":"active","label":"Active allyship","valence":"pos"},{"id":"perform","label":"Performance","valence":"neg"}],"key":{"a":"active","b":"perform","c":"active","d":"perform","e":"active","f":"perform"},"relearn":"Listening, amplifying and showing up are active allyship; posts-for-likes are performance.","source":"active allyship"},
  {"id":"lw-021","cat":"what-allyship-is","type":"reflect","hook":"Lensy: allyship is using whatever influence you have, however small, for others. Feel able to do that?","prompt":"What do you think?","options":["Yes","Even a little","I can do that"],"affirm":"Whatever influence you have, used for others, is exactly what allyship means.","relearn":"Allyship is using your influence, however small, for others.","persona":"any","source":"allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-022","type":"match","hook":"Match the ally action to what it is.","pairs":[{"left":"Listen","right":"Hear those affected first"},{"left":"Amplify","right":"Boost a silenced voice"},{"left":"Show up","right":"Be there consistently"},{"left":"Credit","right":"Name whose idea it was"},{"left":"Step back","right":"Let them lead it"}],"relearn":"Listen, amplify, show up, credit and step back are the core ally moves.","source":"ally toolkit"},
  {"id":"lw-023","cat":"what-allyship-is","type":"reflect","hook":"Lensy: men leading on equality being seen as strength, why does that matter so much here?","prompt":"What do you think?","options":["It brings everyone in","Change needs all of us","It frees boys too"],"affirm":"When male allyship is seen as strength, half the population joins the work, that's huge.","relearn":"Framing male allyship as strength brings everyone into the work.","persona":"Vijay","source":"male allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-024","type":"sort","hook":"Sort: a real ally, or a bystander?","items":[{"id":"a","text":"Backs a colleague who's overlooked"},{"id":"b","text":"Stays silent to stay comfortable"},{"id":"c","text":"Shares the mic with others"},{"id":"d","text":"Waits for someone else to act"},{"id":"e","text":"Names who really had the idea"},{"id":"f","text":"Scrolls past the unfair joke"}],"bins":[{"id":"ally","label":"Ally","valence":"pos"},{"id":"bystander","label":"Bystander","valence":"neg"}],"key":{"a":"ally","b":"bystander","c":"ally","d":"bystander","e":"ally","f":"bystander"},"relearn":"Backing people, sharing the mic and crediting ideas is allyship; silence and waiting is bystanding.","source":"ally vs bystander"},
  {"id":"lw-025","cat":"what-allyship-is","type":"strike-rewrite","hook":"\"Helping others get ahead means you fall behind.\"","myth":{"un":"Helping others get ahead means you fall behind.","re":"Lifting others builds trust, teams and respect; leadership isn't a fixed pie.","why":"Good leaders are measured by who rises with them."},"relearn":"Lifting others doesn't hold you back; it's what real leadership is.","persona":"any","source":"not zero-sum / leadership"},
  {"id":"lw-026","cat":"what-allyship-is","type":"reflect","hook":"Lensy: allyship isn't about being a hero for people, it's standing with them. Feel the difference?","prompt":"What do you think?","options":["Yes","With, not for","Big difference"],"affirm":"Standing with people, led by them, is allyship; 'saving' them isn't.","relearn":"Allyship is standing with people, led by them, not 'saving' them.","persona":"any","source":"allyship humility"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-027","type":"spot","hook":"Spot the 2 moves that aren't real allyship.","scene":[{"id":"a","text":"Crediting whose idea it was","trick":false},{"id":"b","text":"Speaking over them to 'help'","trick":true},{"id":"c","text":"Making space for them to speak","trick":false},{"id":"d","text":"Taking credit for their idea","trick":true},{"id":"e","text":"Asking what would help first","trick":false}],"why":"Speaking over someone and taking their credit aren't allyship, even when they feel helpful.","relearn":"Crediting and making space is allyship; speaking over or taking credit isn't.","source":"ally moves"},
  {"id":"lw-028","cat":"what-allyship-is","type":"reflect","hook":"Lensy: what kind of ally do you want to be?","prompt":"Pick one.","options":["One who listens","One who amplifies","One who shows up","All of these"],"affirm":"Listening, amplifying and showing up, that's an ally the world needs.","relearn":"You can be an ally who listens, amplifies and shows up.","persona":"any","source":"identity"},
  {"id":"lw-029","cat":"what-allyship-is","type":"strike-rewrite","hook":"\"One person can't change anything.\"","myth":{"un":"One person can't change anything.","re":"One person leading by example and lifting one other shifts the whole room.","why":"Norms change one steady example at a time."},"relearn":"One person, leading and lifting one other, can shift the room.","persona":"any","source":"agency"},
  {"id":"lw-030","cat":"lead-by-example","type":"branch","hook":"At home, chores are split unequally by gender. You want to lead.","options":[{"text":"Share the load yourself, visibly and without being asked","consequence":"Your example quietly shifts the family norm.","outcome":"example","best":true},{"text":"Just complain that it's unfair","consequence":"Modelling the fair split yourself leads more than complaining."}],"debrief":"Doing your fair share, visibly, sets a norm others follow.","relearn":"Lead by example: share the load yourself, without being asked.","persona":"Arjun","source":"lead by example / unpaid care"},
  {"id":"lw-031","cat":"lead-by-example","type":"branch","hook":"A demeaning joke about girls lands in your group, everyone laughs.","options":[{"text":"Don't laugh; let your non-reaction set a different tone","consequence":"Your quiet example makes others reconsider.","outcome":"example","best":true},{"text":"Laugh along to fit in","consequence":"Even not laughing sets a tone; you don't have to join in."}],"debrief":"Refusing to laugh is a small, powerful act of leadership.","relearn":"Not laughing at a demeaning joke quietly sets a better norm.","persona":"any","source":"lead by example"},
  {"id":"lw-032","cat":"lead-by-example","type":"branch","hook":"In a group project, people assume the girls will take notes and the boys will present.","options":[{"text":"Suggest roles by skill and interest, and model it","consequence":"You break the default and others follow.","outcome":"example","best":true},{"text":"Go along with the gendered split","consequence":"Assigning roles by skill, not gender, leads by example."}],"debrief":"Quietly assigning roles fairly resets the group's assumptions.","relearn":"Assign roles by skill, not gender, and model the fairer way.","persona":"Sneha","source":"lead by example"},
  {"id":"lw-033","cat":"lead-by-example","type":"reflect","hook":"Lensy: your everyday behaviour is the norm others quietly copy. Powerful, isn't it?","prompt":"What do you think?","options":["Yes","I set a norm","Quietly powerful"],"affirm":"People copy what they see; your consistent example is real influence.","relearn":"Your everyday behaviour sets a norm others quietly follow.","persona":"any","source":"norm-setting"},
  {"id":"lw-034","cat":"lead-by-example","type":"spot","persona":"any","source":"consistency","relearn":"Real example is consistent respect, not a show put on only when watched.","hook":"Spot the two moves that only look like leadership but aren't.","scene":[{"id":"a","text":"Speaking respectfully to everyone, every day","trick":false},{"id":"b","text":"Only sharing chores when a relative visits","trick":true},{"id":"c","text":"Sharing the load at home without being asked","trick":false},{"id":"d","text":"Acting fair on camera, unfair off it","trick":true},{"id":"e","text":"Same respect for juniors and seniors","trick":false}],"why":"Being fair only when watched or filmed is a show, not leadership; real example is consistent."},
  {"id":"lw-035","cat":"lead-by-example","type":"branch","hook":"You realise people look to you in your friend group.","options":[{"text":"Use that influence to model respect and fairness","consequence":"The group's tone lifts with yours.","outcome":"influence","best":true},{"text":"Ignore it; it's not a responsibility","consequence":"If people look to you, modelling respect quietly raises the whole group."}],"debrief":"Influence you already have, used well, is leadership.","relearn":"If people look to you, model respect, your example leads.","persona":"Vijay","source":"influence"},
  {"id":"lw-036","cat":"lead-by-example","type":"reflect","hook":"Lensy: integrity, doing the fair thing even when no one's watching, is the heart of leading by example. Agree?","prompt":"What do you think?","options":["Yes","Integrity matters","Even unwatched"],"affirm":"Doing right unwatched is exactly the integrity that makes an example worth following.","relearn":"Integrity, fairness even when unwatched, is the heart of leading by example.","persona":"any","source":"integrity"},
  {"id":"lw-037","cat":"lead-by-example","type":"branch","hook":"A younger sibling watches how you treat people.","options":[{"text":"Model the respect and fairness you'd want them to learn","consequence":"They grow up with a better default.","outcome":"legacy","best":true},{"text":"Behave however, they'll figure it out","consequence":"Younger ones copy you; model the fairness you want them to learn."}],"debrief":"You're already teaching by example, choose what you teach.","relearn":"Model for younger ones the respect and fairness you want them to learn.","persona":"any","source":"role-modelling"},
  {"id":"lw-038","cat":"lead-by-example","type":"spot","persona":"any","source":"what lands","relearn":"A consistent, humble example lands; one-off gestures and credit-seeking don't.","hook":"Spot the two things that stop an example from actually landing.","scene":[{"id":"a","text":"Doing the fair thing consistently over time","trick":false},{"id":"b","text":"One big gesture, then back to old habits","trick":true},{"id":"c","text":"Quietly leading without seeking credit","trick":false},{"id":"d","text":"Loudly announcing how fair you are","trick":true},{"id":"e","text":"Owning your slip-ups and correcting them","trick":false}],"why":"A one-off gesture and loud credit-seeking undercut the example; steady, humble action lands."},
  {"id":"lw-039","cat":"lead-by-example","type":"reflect","hook":"Lensy: small, steady acts of respect, do they really add up to leadership?","prompt":"What do you think?","options":["Yes","They add up","Steady wins"],"affirm":"Small steady acts, repeated, are how norms, and leaders, are actually made.","relearn":"Small, steady acts of respect add up to real leadership.","persona":"any","source":"steady leadership"},
  {"id":"lw-040","cat":"lead-by-example","type":"branch","hook":"Setting a fair example might make you briefly stand out from the crowd.","options":[{"text":"Lead anyway; the right people respect it","consequence":"You set a standard others quietly admire.","outcome":"brave","best":true},{"text":"Blend in to avoid standing out","consequence":"Leading by example may stand out at first, but it earns real respect."}],"debrief":"Standing slightly apart to do right is what leaders do.","relearn":"Lead by example even if it means briefly standing out.","persona":"any","source":"courage"},
  {"id":"lw-041","cat":"lead-by-example","type":"role-play","hook":"You want to gently model fairer language in your group.","setup":"Lead by how you speak. Say:","yourLine":[{"text":"\"Let's hear from everyone, not just the loudest few.\"","best":true},{"text":"Let the same people dominate"}],"relearn":"Modelling inclusive language, like inviting quieter voices, leads gently.","persona":"any","source":"modelling"},
  {"id":"lw-042","cat":"lead-by-example","type":"reflect","hook":"Lensy: people remember how you made them feel. What example do you want to leave?","prompt":"Pick one.","options":["Respected","Included","Encouraged"],"affirm":"Leaving people feeling respected, included and encouraged is leadership at its best.","relearn":"The example worth leaving makes people feel respected and included.","persona":"any","source":"legacy"},
  {"id":"lw-043","cat":"lead-by-example","type":"sort","persona":"any","source":"example","relearn":"Equal treatment and fair sharing set the example; mocking and credit-taking undercut it.","hook":"Sort: sets a strong example, or undercuts it?","items":[{"id":"a","text":"Treating all genders equally"},{"id":"b","text":"Mocking someone behind their back"},{"id":"c","text":"Sharing the housework fairly"},{"id":"d","text":"Taking credit for a teammate's idea"},{"id":"e","text":"Owning a mistake and fixing it"},{"id":"f","text":"Laughing at a demeaning joke to fit in"}],"bins":[{"id":"strong","label":"Strong example","valence":"pos"},{"id":"under","label":"Undercuts it","valence":"neg"}],"key":{"a":"strong","b":"under","c":"strong","d":"under","e":"strong","f":"under"}},
  {"id":"lw-044","cat":"lift-as-you-climb","type":"branch","hook":"A capable but shy classmate keeps getting overlooked.","options":[{"text":"Mentor and encourage them toward chances they'd skip","consequence":"They grow in confidence and step up.","outcome":"lift","best":true},{"text":"Focus only on your own progress","consequence":"Lifting someone overlooked is the heart of real leadership."}],"debrief":"Mentoring someone with less confidence is leadership in action.","relearn":"Lift as you climb: mentor and encourage those who get overlooked.","persona":"Sneha","source":"lift as you climb"},
  {"id":"lw-045","cat":"lift-as-you-climb","type":"branch","hook":"In a meeting, someone's idea is ignored, then repeated by another and praised.","options":[{"text":"Credit the original person: 'that was her idea earlier'","consequence":"The right person gets the recognition.","outcome":"amplify","best":true},{"text":"Say nothing","consequence":"Crediting the original voice is a powerful, simple lift."}],"debrief":"Amplifying and crediting a talked-over voice is everyday leadership.","relearn":"Credit the person whose idea it was; amplify talked-over voices.","persona":"Vijay","source":"amplify"},
  {"id":"lw-046","cat":"lift-as-you-climb","type":"branch","hook":"A girl in your group was steered away from a subject she's great at.","options":[{"text":"Encourage her toward it and back her up","consequence":"She reconsiders a door she'd been pushed from.","outcome":"open-door","best":true},{"text":"Assume she made her choice","consequence":"Encouraging someone toward a steered-away role can change their path."}],"debrief":"Opening a door someone was pushed from is real leadership.","relearn":"Encourage people toward roles and subjects they were steered from.","persona":"Arjun","source":"sharing opportunity"},
  {"id":"lw-047","cat":"lift-as-you-climb","type":"role-play","hook":"You want to amplify a quieter teammate's point.","setup":"Pass them the mic. Say:","yourLine":[{"text":"\"I think Priya had a great point earlier, Priya, can you say more?\"","best":true},{"text":"Move on without them"}],"relearn":"Handing the mic back to a quieter voice amplifies them.","persona":"any","source":"amplify voice"},
  {"id":"lw-048","cat":"lift-as-you-climb","type":"role-play","hook":"You want to encourage someone who doubts they belong in a role.","setup":"Back them genuinely. Say:","yourLine":[{"text":"\"You'd be great at this, and I'll back you if you go for it.\"","best":true},{"text":"\"It's probably not for you.\""}],"relearn":"Genuine encouragement plus backing helps someone step up.","persona":"Sneha","source":"encouragement"},
  {"id":"lw-049","cat":"lift-as-you-climb","type":"role-play","hook":"You're praised for a team result and want to share the credit.","setup":"Spread it. Say:","yourLine":[{"text":"\"Thanks, but this was a team effort, especially Anil and Meena.\"","best":true},{"text":"Take all the credit yourself"}],"relearn":"Sharing credit lifts others and builds trust.","persona":"any","source":"share credit"},
  {"id":"lw-050","cat":"lift-as-you-climb","type":"reflect","hook":"Lensy: real leadership is measured by who rises with you. Sit with that.","prompt":"What do you think?","options":["I like that","Who rises with me","That's the measure"],"affirm":"Lifting others as you go, that's the truest measure of a leader.","relearn":"Real leadership is measured by who rises with you.","persona":"any","source":"lift as you climb"},
  {"id":"lw-051","cat":"lift-as-you-climb","type":"branch","hook":"You have a chance or platform someone else could really use.","options":[{"text":"Share or pass the opportunity to someone who'd benefit","consequence":"You open a door and grow a future leader.","outcome":"share","best":true},{"text":"Keep every opportunity for yourself","consequence":"Sharing opportunity, when you can, is how the gap closes."}],"debrief":"Deliberately shared opportunity is exactly how gaps actually close.","relearn":"Share opportunity and platforms with those who'd benefit.","persona":"any","source":"sharing opportunity (links g26)"},
  {"id":"lw-052","cat":"lift-as-you-climb","type":"sort","persona":"any","source":"lift vs hold","relearn":"Mentoring, crediting and amplifying lift; hoarding, talking over and taking credit hold people down.","hook":"Sort: lifts others, or holds them down?","items":[{"id":"a","text":"Mentoring someone newer"},{"id":"b","text":"Hoarding all the chances"},{"id":"c","text":"Crediting people's ideas"},{"id":"d","text":"Talking over quieter people"},{"id":"e","text":"Amplifying a talked-over voice"},{"id":"f","text":"Taking sole credit for a team win"}],"bins":[{"id":"lifts","label":"Lifts others","valence":"pos"},{"id":"holds","label":"Holds them down","valence":"neg"}],"key":{"a":"lifts","b":"holds","c":"lifts","d":"holds","e":"lifts","f":"holds"}},
  {"id":"lw-053","cat":"lift-as-you-climb","type":"reflect","hook":"Lensy: who lifted you, and could you do that for someone else?","prompt":"Think of it.","options":["Yes, I can","I want to","Pass it on"],"affirm":"Passing on the lift you got is how leadership multiplies.","relearn":"You can pass on the lift others gave you to someone else.","persona":"any","source":"pay it forward"},
  {"id":"lw-054","cat":"lift-as-you-climb","type":"branch","hook":"A talented friend won't apply for something, sure they'll be rejected.","options":[{"text":"Encourage them and help them prepare","consequence":"They apply, and whatever happens, they grow.","outcome":"encourage","best":true},{"text":"Agree they'd probably fail","consequence":"Encouraging and helping them prepare lifts them to try."}],"debrief":"A nudge and some help can change whether someone even tries.","relearn":"Encourage a doubting friend to try, and help them prepare.","persona":"any","source":"encouragement"},
  {"id":"lw-055","cat":"lift-as-you-climb","type":"role-play","hook":"You notice a teammate is always assigned the 'background' tasks.","setup":"Open a bigger door. Say:","yourLine":[{"text":"\"You should lead the next part, you've earned it.\"","best":true},{"text":"Leave the pattern as it is"}],"relearn":"Offering someone a bigger role breaks a limiting pattern.","persona":"any","source":"opportunity"},
  {"id":"lw-056","cat":"lift-as-you-climb","type":"reflect","hook":"Lensy: lifting one person well can ripple out to many. Believe it?","prompt":"What do you think?","options":["Yes","It ripples","One at a time"],"affirm":"Lift one person, and they often go on to lift others, that's how it spreads.","relearn":"Lifting one person well can ripple out to many.","persona":"any","source":"ripple"},
  {"id":"lw-057","cat":"lift-as-you-climb","type":"match","persona":"any","source":"lift toolkit","relearn":"Mentoring, amplifying, sharing opportunity, crediting and encouraging each lift someone concretely.","hook":"Match the lift to what it does.","pairs":[{"left":"Mentor","right":"Builds someone's confidence"},{"left":"Amplify","right":"Gets a quiet voice heard"},{"left":"Share opportunity","right":"Opens a closed door"},{"left":"Credit","right":"Makes the real author seen"},{"left":"Encourage","right":"Helps a doubter try"}]},
  {"id":"lw-058","cat":"lift-as-you-climb","type":"branch","hook":"You could quietly take sole credit, or name everyone who helped.","options":[{"text":"Name everyone who contributed","consequence":"People feel seen and trust you more.","outcome":"generous","best":true},{"text":"Take sole credit","consequence":"Naming contributors lifts them and marks a real leader."}],"debrief":"Generosity with credit is a quiet superpower of good leaders.","relearn":"Name everyone who helped; generous credit lifts people.","persona":"any","source":"credit"},
  {"id":"lw-059","cat":"lift-as-you-climb","type":"reflect","hook":"Lensy: 'lift as you climb', could that be your leadership motto?","prompt":"What do you think?","options":["Yes","Love it","My motto"],"affirm":"Lift as you climb, a motto that makes everyone, including you, rise.","relearn":"'Lift as you climb' is leadership that makes everyone rise.","persona":"any","source":"motto"},
  {"id":"lw-060","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"Publicly shaming someone is the best way to change them.\"","myth":{"un":"Publicly shaming someone is the best way to change them.","re":"A respectful 'call-in', often private and good-faith, changes minds better than a shaming 'call-out'.","why":"Shame usually makes people defensive and dig in."},"relearn":"A respectful call-in changes minds better than public shaming.","persona":"any","source":"call-in vs call-out"},
  {"id":"lw-061","cat":"call-in-not-out","type":"branch","hook":"A friend says something sexist, probably without thinking.","options":[{"text":"Call them in privately and with good faith","consequence":"They hear it and reconsider, without getting defensive.","outcome":"call-in","best":true},{"text":"Blast them publicly to make a point","consequence":"A private, good-faith call-in usually persuades better than a public blast."}],"debrief":"Assuming good faith and talking privately is the persuasive route.","relearn":"Call a friend in privately and in good faith, not out publicly.","persona":"Arjun","source":"call-in"},
  {"id":"lw-062","cat":"call-in-not-out","type":"role-play","hook":"You want to challenge a sexist joke without a big confrontation.","setup":"Keep it light but clear. Say:","yourLine":[{"text":"\"Hey, that one didn't sit right with me, can we not?\"","best":true},{"text":"Laugh, then complain later to others"}],"relearn":"'That didn't sit right, can we not?' is a clear, low-drama call-in.","persona":"any","source":"call-in voice"},
  {"id":"lw-063","cat":"call-in-not-out","type":"role-play","hook":"A teammate keeps interrupting the women in the group.","setup":"Address it constructively. Say:","yourLine":[{"text":"\"Let's let her finish, I want to hear the whole point.\"","best":true},{"text":"Say nothing and let it continue"}],"relearn":"A calm 'let her finish' redirects without shaming.","persona":"Vijay","source":"constructive challenge"},
  {"id":"lw-064","cat":"call-in-not-out","type":"branch","hook":"Someone digs in defensively when challenged in front of others.","options":[{"text":"Shift to a private, good-faith chat later","consequence":"They can change without losing face.","outcome":"private","best":true},{"text":"Push harder in public","consequence":"Public pushing entrenches people; a private follow-up works better."}],"debrief":"Letting someone save face in private makes change possible.","relearn":"If someone digs in publicly, follow up privately and in good faith.","persona":"any","source":"face-saving"},
  {"id":"lw-065","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"Calling in is just being soft and letting things slide.\"","myth":{"un":"Calling in is just being soft and letting it slide.","re":"It's firm about the issue and kind to the person; it still names the problem clearly.","why":"You can be clear and respectful at once."},"relearn":"Calling in is firm on the issue and kind to the person, not soft.","persona":"any","source":"call-in"},
  {"id":"lw-066","cat":"call-in-not-out","type":"branch","hook":"Something said is serious and harmful, not just clumsy.","options":[{"text":"Name it firmly and clearly; some things must be","consequence":"You draw a clear line where it's needed.","outcome":"firm","best":true},{"text":"Stay gentle to avoid friction","consequence":"Call-in is the default, but serious harm should be named firmly."}],"debrief":"Call-in is the default; serious harm still needs a firm, clear line.","relearn":"Some serious things must be named firmly; call-in isn't always enough.","persona":"Counsellor","source":"firm when needed"},
  {"id":"lw-067","cat":"call-in-not-out","type":"branch","hook":"Challenging someone could put your safety at risk.","options":[{"text":"Put safety first; use a safe move or get help instead","consequence":"You stay safe and still don't endorse it.","outcome":"safe","best":true},{"text":"Confront them regardless","consequence":"Safety comes first; for risk, use a safe move or get help (as in Stand Up)."}],"debrief":"Constructive challenge is for safe situations; danger calls for safe-intervention rules.","relearn":"Safety first: if challenging is unsafe, use a safe move or get help.","persona":"any","source":"safety-first (links g27)"},
  {"id":"lw-068","cat":"call-in-not-out","type":"sort","hook":"Sort: a constructive call-in, or a shaming call-out?","items":[{"id":"a","text":"A private, good-faith word"},{"id":"b","text":"Public humiliation"},{"id":"c","text":"'Can we rethink that?'"},{"id":"d","text":"Mocking them to a crowd"},{"id":"e","text":"Catching them quietly afterward"},{"id":"f","text":"Posting their slip to shame them"}],"bins":[{"id":"in","label":"Call-in","valence":"pos"},{"id":"out","label":"Shaming call-out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Private, good-faith, 'let's rethink' is call-in; public mockery is shaming.","persona":"any","source":"call-in vs call-out"},
  {"id":"lw-069","cat":"call-in-not-out","type":"reflect","hook":"Lensy: the goal isn't to win the argument, it's to actually change the room over time. See it?","prompt":"What do you think?","options":["Yes","The long game","Change over winning"],"affirm":"Playing the long game, persuading, not 'winning', is how peer groups really shift.","relearn":"The goal is to change minds over time, not to win an argument.","persona":"any","source":"long game"},
  {"id":"lw-070","cat":"call-in-not-out","type":"role-play","hook":"You want to invite someone to do better, assuming good faith.","setup":"Open the door, don't slam it. Say:","yourLine":[{"text":"\"I don't think you meant it badly, but here's how it landed.\"","best":true},{"text":"\"You're a sexist and everyone should know.\""}],"relearn":"Assuming good faith and explaining the impact invites change.","persona":"any","source":"good faith"},
  {"id":"lw-071","cat":"call-in-not-out","type":"reflect","hook":"Lensy: calling in takes more patience than calling out, but works better. Worth it?","prompt":"What do you think?","options":["Yes","Worth the patience","Better results"],"affirm":"The patience of calling-in is what actually shifts people for good.","relearn":"Calling in takes patience but changes people more lastingly.","persona":"any","source":"patience"},
  {"id":"lw-072","cat":"call-in-not-out","type":"sort","hook":"Sort: helps change a mind, or hardens it?","items":[{"id":"a","text":"Respect and good faith"},{"id":"b","text":"Public humiliation"},{"id":"c","text":"Explaining the impact"},{"id":"d","text":"Name-calling"},{"id":"e","text":"Offering a way forward"},{"id":"f","text":"Dragging up old mistakes"}],"bins":[{"id":"change","label":"Helps change","valence":"pos"},{"id":"harden","label":"Hardens them","valence":"neg"}],"key":{"a":"change","b":"harden","c":"change","d":"harden","e":"change","f":"harden"},"relearn":"Respect, impact, and a way forward change minds; humiliation and name-calling harden them.","persona":"any","source":"persuasion"},
  {"id":"lw-073","cat":"your-leadership-style","type":"reflect","hook":"Lensy: leadership comes in many styles, what feels most like you?","prompt":"Pick one.","options":["Quiet example","Encouraging others","Speaking up","Connecting people"],"affirm":"Your authentic style, whatever it is, is a real and valuable way to lead.","relearn":"Leadership has many styles; yours is authentic and valuable.","persona":"any","source":"authentic style"},
  {"id":"lw-074","cat":"your-leadership-style","type":"reflect","hook":"Lensy: leading from your own values beats copying someone else's style. Agree?","prompt":"What do you think?","options":["Yes","From my values","Be myself"],"affirm":"Leading from your values is what makes your leadership real and sustainable.","relearn":"Lead from your own values, not a copied style.","persona":"any","source":"values-based"},
  {"id":"lw-075","cat":"your-leadership-style","type":"branch","hook":"You want a concrete first step to lead on equality.","options":[{"text":"Pick one small, specific action you'll actually do this week","consequence":"You turn intention into a real start.","outcome":"plan","best":true},{"text":"Wait until you feel fully ready","consequence":"One small, specific action beats waiting to feel 'ready'."}],"debrief":"A concrete small step is how leadership actually begins.","relearn":"Pick one small, specific action to start leading this week.","persona":"any","source":"action plan"},
  {"id":"lw-076","cat":"your-leadership-style","type":"branch","hook":"You're choosing where to focus your leadership energy.","options":[{"text":"Start where you already have influence (home, group, team)","consequence":"You lead effectively in your real circles.","outcome":"realistic","best":true},{"text":"Wait for a big public stage","consequence":"Lead first where you already have influence; that's where change starts."}],"debrief":"Your everyday circles are where your leadership is most real.","relearn":"Lead where you already have influence: home, group, team.","persona":"any","source":"where to lead"},
  {"id":"lw-077","cat":"your-leadership-style","type":"role-play","hook":"You're rallying a friend to lead alongside you.","setup":"Invite them in. Say:","yourLine":[{"text":"\"Let's set the tone together, it's easier and better with two.\"","best":true},{"text":"Try to do it all alone"}],"relearn":"Inviting others to lead with you multiplies the effect.","persona":"any","source":"collective"},
  {"id":"lw-078","cat":"your-leadership-style","type":"reflect","hook":"Lensy: which part of leading do you most want to grow?","prompt":"Pick one.","options":["Leading by example","Lifting others","Calling in well","Knowing my style"],"affirm":"Growing any one of those makes you a stronger, kinder leader.","relearn":"Example, lifting, calling-in and self-knowledge are all parts of leading.","persona":"any","source":"growth"},
  {"id":"lw-079","cat":"your-leadership-style","type":"branch","hook":"You're a boy unsure if 'leading on equality' is your place.","options":[{"text":"Claim it, your leadership here is strength, and it's needed","consequence":"You bring half the room into the work.","outcome":"strength","best":true},{"text":"Leave it to others","consequence":"A boy leading on equality is strength, and exactly what moves the needle."}],"debrief":"Boys leading on equality is one of the most powerful things this game asks for.","relearn":"Leading on equality as a boy is strength, and it's needed.","persona":"Vijay","source":"male allyship"},
  {"id":"lw-080","cat":"your-leadership-style","type":"reflect","hook":"Lensy: you can lead in ways that respect your family and community, not against them. Reassuring?","prompt":"What do you think?","options":["Yes","With respect","That fits"],"affirm":"Quiet example and call-in let you lead while respecting the people around you.","relearn":"You can lead for equality in ways that respect family and community.","persona":"any","source":"India / respectful leadership"},
  {"id":"lw-081","cat":"your-leadership-style","type":"reflect","hook":"Lensy: India has its own role models who led for fairness across science, sport and reform. Inspiring?","prompt":"What do you think?","options":["Yes","Inspiring","Our own leaders"],"affirm":"You stand in a long line of Indian changemakers, you can join it.","relearn":"India has its own role models of leadership for fairness to draw on.","persona":"any","source":"India role models"},
  {"id":"lw-082","cat":"your-leadership-style","type":"branch","hook":"You finish the game and want it to actually change something.","options":[{"text":"Commit to one real action and one person you'll lift","consequence":"Your learning becomes a difference in the world.","outcome":"commit","best":true},{"text":"File it away as 'nice to know'","consequence":"One action and one person lifted turns learning into change."}],"debrief":"A concrete commitment is what turns a game into real leadership.","relearn":"Commit to one action and one person to lift; make it real.","persona":"any","source":"commitment"},
  {"id":"lw-083","cat":"your-leadership-style","type":"reflect","hook":"Lensy: biggest take-away from Lead the Way?","prompt":"Pick your motto.","options":["No title needed to lead","Lift as you climb","Allyship is everyone's job","Call in, not out"],"affirm":"Any of those, lived out, makes you the quiet leader this world needs.","relearn":"Lead without a title, lift as you climb, ally for all, call in not out.","persona":"any","source":"consolidation"},
  {"id":"lw-084","cat":"your-leadership-style","type":"reflect","hook":"Lensy: a generation of quiet leaders and active allies, worth being part of?","prompt":"What do you think?","options":["Yes","Count me in","Let's lead"],"affirm":"Every quiet leader and active ally helps build a fairer world, starting with you.","relearn":"Being a quiet leader and active ally helps build a fairer world.","persona":"any","source":"vision"},
  {"id":"lw-1260","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"If you don't roast someone publicly, they'll never learn.\"","myth":{"un":"If you don't roast someone publicly, they'll never learn.","re":"A quiet, private word, assuming they meant no harm, teaches far better than a public roast.","why":"Public roasting makes people defend their pride instead of hearing you."},"relearn":"A private, good-faith word teaches better than a public roast.","persona":"any","source":"call-in vs call-out"},
  {"id":"lw-1261","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"Calling someone in just protects them from consequences.\"","myth":{"un":"Calling someone in just protects them from consequences.","re":"It still names the problem clearly. It just gives the person a path to change instead of only shame.","why":"Naming the issue and offering a way forward changes behaviour, not just mood."},"relearn":"Calling in names the problem and offers a way to change.","persona":"Sneha","source":"call-in is not silence"},
  {"id":"lw-1262","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"Pulling someone aside is sneaky. Say it to their face in the group.\"","myth":{"un":"Pulling someone aside is sneaky. Say it to their face in the group.","re":"A private aside isn't sneaky; it lets them rethink without the whole room watching them lose face.","why":"People hear feedback better when their pride isn't on public display."},"relearn":"A private aside lets someone rethink without losing face.","persona":"any","source":"private call-in"},
  {"id":"lw-1263","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"Being polite about it means you're scared to confront them.\"","myth":{"un":"Being polite about it means you're scared to confront them.","re":"Staying calm and respectful is a choice of strength. You're firm on the issue and steady with the person.","why":"Calm firmness lands harder and lasts longer than heat."},"relearn":"Calm respect is strength, not fear: firm issue, steady tone.","persona":"Vijay","source":"calm is strength"},
  {"id":"lw-1264","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"Screenshot it and post it so everyone sees what he said.\"","myth":{"un":"Screenshot it and post it so everyone sees what he said.","re":"Posting it to shame him entrenches him; a private message about how it landed is more likely to change him.","why":"Public exposure triggers defence; private feedback invites a rethink."},"relearn":"Shaming a screenshot entrenches; a private note about impact changes minds.","persona":"any","source":"public shaming entrenches"},
  {"id":"lw-1265","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"If he doesn't apologise instantly, the call-in failed.\"","myth":{"un":"If he doesn't apologise instantly, the call-in failed.","re":"Minds usually shift slowly. A good call-in plants a seed; the change often shows up later, not on the spot.","why":"Real reflection takes time; an instant reaction isn't the only sign it worked."},"relearn":"A call-in plants a seed; change often shows up later, not instantly.","persona":"any","source":"the long game"},
  {"id":"lw-1266","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"Calling in is just letting harmful people off easy.\"","myth":{"un":"Calling in is just letting harmful people off easy.","re":"Serious harm still gets named firmly. Call-in is the default for honest slips, not a free pass for real harm.","why":"You can be persuasive with a slip and firm with genuine harm."},"relearn":"Call-in is the default for honest slips; real harm is named firmly.","persona":"Counsellor","source":"firm when needed"},
  {"id":"lw-1267","cat":"call-in-not-out","type":"strike-rewrite","hook":"\"Tell off the relative at dinner so the whole family hears it.\"","myth":{"un":"Tell off the relative at dinner so the whole family hears it.","re":"A quiet word later, respecting the relationship, usually shifts an elder more than a scene at the table.","why":"Public confrontation in a family hardens elders; a respectful aside keeps the door open."},"relearn":"A respectful private word shifts a relative better than a family scene.","persona":"any","source":"respect family relationships"},
  {"id":"lw-1268","cat":"call-in-not-out","type":"branch","hook":"In the class group chat, a boy posts a 'girls can't drive' meme and everyone laughs.","options":[{"text":"DM him: 'Not a fan of that one. Can we skip those?'","consequence":"He drops it without the chat watching him back down.","outcome":"private","best":true},{"text":"Reply in the chat calling him sexist for all to see","consequence":"A public label makes him double down to save face."}],"debrief":"A private nudge in good faith moves a peer better than a public label.","relearn":"Message a peer privately and kindly, not call them out in the group.","persona":"any","source":"call-in (group chat)"},
  {"id":"lw-1269","cat":"call-in-not-out","type":"branch","hook":"A senior on your project team keeps calling the only girl 'the typist'.","options":[{"text":"After the meeting: 'She's our data lead. Let's use her title.'","consequence":"He hears it without an audience and uses her real role.","outcome":"private","best":true},{"text":"Snap at him in front of everyone","consequence":"A public snap at a senior just makes him defensive."}],"debrief":"A quiet, respectful correction protects her role without humiliating him.","relearn":"Correct a put-down privately and respectfully, even with a senior.","persona":"Sneha","source":"call-in (amplify + private)"},
  {"id":"lw-1270","cat":"call-in-not-out","type":"branch","hook":"Your friend jokes that your classmate 'throws like a girl'. He didn't mean harm.","options":[{"text":"Quietly: 'I know it's a joke, but it kind of puts girls down, na?'","consequence":"He sees the impact and eases off, no fight needed.","outcome":"good-faith","best":true},{"text":"Announce to the group that he's a sexist","consequence":"A public label makes him argue back, not listen."}],"debrief":"Assuming good faith and naming the impact invites a friend to rethink.","relearn":"Name the impact gently, assuming good faith, instead of labelling.","persona":"Vijay","source":"good faith + impact"},
  {"id":"lw-1271","cat":"call-in-not-out","type":"branch","hook":"A teammate keeps dismissing every idea the women raise in your fest committee.","options":[{"text":"Privately: 'Their ideas get cut fast. Can we hear them out?'","consequence":"He notices his pattern and gives ideas a fairer hearing.","outcome":"private","best":true},{"text":"Call him out mid-meeting for being biased","consequence":"A public charge makes him defend himself, not reflect."}],"debrief":"Naming a pattern privately, as something to fix together, opens change.","relearn":"Point out a pattern privately as a 'we' problem, not a public charge.","persona":"any","source":"call-in (pattern)"},
  {"id":"lw-1272","cat":"call-in-not-out","type":"branch","hook":"Someone you called in last week says, 'So now I can't even joke?'","options":[{"text":"'You can joke, just not at someone's expense. We're good.'","consequence":"Warm and clear: the relationship and the point both hold.","outcome":"warm","best":true},{"text":"'Obviously not, grow up.'","consequence":"A sharp reply turns your call-in into a fight."}],"debrief":"Holding the line warmly keeps both the person and the point.","relearn":"Hold the boundary warmly: joke, yes; at someone's cost, no.","persona":"any","source":"hold the line warmly"},
  {"id":"lw-1273","cat":"call-in-not-out","type":"branch","hook":"At a wedding, an uncle loudly says your cousin should 'drop her job after marriage'.","options":[{"text":"Quietly to him later: 'She loves her work. Let her choose.'","consequence":"You make the point without a public clash at the function.","outcome":"private","best":true},{"text":"Argue him down in front of all the guests","consequence":"A public argument embarrasses everyone and hardens him."}],"debrief":"A respectful private word respects the family and still makes the point.","relearn":"Make the point to a relative quietly, respecting the occasion.","persona":"any","source":"respect family + private"},
  {"id":"lw-1274","cat":"call-in-not-out","type":"branch","hook":"A junior copies your friend's design and presents it as his own to the club.","options":[{"text":"Ask him privately to credit her, and back her up if he won't","consequence":"He credits her; if not, you'll name it clearly: it's real harm.","outcome":"escalate-fairly","best":true},{"text":"Expose him on the club's notice board","consequence":"A public takedown is the call-out. Try the private ask first."}],"debrief":"Try the private ask first; if real harm stands, name it firmly.","relearn":"Ask privately first; escalate firmly only if the harm isn't fixed.","persona":"any","source":"call-in then firm"},
  {"id":"lw-1275","cat":"call-in-not-out","type":"branch","hook":"A boy in your hostel keeps 'rating' girls who walk past, getting laughs.","options":[{"text":"Pull him aside: 'That makes them uncomfortable. Let's drop it.'","consequence":"Without his audience, he hears it and stops performing.","outcome":"private","best":true},{"text":"Shame him loudly in front of his friends","consequence":"With an audience he plays up to it instead of stopping."}],"debrief":"Removing the audience and speaking privately ends the performance.","relearn":"Take away the audience: a private word stops the show.","persona":"Arjun","source":"private removes the stage"},
  {"id":"lw-1276","cat":"call-in-not-out","type":"branch","hook":"You realise YOU made a sexist joke and a friend looks uneasy.","options":[{"text":"'That came out wrong. My bad, scrap that one.'","consequence":"Owning it fast models the call-in you'd want from others.","outcome":"own-it","best":true},{"text":"Double down so you don't look soft","consequence":"Doubling down to save face is the pride that blocks change."}],"debrief":"Owning your own slip quickly is leadership, not weakness.","relearn":"When it's you, own it fast: that models the call-in for everyone.","persona":"any","source":"call yourself in"},
  {"id":"lw-1277","cat":"call-in-not-out","type":"branch","hook":"A classmate keeps 'correcting' a girl's English in front of others to look smart.","options":[{"text":"Later: 'She knows her stuff. That comes off as showing off.'","consequence":"He realises how it lands and eases off in good faith.","outcome":"private","best":true},{"text":"Mock his English back in the group","consequence":"Mocking him back is a public dunk, not a call-in."}],"debrief":"Naming how 'help' actually lands, in private, invites him to stop.","relearn":"Tell him privately how the 'correcting' really lands.","persona":"any","source":"call-in (impact)"},
  {"id":"lw-1278","cat":"call-in-not-out","type":"branch","hook":"Your group is about to pile onto one boy in the chat for a clumsy comment.","options":[{"text":"'One of us can DM him. A pile-on won't help.' Then message him","consequence":"You spare a pile-on and give him a chance to rethink.","outcome":"de-escalate","best":true},{"text":"Add your own jab to the pile","consequence":"Joining the pile-on is public shaming that just hardens him."}],"debrief":"Steering the group off a pile-on toward one private DM changes minds.","relearn":"Steer the group off a pile-on; one kind DM does more.","persona":"any","source":"stop the pile-on"},
  {"id":"lw-1279","cat":"call-in-not-out","type":"branch","hook":"A friend posts a long 'calling out' rant about a classmate's sexist line.","options":[{"text":"Suggest he message the classmate directly instead, in good faith","consequence":"A direct, private message is likelier to actually change him.","outcome":"private","best":true},{"text":"Like and amplify the rant","consequence":"Amplifying the rant feeds shame, which entrenches, not persuades."}],"debrief":"Nudging a friend from public rant to private message is the call-in.","relearn":"Nudge a public rant toward a direct, private good-faith message.","persona":"any","source":"redirect the rant"},
  {"id":"lw-1280","cat":"call-in-not-out","type":"branch","hook":"A coachmate says girls 'shouldn't be on the cricket pitch'. The captain's right there.","options":[{"text":"'They've earned their spot. Let's judge on play, not gender.'","consequence":"Said evenly, it sets a fair norm without a brawl.","outcome":"firm-calm","best":true},{"text":"Shout him down and call him pathetic","consequence":"Shouting him down turns it into a clash, not a changed mind."}],"debrief":"When it's said openly and now, a calm, firm line names it without shaming.","relearn":"Some lines need a calm, firm answer in the moment, not a shout.","persona":"Vijay","source":"firm + calm in the moment"},
  {"id":"lw-1281","cat":"call-in-not-out","type":"branch","hook":"A relative messages your family group: 'Why is Sneha studying so far from home?'","options":[{"text":"'She got a great seat on merit. We're proud of her.'","consequence":"You reframe with pride; the group follows your warm tone.","outcome":"reframe","best":true},{"text":"Call the relative backward in front of everyone","consequence":"Insulting the relative publicly hardens them and splits the family."}],"debrief":"Reframing with calm pride shifts a family group better than insults.","relearn":"Reframe with calm pride; don't insult a relative to defend someone.","persona":"any","source":"reframe in family group"},
  {"id":"lw-1282","cat":"call-in-not-out","type":"branch","hook":"You see a teammate sending a girl unwanted messages and she looks frightened.","options":[{"text":"Check she's okay, and bring in a trusted adult: safety first","consequence":"You don't confront alone when there's fear; you get safe backup.","outcome":"safe","best":true},{"text":"Confront him alone and aggressively","consequence":"Confronting alone when someone's scared can escalate the danger."}],"debrief":"When there's fear or risk, safety first: get a trusted adult, not a solo move.","relearn":"When someone's frightened, safety first: support her and get a trusted adult.","persona":"any","source":"safety-first (links g27)"},
  {"id":"lw-1283","cat":"call-in-not-out","type":"branch","hook":"You called a friend in once and he changed. Now he slips again with a new group.","options":[{"text":"Remind him once more, calmly, same good faith as before","consequence":"Patience over a few tries is how habits actually shift.","outcome":"patient","best":true},{"text":"Blast him for 'pretending' to have changed","consequence":"Blasting him erases the progress he made and pushes him away."}],"debrief":"A second calm reminder respects that change is gradual, not one-and-done.","relearn":"Change is gradual: a calm second reminder beats giving up or blasting.","persona":"any","source":"patience + the long game"},
  {"id":"lw-1284","cat":"call-in-not-out","type":"branch","hook":"At a debate, a speaker says feminists 'just hate men'. The room's tense.","options":[{"text":"'Equality lifts boys too. It's not against anyone.'","consequence":"You reframe without scorn; some listeners actually rethink.","outcome":"reframe","best":true},{"text":"Sneer that he's clearly threatened","consequence":"Sneering proves his 'they hate men' point and loses the room."}],"debrief":"Reframing equality as 'lifts everyone' persuades better than scorn.","relearn":"Reframe, don't sneer: equality lifts boys too, it's against no one.","persona":"any","source":"reframe not zero-sum"},
  {"id":"lw-1285","cat":"call-in-not-out","type":"role-play","hook":"A friend keeps using 'gay' as an insult and doesn't see the harm.","setup":"Keep it easy but honest. Say:","yourLine":[{"text":"\"Using 'gay' like that stings more than you'd think. Can we drop it?\"","best":true},{"text":"Laugh along and bring it up months later"}],"relearn":"Naming the sting gently, in good faith, invites a friend to drop it.","persona":"Arjun","source":"call-in voice"},
  {"id":"lw-1286","cat":"call-in-not-out","type":"role-play","hook":"Your study group keeps handing every girl the note-taking job by default.","setup":"Flag it lightly to the group. Say:","yourLine":[{"text":"\"Let's pick notes by who wants it, not by who's a girl. I'll go first.\"","best":true},{"text":"Roll your eyes and take the notes yourself in silence"}],"relearn":"A light 'let's pick by choice, not gender' resets the default kindly.","persona":"any","source":"call-in (default roles)"},
  {"id":"lw-1287","cat":"call-in-not-out","type":"role-play","hook":"An older cousin teases your brother for crying, 'be a man'.","setup":"Step in gently, no scene. Say:","yourLine":[{"text":"\"It's okay for him to cry: being a man isn't about hiding that.\"","best":true},{"text":"Agree so your cousin doesn't think you're soft too"}],"relearn":"A gentle 'it's okay to cry' frees boys and resets the room.","persona":"Vijay","source":"free boys too"},
  {"id":"lw-1288","cat":"call-in-not-out","type":"role-play","hook":"A teammate brags about 'not letting' his girlfriend talk to other guys.","setup":"Question it without a lecture. Say:","yourLine":[{"text":"\"Trusting her isn't weakness, yaar: controlling people isn't a flex.\"","best":true},{"text":"Nod along so the group stays chill"}],"relearn":"Naming control as not-a-flex, in good faith, invites a rethink.","persona":"any","source":"reframe control"},
  {"id":"lw-1289","cat":"call-in-not-out","type":"role-play","hook":"In a WhatsApp group, someone shares a 'send her location' joke about a girl.","setup":"Cool it down, don't blow up. Say:","yourLine":[{"text":"\"Let's not: that kind of joke isn't really funny for her.\"","best":true},{"text":"Send a laughing sticker and move on"}],"relearn":"A short 'let's not, not funny for her' cools a chat without a fight.","persona":"any","source":"call-in (chat)"},
  {"id":"lw-1290","cat":"call-in-not-out","type":"role-play","hook":"Your friend says a girl 'was asking for it' by what she wore.","setup":"This one needs a clear line, still calm. Say:","yourLine":[{"text":"\"No, clothes are never a reason. That's not okay to say.\"","best":true},{"text":"Change the subject so it doesn't get awkward"}],"relearn":"Some lines get a clear, firm 'no': call-in isn't staying silent.","persona":"any","source":"firm when needed"},
  {"id":"lw-1291","cat":"call-in-not-out","type":"role-play","hook":"A senior cuts off the only girl in the meeting, again.","setup":"Redirect without scolding him. Say:","yourLine":[{"text":"\"Hang on, she was mid-point. I want to hear the rest.\"","best":true},{"text":"Let it pass and tell her 'he's always like that' later"}],"relearn":"A calm 'she was mid-point' redirects without scolding anyone.","persona":"Sneha","source":"amplify + redirect"},
  {"id":"lw-1292","cat":"call-in-not-out","type":"role-play","hook":"A friend forwards you a meme mocking trans people, expecting a laugh.","setup":"Decline kindly and clearly. Say:","yourLine":[{"text":"\"Not my kind of joke: real people get hurt by those.\"","best":true},{"text":"React 'haha' to avoid a whole conversation"}],"relearn":"A clear 'not my kind of joke, because people get hurt' is a kind, firm call-in.","persona":"Arjun","source":"decline kindly"},
  {"id":"lw-1293","cat":"call-in-not-out","type":"role-play","hook":"At home, a relative says 'let the girls clear the plates' while boys sit.","setup":"Reset it by joining in. Say:","yourLine":[{"text":"\"I'll help clear too: no reason it's only the girls.\"","best":true},{"text":"Stay seated; it's how it's always been"}],"relearn":"Reset an unfair chore split by joining in, not by arguing.","persona":"Vijay","source":"lead by doing"},
  {"id":"lw-1294","cat":"call-in-not-out","type":"role-play","hook":"A classmate keeps asking a girl 'who's your dad' instead of judging her work.","setup":"Point back to the work. Say:","yourLine":[{"text":"\"Her project speaks for itself: let's talk about that.\"","best":true},{"text":"Shrug; it's not your business"}],"relearn":"Point the room back to her work instead of letting the dig stand.","persona":"any","source":"redirect to merit"},
  {"id":"lw-1295","cat":"call-in-not-out","type":"role-play","hook":"A friend says you're 'whipped' for splitting chores with your partner.","setup":"Own it with ease. Say:","yourLine":[{"text":"\"It's just fair, not whipped: try it, honestly.\"","best":true},{"text":"Laugh it off and stop helping when he's around"}],"relearn":"Owning fairness calmly turns a 'whipped' jab into a quiet example.","persona":"any","source":"own the example"},
  {"id":"lw-1296","cat":"call-in-not-out","type":"role-play","hook":"Younger boys in your team copy a slur they heard a senior use.","setup":"Set the norm for them, gently. Say:","yourLine":[{"text":"\"We don't talk about people like that here: let's keep it clean.\"","best":true},{"text":"Ignore it; they're just kids repeating stuff"}],"relearn":"Set the norm gently for juniors: 'we don't talk like that here'.","persona":"any","source":"set the norm"},
  {"id":"lw-1297","cat":"call-in-not-out","type":"sort","hook":"Sort each move: a good-faith call-in, or a shaming call-out?","items":[{"id":"a","text":"A private DM: 'that landed wrong, can we talk?'"},{"id":"b","text":"Posting his screenshot to mock him"},{"id":"c","text":"'I don't think you meant it, but here's the impact'"},{"id":"d","text":"Tagging the whole class to pile on"},{"id":"e","text":"Pulling him aside after the meeting"},{"id":"f","text":"Sneering 'everyone, look what he said'"}],"bins":[{"id":"in","label":"Call-in","valence":"pos"},{"id":"out","label":"Shaming call-out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Private, good-faith, impact-focused moves are call-ins; public mockery is shaming.","persona":"any","source":"call-in vs call-out"},
  {"id":"lw-1298","cat":"call-in-not-out","type":"sort","hook":"Sort each reaction: does it open a mind, or shut it down?","items":[{"id":"a","text":"Assuming he meant no harm"},{"id":"b","text":"Calling him a lost cause"},{"id":"c","text":"Explaining how it landed"},{"id":"d","text":"Mocking him to the group"},{"id":"e","text":"Giving him a way to fix it"},{"id":"f","text":"Bringing up his every past mistake"}],"bins":[{"id":"open","label":"Opens a mind","valence":"pos"},{"id":"shut","label":"Shuts it down","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Good faith, explaining impact, and a way to fix it open minds; mockery and pile-ons shut them.","persona":"any","source":"persuasion"},
  {"id":"lw-1299","cat":"call-in-not-out","type":"sort","hook":"Sort each one: handle as a gentle call-in, or name it firmly?","items":[{"id":"a","text":"A clumsy 'throws like a girl' joke"},{"id":"b","text":"Repeated unwanted messages that scare someone"},{"id":"c","text":"A relative's outdated comment at dinner"},{"id":"d","text":"Stealing and presenting a girl's work as his"},{"id":"e","text":"A friend's careless slip of a slur"},{"id":"f","text":"'She was asking for it' victim-blaming"}],"bins":[{"id":"gentle","label":"Gentle call-in","valence":"pos"},{"id":"firm","label":"Name it firmly","valence":"tell"}],"key":{"a":"gentle","b":"firm","c":"gentle","d":"firm","e":"gentle","f":"firm"},"relearn":"Honest slips get a gentle call-in; real harm and victim-blaming get named firmly.","persona":"Counsellor","source":"call-in vs firm"},
  {"id":"lw-1300","cat":"call-in-not-out","type":"sort","hook":"Sort each step of a calm call-in into when it happens.","items":[{"id":"a","text":"Notice the comment land badly"},{"id":"b","text":"Wait, then catch them privately"},{"id":"c","text":"Assume they meant no harm"},{"id":"d","text":"Say how it actually landed"},{"id":"e","text":"Offer a simple way forward"},{"id":"f","text":"Keep the relationship warm after"}],"bins":[{"id":"start","label":"At the moment","valence":"neutral"},{"id":"later","label":"In the private chat","valence":"pos"}],"key":{"a":"start","b":"start","c":"later","d":"later","e":"later","f":"later"},"relearn":"Notice and choose your moment first; then privately assume good faith, name impact, and stay warm.","persona":"any","source":"call-in steps"},
  {"id":"lw-1301","cat":"call-in-not-out","type":"reflect","hook":"Lensy: the win isn't making him feel small. It's that the room changes. Sit with that?","prompt":"What feels true for you?","options":["Yes","The room, not the burn","Change over winning"],"affirm":"Aiming at a changed room, not a burned person, is what makes leadership last.","relearn":"The goal is a changed room, not making someone feel small.","persona":"any","source":"the long game"},
  {"id":"lw-1302","cat":"call-in-not-out","type":"reflect","hook":"Lensy: sometimes you call someone in and nothing visibly changes. Still worth doing?","prompt":"Where do you land?","options":["Yes","Seeds take time","It mattered anyway"],"affirm":"Most call-ins are seeds: you rarely see the moment they sprout, and they still count.","relearn":"A call-in is worth it even when you don't see it land right away.","persona":"any","source":"patience"},
  {"id":"lw-1303","cat":"call-in-not-out","type":"reflect","hook":"Lensy: which is harder for you, staying calm or actually saying something at all?","prompt":"Be honest with yourself.","options":["Staying calm","Speaking up","Both, some days"],"affirm":"Knowing your own harder edge is how you grow into the kind of leader you want to be.","relearn":"Knowing whether calm or courage is your harder edge helps you grow.","persona":"any","source":"self-knowledge"},
  {"id":"lw-1304","cat":"call-in-not-out","type":"reflect","hook":"Lensy: when you've been called in kindly yourself, how did it feel after?","prompt":"What comes up?","options":["Relieved","A bit embarrassed","Glad someone bothered"],"affirm":"Remembering how a kind call-in felt for you is the best guide for how to give one.","relearn":"How a kind call-in felt for you is your best guide to giving one.","persona":"any","source":"empathy"},
  {"id":"lw-1305","cat":"call-in-not-out","type":"reflect","hook":"Lensy: is it okay to wait and pick a better moment, instead of reacting instantly?","prompt":"What do you think?","options":["Yes","Timing matters","A calm word later"],"affirm":"Choosing your moment isn't dodging: a calm word later often lands far better.","relearn":"Picking a calmer moment to speak is a fair, often better choice.","persona":"any","source":"timing"},
  {"id":"lw-1306","cat":"call-in-not-out","type":"reflect","hook":"Lensy: calling in a close friend can feel riskier than a stranger. Notice that?","prompt":"What's real for you?","options":["Yes","Harder with friends","Worth the care"],"affirm":"It's normal that it feels riskier with friends: caring enough to say it is the point.","relearn":"It can feel harder to call in a friend; caring enough to do it is leadership.","persona":"any","source":"friends are harder"},
  {"id":"lw-1307","cat":"call-in-not-out","type":"reflect","hook":"Lensy: you don't have to fix every comment you hear. Does that take some pressure off?","prompt":"How does that sit?","options":["Yes","Pick my battles","Some, not all"],"affirm":"Choosing where you spend your energy is wise: you can't and needn't catch everything.","relearn":"You can pick your moments; you needn't challenge every single comment.","persona":"any","source":"sustainable"},
  {"id":"lw-1308","cat":"call-in-not-out","type":"reflect","hook":"Lensy: after a call-in goes well, do you let the person off the hook warmly?","prompt":"What feels right?","options":["Yes","Keep it warm","Move on together"],"affirm":"Letting someone move on without grudges is what makes them open to you next time.","relearn":"Closing a call-in warmly keeps the person open to you next time.","persona":"any","source":"close it warmly"},
  {"id":"lw-1309","cat":"call-in-not-out","type":"match","hook":"Match each shaming call-out to the calmer call-in that works better.","pairs":[{"left":"'Everyone, look how sexist he is'","right":"A private 'hey, that didn't sit right'"},{"left":"Posting his screenshot to mock","right":"A direct DM about how it landed"},{"left":"'You're a lost cause'","right":"'I don't think you meant it badly'"},{"left":"Shouting him down in the room","right":"Catching him quietly afterward"},{"left":"Dragging up his every old slip","right":"Sticking to this one thing, kindly"}],"relearn":"Each public takedown has a calmer, private version that actually changes minds.","persona":"any","source":"call-out → call-in"},
  {"id":"lw-1310","cat":"call-in-not-out","type":"match","hook":"Match each situation to the right move.","pairs":[{"left":"A clumsy joke from a friend","right":"A gentle, good-faith call-in"},{"left":"Serious victim-blaming","right":"A clear, firm 'no, not okay'"},{"left":"Someone frightened and at risk","right":"Safety first: get a trusted adult"},{"left":"A relative's old-fashioned remark","right":"A respectful private word later"},{"left":"A pile-on forming in the chat","right":"Steer it to one kind DM"}],"relearn":"The move fits the moment: gentle for slips, firm for harm, safety first for risk.","persona":"Counsellor","source":"match move to moment"},
  {"id":"lw-1311","cat":"call-in-not-out","type":"match","hook":"Match each call-in line to what makes it work.","pairs":[{"left":"'I don't think you meant it badly'","right":"Assumes good faith"},{"left":"'Here's how it landed for her'","right":"Names the impact"},{"left":"Said quietly after, not in the room","right":"Lets them save face"},{"left":"'Can we just skip those?'","right":"Offers a clear way forward"},{"left":"'We're good, by the way'","right":"Keeps the relationship warm"}],"relearn":"Good faith, naming impact, saving face, a way forward, and warmth make a call-in work.","persona":"any","source":"why call-ins work"},
  {"id":"lw-1312","cat":"call-in-not-out","type":"match","hook":"Match each myth about calling in to the truth.","pairs":[{"left":"'Calling in is being soft'","right":"Firm on the issue, kind to the person"},{"left":"'Public shaming changes people'","right":"Shame entrenches; persuasion changes minds"},{"left":"'Say it instantly or never'","right":"A calm word later often lands better"},{"left":"'Call-in means staying silent'","right":"Real harm still gets named firmly"},{"left":"'No instant fix means it failed'","right":"Minds shift slowly; seeds sprout later"}],"relearn":"Calling in is firm-yet-kind, persuasive over shaming, patient, and not silence.","persona":"any","source":"myths vs truth"},
  {"id":"lw-1313","cat":"call-in-not-out","type":"spot","hook":"Spot the two moves that shame instead of calling in.","scene":[{"id":"a","text":"A private 'that landed wrong, can we talk?'","trick":false},{"id":"b","text":"Posting his screenshot for the class to mock","trick":true},{"id":"c","text":"Assuming he meant no harm","trick":false},{"id":"d","text":"Tagging everyone to pile on him","trick":true},{"id":"e","text":"Catching him quietly after the meeting","trick":false}],"why":"Posting to mock and tagging a pile-on are public shaming. They entrench, not persuade.","relearn":"Public mockery and pile-ons shame; private, good-faith words call in.","persona":"any","source":"spot the call-out"},
  {"id":"lw-1314","cat":"call-in-not-out","type":"spot","hook":"Spot the two lines that would harden someone instead of opening them up.","scene":[{"id":"a","text":"'I don't think you meant it badly'","trick":false},{"id":"b","text":"'You're just a sexist, end of story'","trick":true},{"id":"c","text":"'Here's how it landed for her'","trick":false},{"id":"d","text":"'Everyone already knows you're trash'","trick":true},{"id":"e","text":"'Can we just skip those jokes?'","trick":false}],"why":"Labelling someone and announcing contempt make them defend their pride, not rethink.","relearn":"Labels and contempt harden people; good faith and impact open them up.","persona":"any","source":"spot the hardener"},
  {"id":"lw-1315","cat":"call-in-not-out","type":"spot","hook":"Spot the two responses that push confrontation when safety should come first.","scene":[{"id":"a","text":"Check she's okay first","trick":false},{"id":"b","text":"Corner him alone, even though she's scared","trick":true},{"id":"c","text":"Bring in a trusted adult","trick":false},{"id":"d","text":"Livestream confronting him to 'expose' it","trick":true},{"id":"e","text":"Stay with her and call for help if needed","trick":false}],"why":"Cornering him alone and livestreaming a confrontation ignore the risk: when there's fear, safety first.","relearn":"When someone's frightened, safety first: support her and get a trusted adult, don't confront alone.","persona":"any","source":"spot the unsafe move"},
  {"id":"lw-1316","cat":"call-in-not-out","type":"spot","hook":"Spot the two 'leadership' moves that are really just grandstanding.","scene":[{"id":"a","text":"A quiet word that shifts the norm","trick":false},{"id":"b","text":"A loud speech mainly to look good","trick":true},{"id":"c","text":"Crediting whoever's idea it was","trick":false},{"id":"d","text":"Publicly dunking to win applause","trick":true},{"id":"e","text":"Changing your own behaviour first","trick":false}],"why":"A look-good speech and a public dunk chase credit and applause: that's grandstanding, not leading.","relearn":"Quiet norm-shifting leads; speeches-for-show and public dunks are grandstanding.","persona":"any","source":"spot the grandstanding"},
  {"id":"lw-1317","cat":"call-in-not-out","type":"branch","hook":"A friend keeps 'joking' about your classmate's stammer to get laughs.","options":[{"text":"Quietly: 'He hates that. Let's not make him the joke.'","consequence":"He sees it isn't harmless fun and eases off.","outcome":"private","best":true},{"text":"Mock your friend's flaws right back in the group","consequence":"Trading mockery is a public dunk, not a call-in."}],"debrief":"A quiet 'he hates that' names the harm without humiliating your friend.","relearn":"Name the harm to a friend quietly instead of mocking them back.","persona":"any","source":"call-in (private)"},
  {"id":"lw-1318","cat":"call-in-not-out","type":"role-play","hook":"A teammate says you only 'support girls' to impress them.","setup":"Keep it light and clear. Say:","yourLine":[{"text":"\"Nah, it's just basic fairness: costs me nothing, helps a lot.\"","best":true},{"text":"Get defensive and list all your 'proof'"}],"relearn":"A calm 'it's just fairness' answers the dig without getting defensive.","persona":"Vijay","source":"male allyship as normal"},
  {"id":"lw-1080","cat":"lead-by-example","type":"branch","persona":"Vijay","source":"lead by example / chores","relearn":"Picking up a 'girls' chore yourself, unasked, shifts the home norm more than a speech.","hook":"At home, only your sister is expected to clear the dishes after dinner.","options":[{"text":"Quietly start clearing the dishes yourself each night","consequence":"Your steady example makes the split feel normal for all.","outcome":"example","best":true},{"text":"Just announce chores should be equal, then do none","consequence":"A speech without action changes nothing; doing it leads."}],"debrief":"Sharing a chore visibly and unasked teaches more than any lecture about fairness."},
  {"id":"lw-1083","cat":"lead-by-example","type":"branch","persona":"Arjun","source":"lead by example / integrity","relearn":"Behaving the same way whether or not seniors watch is the integrity that earns trust.","hook":"The teacher leaves; classmates start mocking a shy boy now no adult is watching.","options":[{"text":"Treat him exactly as you would with the teacher there","consequence":"Your unchanged behaviour steadies the room.","outcome":"integrity","best":true},{"text":"Join the mocking since no one in charge will know","consequence":"Acting fair only when watched is a performance, not leadership."}],"debrief":"Integrity means your conduct matches your values even when no adult is in the room."},
  {"id":"lw-1085","cat":"lead-by-example","type":"branch","persona":"Vijay","source":"lead by example / cooking","relearn":"A boy doing a skill openly shows it's a useful skill, not shame, and resets what's 'manly'.","hook":"Friends tease you for learning to cook, saying that's 'women's work'.","options":[{"text":"Keep cooking openly and share what you made with them","consequence":"Owning it confidently reframes cooking as a normal skill.","outcome":"example","best":true},{"text":"Hide that you cook so they stop teasing","consequence":"Hiding it agrees the teasing is right."}],"debrief":"Doing a skill openly, unbothered by 'that's women's work', leads and frees others too."},
  {"id":"lw-1086","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / credit","relearn":"Crediting the person whose idea it was, out loud, models fairness better than the spotlight.","hook":"A teammate's idea gets ignored, then repeated by someone louder who's praised.","options":[{"text":"Say 'glad we're going with it, that was Meena's idea'","consequence":"You quietly model fair credit and the room notices.","outcome":"amplify","best":true},{"text":"Stay quiet; it's awkward to correct people","consequence":"Letting credit go to the wrong person keeps the pattern."}],"debrief":"Pointing credit back to its source, lightly, sets a norm of fairness others copy."},
  {"id":"lw-1088","cat":"lead-by-example","type":"branch","persona":"Sneha","source":"lead by example / steady","relearn":"Leading by example is steady and low-key; the point is the norm shifts, not the credit.","hook":"You've quietly made your group fairer for weeks. Someone calls you a 'show-off'.","options":[{"text":"Keep doing the right thing calmly, without defending it","consequence":"Your steadiness proves it was never about credit.","outcome":"steady","best":true},{"text":"List every fair thing you've done to prove a point","consequence":"Tallying your good deeds makes it about you, not the norm."}],"debrief":"Real example is steady; you needn't defend it or chase credit."},
  {"id":"lw-1090","cat":"lead-by-example","type":"branch","persona":"Vijay","source":"lead by example / male allyship","relearn":"A boy leading on fairness is showing maturity and strength, not betraying 'his side'.","hook":"Friends say backing the girls' team makes you 'one of them', not a real bro.","options":[{"text":"Keep backing fairness as the obvious, mature thing","consequence":"You model that allyship is strength, not switching sides.","outcome":"strength","best":true},{"text":"Back off so the boys still see you as loyal","consequence":"Dropping fairness to seem loyal trades values for approval."}],"debrief":"Leading on equality isn't a side against boys; it's strength, and frees boys too."},
  {"id":"lw-1091","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / sports","relearn":"Picking a mixed, skill-based team yourself models that ability, not gender, decides who plays.","hook":"You're made captain; the boys expect an all-boys side for the big match.","options":[{"text":"Pick the strongest players regardless of gender, say why","consequence":"Choosing on skill sets a fair standard the rest accept.","outcome":"example","best":true},{"text":"Pick all boys to keep the team happy","consequence":"Picking by gender, not skill, weakens team and norm."}],"debrief":"Choosing players by skill, openly, shows fairness and a strong team go together."},
  {"id":"lw-1092","cat":"lead-by-example","type":"branch","persona":"Arjun","source":"lead by example / consistency","relearn":"One slip doesn't end your example; owning and correcting it keeps the example trustworthy.","hook":"You repeat a careless gendered comment, then catch yourself. Friends saw it.","options":[{"text":"Own it: 'that came out wrong, I don't actually think that'","consequence":"Owning the slip keeps your example honest and human.","outcome":"own","best":true},{"text":"Pretend you didn't say it","consequence":"Pretending makes you look like you only perform fairness."}],"debrief":"Leading by example isn't never slipping; it's owning slips and correcting course."},
  {"id":"lw-1093","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / home","relearn":"Pitching in, rather than waiting to be served, leads at home without shaming anyone.","hook":"You're a guest; the boys are served first while the girls keep working.","options":[{"text":"Offer to help and wait so everyone eats together","consequence":"Your small move gently questions the 'men first' habit.","outcome":"example","best":true},{"text":"Accept being served first; you're the guest","consequence":"Taking the privilege quietly endorses the unequal habit."}],"debrief":"Pitching in and waiting so all eat together leads without shaming anyone's home."},
  {"id":"lw-1094","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / online","relearn":"Not forwarding a demeaning meme, and saying lightly why, models better group behaviour online.","hook":"A demeaning meme about girls is forwarded in your class group; people are laughing.","options":[{"text":"Don't forward it; reply 'this one's not it, let's not'","consequence":"Your calm refusal lets others opt out too.","outcome":"example","best":true},{"text":"React with the laughing emoji and say nothing","consequence":"A laughing react reads as a yes; set a tone instead."}],"debrief":"Not forwarding, and saying so lightly, models the group norm you want online."},
  {"id":"lw-1095","cat":"lead-by-example","type":"branch","persona":"Sneha","source":"lead by example / voice","relearn":"Speaking in your own calm voice, and inviting quieter peers in, models leadership isn't 'a man's role'.","hook":"In the class council, boys talk over the girls and a teacher assumes a boy will lead.","options":[{"text":"Speak clearly, then say 'let's hear Priya, she had a point'","consequence":"You claim your voice and open space for another.","outcome":"voice","best":true},{"text":"Stay quiet so you don't seem pushy","consequence":"Staying small leaves the old pattern in charge."}],"debrief":"Using your voice and pulling quieter peers in models leadership, not just for boys."},
  {"id":"lw-1096","cat":"lead-by-example","type":"branch","persona":"Vijay","source":"lead by example / errands","relearn":"Sharing the 'invisible' errands, not just the visible ones, makes your example complete.","hook":"Your sister does dishes and also tracks everyone's medicines and school forms.","options":[{"text":"Take on the forms and medicines too, not just dishes","consequence":"Sharing the mental load, not only chores, leads more fully.","outcome":"example","best":true},{"text":"Do one visible chore and feel that's enough","consequence":"Doing only the visible bit leaves the real load on her."}],"debrief":"Real example shares the invisible planning too, not just the chores people can see."},
  {"id":"lw-1097","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / pressure","relearn":"Holding your standard calmly under peer pressure is what makes an example worth following.","hook":"Friends dare you to rate girls walking past, saying it's 'just fun'.","options":[{"text":"Decline easily: 'not my thing', and change the subject","consequence":"Your relaxed no makes opting out look normal.","outcome":"example","best":true},{"text":"Play along a little so they don't mock you","consequence":"Joining 'a little' still endorses it; an easy no leads."}],"debrief":"A relaxed, brief refusal models a standard others can follow without drama."},
  {"id":"lw-1098","cat":"lead-by-example","type":"branch","persona":"Arjun","source":"lead by example / respect","relearn":"Using a classmate's correct name, consistently, models simple respect that sets a norm.","hook":"A few boys keep 'jokingly' using a wrong name for a classmate who corrected them.","options":[{"text":"Always use the name the classmate asked for, every time","consequence":"Your steady respect makes the mockery look out of step.","outcome":"respect","best":true},{"text":"Use the wrong name too when they're around","consequence":"Joining the 'joke' tells the class disrespect is fine."}],"debrief":"Using the name someone asked for models the respect that sets the norm."},
  {"id":"lw-1099","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / no audience","relearn":"Doing the fair thing when there's no audience or reward is the truest test of leading by example.","hook":"You find a junior's lost answer sheet; no one saw, and returning it earns you nothing.","options":[{"text":"Return it to her quietly without making a thing of it","consequence":"Doing right with no audience is the heart of example.","outcome":"integrity","best":true},{"text":"Keep it; no one will ever know","consequence":"'No one will know' is exactly when your example is tested."}],"debrief":"Integrity is doing the fair thing when no one's watching and there's no reward."},
  {"id":"lw-1100","cat":"lead-by-example","type":"branch","persona":"Sneha","source":"lead by example / steering","relearn":"Backing a friend toward a 'boys' subject, and staying with it, models that interest beats stereotype.","hook":"A friend loves coding but is told 'girls don't do tech'; she may drop it.","options":[{"text":"Take the elective with her and treat it as normal","consequence":"Your matter-of-fact choice makes the stereotype look silly.","outcome":"example","best":true},{"text":"Agree she should pick something 'more suitable'","consequence":"Steering her away repeats the bias she faces."}],"debrief":"Choosing the 'not for girls' subject yourself shows interest decides, not gender."},
  {"id":"lw-1101","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / apology","relearn":"Apologising plainly when your behaviour hurt someone models accountability others learn from.","hook":"You realise a 'joke' you made last week actually stung a classmate.","options":[{"text":"Apologise simply and directly, without excuses","consequence":"A clean apology models that owning harm is strength.","outcome":"own","best":true},{"text":"Say 'I was only joking, relax'","consequence":"'Only joking' dodges responsibility and repeats the hurt."}],"debrief":"A plain apology, no excuses, models the accountability that makes an example trustworthy."},
  {"id":"lw-1102","cat":"lead-by-example","type":"branch","persona":"Vijay","source":"lead by example / family","relearn":"Treating your sister's goals as seriously as your own, openly, leads change inside the family.","hook":"Relatives ask you about your career, but only ask your sister when she'll marry.","options":[{"text":"Redirect: 'she's aiming for engineering, ask her that'","consequence":"You model that her goals deserve the same attention.","outcome":"example","best":true},{"text":"Answer about yourself and let her question slide","consequence":"Letting it slide accepts only your future counts."}],"debrief":"Steering attention to her goals shows equal seriousness, respecting elders."},
  {"id":"lw-1104","cat":"lead-by-example","type":"branch","persona":"Arjun","source":"lead by example / friends","relearn":"Defending an absent friend's reputation models the respect you'd want shown to you.","hook":"Your friends start spreading an unkind rumour about a girl who isn't there.","options":[{"text":"Say 'I don't think that's true, let's not spread it'","consequence":"Defending someone absent models the respect you'd want.","outcome":"example","best":true},{"text":"Add a detail to the rumour to seem in the know","consequence":"Feeding the rumour spreads harm and breaks trust."}],"debrief":"Standing up for someone not in the room models the fairness you'd want shown to you."},
  {"id":"lw-1105","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / first action","relearn":"One small, specific fair act you actually do beats a big promise you never start.","hook":"You're inspired to 'be a better ally' but haven't done anything concrete yet.","options":[{"text":"Pick one small thing, like sharing a chore this week, do it","consequence":"A small real act started today is leadership; a vow isn't.","outcome":"action","best":true},{"text":"Just post that you support equality and leave it","consequence":"A post alone is display; one real action is the example."}],"debrief":"Leading by example starts with one small, specific thing you actually do."},
  {"id":"lw-1106","cat":"lead-by-example","type":"branch","persona":"Vijay","source":"lead by example / teasing","relearn":"Refusing to police a friend's 'unmanly' feelings models that respect isn't gendered.","hook":"Your friends mock another boy for crying at a sad film, calling him weak.","options":[{"text":"Say 'crying's normal' and treat him exactly the same after","consequence":"Treating his feelings as normal frees the whole group.","outcome":"example","best":true},{"text":"Join the teasing so they don't turn on you","consequence":"Teasing him to stay safe spreads the 'boys can't feel' rule."}],"debrief":"Treating a boy's feelings as normal models that respect, and emotion, aren't gendered."},
  {"id":"lw-1107","cat":"lead-by-example","type":"branch","persona":"any","source":"lead by example / fairness","relearn":"Splitting a shared reward evenly, even when you could grab more, models fairness people remember.","hook":"Your team wins a prize; as the loudest member you could take the credit.","options":[{"text":"Split it evenly and name what each person contributed","consequence":"Sharing the win fairly models leadership that lifts the team.","outcome":"example","best":true},{"text":"Take the biggest share since you spoke the most","consequence":"Grabbing the most teaches visibility beats fairness."}],"debrief":"Sharing credit and reward evenly shows leadership lifts the team, not you."},
  {"id":"lw-1108","cat":"lead-by-example","type":"branch","persona":"Sneha","source":"lead by example / double standard","relearn":"Refusing a double standard for yourself, calmly, models that the same rules apply to all.","hook":"You're told to be 'modest' about topping, though boys are praised loudly.","options":[{"text":"Accept congratulations gracefully, as anyone would","consequence":"Owning your success models that pride isn't only for boys.","outcome":"example","best":true},{"text":"Downplay it so you don't seem a 'show-off'","consequence":"Shrinking yourself accepts the double standard set."}],"debrief":"Owning your success as a boy would shows the same rules apply to all."},
  {"id":"lw-1109","cat":"lead-by-example","type":"reflect","persona":"any","source":"norm-setting","relearn":"Your everyday behaviour quietly sets a norm others copy, whether you mean to or not.","hook":"Lensy: the people around you copy what you do far more than what you say. Sit with that.","prompt":"What feels true for you?","options":["I'm always setting a norm","My actions speak loudest","Worth choosing carefully"],"affirm":"You're already an example to someone; choosing what you model is real, quiet leadership."},
  {"id":"lw-1110","cat":"lead-by-example","type":"reflect","persona":"Vijay","source":"male allyship","relearn":"A boy leading on fairness is showing strength and maturity, not betraying anyone.","hook":"Lensy: some say a boy who stands for fairness is 'soft'. What do you feel about that?","prompt":"Pick what fits you.","options":["It's actually strength","Maturity, not weakness","Fairness frees boys too"],"affirm":"Leading on equality takes real strength, and it lightens the load for boys as much as girls."},
  {"id":"lw-1111","cat":"lead-by-example","type":"reflect","persona":"any","source":"integrity","relearn":"Doing the fair thing when no one's watching is the integrity that makes an example worth following.","hook":"Lensy: think of a moment you did right when no one would ever know. How did it feel?","prompt":"What comes up?","options":["Quietly proud","That's who I want to be","Harder but worth it"],"affirm":"That choice, made with no audience and no reward, is the integrity leadership is built on."},
  {"id":"lw-1112","cat":"lead-by-example","type":"reflect","persona":"any","source":"steady leadership","relearn":"Small, steady acts of respect repeated over time are how norms, and leaders, are made.","hook":"Lensy: a hundred small fair choices or one big speech, which changes a room more?","prompt":"Where do you land?","options":["The steady small ones","Both, but steady wins","Actions over speeches"],"affirm":"Small, steady fairness, repeated, is how real norms shift, no megaphone required."},
  {"id":"lw-1113","cat":"lead-by-example","type":"reflect","persona":"any","source":"legacy","relearn":"People remember how you made them feel; that feeling is the example you leave.","hook":"Lensy: a younger kid is watching how you treat people right now. What do you hope they learn?","prompt":"Choose one.","options":["To respect everyone","That fairness is normal","To lift others up"],"affirm":"What you model now becomes someone's default later; that's leadership that outlasts you."},
  {"id":"lw-1114","cat":"lead-by-example","type":"reflect","persona":"Sneha","source":"own values","relearn":"Leading from your own values, not a borrowed style, is what makes your leadership sustainable.","hook":"Lensy: you needn't lead like anyone else. What value of yours do you most want to lead from?","prompt":"Pick the one that's most you.","options":["Fairness","Honesty","Kindness","Courage"],"affirm":"Leading from a value that's truly yours is what makes your example real and lasting."},
  {"id":"lw-1115","cat":"lead-by-example","type":"reflect","persona":"any","source":"quiet leadership","relearn":"You don't need a title or a stage; quiet everyday example is real leadership.","hook":"Lensy: 'I'm not a leader, I have no title.' Does leadership really need a title?","prompt":"What do you think now?","options":["No title needed","Everyday acts count","Anyone can lead"],"affirm":"You don't need a badge or a stage; how you act every day is leadership already."},
  {"id":"lw-1116","cat":"lead-by-example","type":"reflect","persona":"any","source":"home example","relearn":"Sharing the home load visibly and unasked leads better than telling others to be fair.","hook":"Lensy: at home, what's one share of the work you could quietly take on without being asked?","prompt":"Picture one.","options":["The dishes","The planning and reminders","Whatever's left undone"],"affirm":"Whatever you pick, doing it unasked and steadily is how leading by example starts at home."},
  {"id":"lw-1117","cat":"lead-by-example","type":"reflect","persona":"Arjun","source":"consistency","relearn":"An example only leads if it's consistent; one slip doesn't undo steady fairness.","hook":"Lensy: you won't get it perfect every time. Does one slip cancel a hundred fair days?","prompt":"How do you see it?","options":["No, consistency counts","Owning slips is enough","Progress, not perfection"],"affirm":"Your example is the pattern, not the one bad day; owning slips keeps it honest."},
  {"id":"lw-1118","cat":"lead-by-example","type":"reflect","persona":"any","source":"no credit","relearn":"Leading by example is steady and humble; the win is the norm shifting, not the credit.","hook":"Lensy: if you changed the room but no one ever thanked you, would that still be worth it?","prompt":"What's your honest take?","options":["Yes, the change is the point","Credit isn't why I do it","Quiet impact is enough"],"affirm":"When the shifted norm matters more than the thank-you, that's leadership at its most real."},
  {"id":"lw-1119","cat":"lead-by-example","type":"reflect","persona":"any","source":"first step","relearn":"A real plan is one small, specific thing you'll actually do, not a vow to 'be better'.","hook":"Lensy: what's one tiny, specific fair thing you could actually do this week?","prompt":"Name one to yourself.","options":["Share a chore","Credit someone's idea","Not laugh at a put-down","Invite a quiet voice in"],"affirm":"One small, specific act you really do beats any grand promise; that's where your example begins."},
  {"id":"lw-1120","cat":"lead-by-example","type":"reflect","persona":"Vijay","source":"bringing boys in","relearn":"Equality is everyone's job; boys bringing other boys along is one of the strongest moves there is.","hook":"Lensy: imagine bringing one friend along to act fairer too. Who comes to mind?","prompt":"Hold that person in mind.","options":["A close friend","Someone who'd listen","Just by my example"],"affirm":"Bringing even one boy along, often just by your example, multiplies the change you can make."},
  {"id":"lw-1121","cat":"lead-by-example","type":"reflect","persona":"any","source":"agency","relearn":"One person leading by example and lifting one other genuinely shifts the room.","hook":"Lensy: 'one person can't change anything.' True, or a story we tell to stay comfortable?","prompt":"What do you believe?","options":["One person can shift a room","It starts with one","I can be that one"],"affirm":"One steady example, lifting one other person, really does move a room; you can be that start."},
  {"id":"lw-1122","cat":"lead-by-example","type":"reflect","persona":"any","source":"style","relearn":"There's no single right way to lead; your authentic style is real and valuable.","hook":"Lensy: leaders come quiet, funny, calm, fierce. Which feels most like the leader in you?","prompt":"Pick what fits.","options":["Quiet and steady","Warm and including","Calm but firm","Fun and disarming"],"affirm":"Whatever style is genuinely yours is a real way to lead; you don't have to copy anyone."},
  {"id":"lw-1123","cat":"lead-by-example","type":"reflect","persona":"any","source":"respect","relearn":"Respect shown the same to everyone, regardless of gender or status, sets the norm you lead by.","hook":"Lensy: do you treat the canteen worker with the same respect as the principal?","prompt":"Sit with it honestly.","options":["I try to, always","Same respect for all","Something to work on"],"affirm":"Equal respect up and down, watched or not, is the everyday example that quietly leads a place."},
  {"id":"lw-1124","cat":"lead-by-example","type":"spot","persona":"any","source":"lead by example / home","relearn":"Sharing the load unasked and steadily leads; doing it for show or only when told doesn't.","hook":"At home, spot the two moves that aren't really leading by example.","scene":[{"id":"a","text":"Clearing up every night without being asked","trick":false},{"id":"b","text":"Only helping when guests can see you","trick":true},{"id":"c","text":"Learning to cook and doing it openly","trick":false},{"id":"d","text":"Helping once, then posting it for praise","trick":true},{"id":"e","text":"Tracking the reminders and forms too","trick":false}],"why":"Helping only when seen, or just for a post, is a show; quiet, steady sharing is what leads."},
  {"id":"lw-1125","cat":"lead-by-example","type":"spot","persona":"any","source":"lead by example / group","relearn":"Fair roles and shared credit lead a group; gendered defaults and credit-grabbing don't.","hook":"In a group project, spot the two moves that undercut leading by example.","scene":[{"id":"a","text":"Assigning roles by who's strongest at each","trick":false},{"id":"b","text":"Defaulting girls to notes, boys to present","trick":true},{"id":"c","text":"Crediting whoever's idea it actually was","trick":false},{"id":"d","text":"Taking credit for a quieter member's idea","trick":true},{"id":"e","text":"Inviting the quiet members to speak","trick":false}],"why":"Gendered role defaults and grabbing others' credit undercut the example; skill-based roles lead."},
  {"id":"lw-1126","cat":"lead-by-example","type":"spot","persona":"Vijay","source":"lead by example / male allyship","relearn":"A boy leading on fairness is strength; caving for approval or only posting isn't leadership.","hook":"Spot the two moves that aren't real male allyship.","scene":[{"id":"a","text":"Backing a fair call even when friends grumble","trick":false},{"id":"b","text":"Dropping fairness so the boys still approve","trick":true},{"id":"c","text":"Sharing chores at home, unasked","trick":false},{"id":"d","text":"Saying you support equality but only online","trick":true},{"id":"e","text":"Taking a sister's goals as seriously as yours","trick":false}],"why":"Caving for approval or 'supporting' only online isn't allyship; steady, real action is."},
  {"id":"lw-1127","cat":"lead-by-example","type":"spot","persona":"any","source":"lead by example / jokes","relearn":"Not laughing and quietly redirecting set a better norm; laughing along or piling on don't lead.","hook":"A demeaning joke lands. Spot the two reactions that don't lead by example.","scene":[{"id":"a","text":"Not laughing and changing the subject","trick":false},{"id":"b","text":"Laughing loudly so you fit in","trick":true},{"id":"c","text":"Lightly saying 'that one's not it'","trick":false},{"id":"d","text":"Adding a meaner joke of your own","trick":true},{"id":"e","text":"Checking in with the person it targeted","trick":false}],"why":"Laughing along and topping it with a meaner joke spread the put-down; not laughing leads."},
  {"id":"lw-1128","cat":"lead-by-example","type":"spot","persona":"any","source":"lead by example / integrity","relearn":"Integrity is acting fair whether or not watched; acting fair only for an audience isn't.","hook":"The teacher steps out. Spot the two moves that are performance, not integrity.","scene":[{"id":"a","text":"Treating all the same with no adult around","trick":false},{"id":"b","text":"Being kind only while the teacher watches","trick":true},{"id":"c","text":"Returning a lost item with no one looking","trick":false},{"id":"d","text":"Helping only when it earns you praise","trick":true},{"id":"e","text":"Owning a mistake even if no one noticed","trick":false}],"why":"Being fair only when watched or rewarded is a performance; integrity holds with no audience."},
  {"id":"lw-1129","cat":"lead-by-example","type":"spot","persona":"Sneha","source":"lead by example / voice","relearn":"Using your voice and opening space for others leads; shrinking or silencing others doesn't.","hook":"When girls get talked over, spot the two moves that don't lead.","scene":[{"id":"a","text":"Speaking your point clearly and calmly","trick":false},{"id":"b","text":"Staying silent so you don't seem pushy","trick":true},{"id":"c","text":"Saying 'let's hear Priya, she had a point'","trick":false},{"id":"d","text":"Talking over everyone to win the floor","trick":true},{"id":"e","text":"Crediting whoever raised the idea first","trick":false}],"why":"Going silent to seem 'nice' or steamrolling others both fail; using your voice and lifting others leads."},
  {"id":"lw-1130","cat":"lead-by-example","type":"spot","persona":"any","source":"lead by example / what lands","relearn":"Consistency, humility and owning slips make an example land; one-off stunts and loud credit don't.","hook":"Spot the two things that stop an example from landing.","scene":[{"id":"a","text":"Doing the fair thing consistently for months","trick":false},{"id":"b","text":"One grand gesture, then back to old habits","trick":true},{"id":"c","text":"Owning a slip and correcting course","trick":false},{"id":"d","text":"Loudly reminding everyone how fair you are","trick":true},{"id":"e","text":"Leading quietly, without chasing credit","trick":false}],"why":"A one-off gesture and loud self-praise undercut the example; steady, humble action lands."},
  {"id":"lw-1131","cat":"lead-by-example","type":"spot","persona":"any","source":"lead by example / younger ones","relearn":"Modelling respect for younger kids teaches a fair default; mocking or excusing put-downs doesn't.","hook":"A younger sibling is watching. Spot the two moves that teach the wrong lesson.","scene":[{"id":"a","text":"Speaking respectfully about all genders","trick":false},{"id":"b","text":"Using a put-down, then 'it's just a joke'","trick":true},{"id":"c","text":"Sharing chores so it looks normal","trick":false},{"id":"d","text":"Mocking a boy for crying near them","trick":true},{"id":"e","text":"Apologising plainly when you're wrong","trick":false}],"why":"Excusing a put-down and mocking feelings teach the wrong default; respect teaches the right one."},
  {"id":"lw-1132","cat":"lead-by-example","type":"role-play","persona":"any","source":"modelling","relearn":"Modelling fair credit out loud, lightly, leads a group better than letting it slide.","hook":"A teammate's idea just got repeated by someone louder and praised. You want to set credit straight.","setup":"Lead by crediting the source. Say:","yourLine":[{"text":"\"Glad we're going with it, that was Asha's idea earlier.\"","best":true},{"text":"Say nothing; it's awkward to correct people"}]},
  {"id":"lw-1133","cat":"lead-by-example","type":"role-play","persona":"Vijay","source":"modelling","relearn":"Naming the unequal split lightly, then doing your share, models fairness at home.","hook":"After the meal the women clear up while the men sit. You want to lead by example.","setup":"Get up and say, easily:","yourLine":[{"text":"\"Let me help clear, no reason this is only their job.\"","best":true},{"text":"Stay seated; that's just how it's always been"}]},
  {"id":"lw-1134","cat":"lead-by-example","type":"role-play","persona":"any","source":"modelling","relearn":"A calm, brief refusal to join a demeaning 'game' models a standard without preaching.","hook":"Friends dare you to rate girls walking past, calling it 'just fun'.","setup":"Decline easily and redirect. Say:","yourLine":[{"text":"\"Not my thing, leave them be, let's get going.\"","best":true},{"text":"Play along a bit so they don't mock you"}]},
  {"id":"lw-1135","cat":"lead-by-example","type":"role-play","persona":"Sneha","source":"modelling","relearn":"Owning your success normally, and inviting others up, models that pride isn't only for boys.","hook":"You topped the class; you're nudged to downplay it while boys are praised loudly.","setup":"Accept it gracefully and share the floor. Say:","yourLine":[{"text":"\"Thank you, I worked hard, and so did Priya, ask her too.\"","best":true},{"text":"Mumble that it was nothing so you don't seem show-off"}]},
  {"id":"lw-1136","cat":"lead-by-example","type":"role-play","persona":"Arjun","source":"modelling","relearn":"Defending an absent friend, plainly, models the respect you'd want shown to you.","hook":"Friends start spreading an unkind rumour about a girl who isn't there.","setup":"Step in, evenly. Say:","yourLine":[{"text":"\"I don't think that's true, and let's not spread it.\"","best":true},{"text":"Add a detail so you seem in the know"}]},
  {"id":"lw-1137","cat":"lead-by-example","type":"role-play","persona":"any","source":"modelling","relearn":"Volunteering across the gender line first makes mixing feel normal for the group.","hook":"For the function, the teacher asks which girls decorate and which boys handle sound.","setup":"Cross the line first. Say:","yourLine":[{"text":"\"I'll decorate, and anyone can pick what they're good at.\"","best":true},{"text":"Just take the task expected of your gender"}]},
  {"id":"lw-1138","cat":"lead-by-example","type":"role-play","persona":"Vijay","source":"modelling","relearn":"Treating a sister's goals as seriously as your own, out loud, leads change in the family.","hook":"Relatives grill you about your career but only ask your sister about marriage.","setup":"Redirect warmly to her goals. Say:","yourLine":[{"text":"\"She's aiming for engineering, you should ask her about that.\"","best":true},{"text":"Answer about yourself and let her question slide"}]},
  {"id":"lw-1139","cat":"lead-by-example","type":"sort","persona":"any","source":"integrity vs performance","relearn":"Integrity is acting fair with no audience; performance is acting fair only when watched.","hook":"Sort each move: real integrity, or just performance?","items":[{"id":"a","text":"Returning a lost item with no one watching"},{"id":"b","text":"Being kind only while the teacher looks"},{"id":"c","text":"Owning a mistake nobody noticed"},{"id":"d","text":"Helping only when it earns praise"},{"id":"e","text":"Treating juniors the same as seniors"},{"id":"f","text":"Posting your good deed for applause"}],"bins":[{"id":"integrity","label":"Real integrity","valence":"pos"},{"id":"show","label":"Just performance","valence":"neg"}],"key":{"a":"integrity","b":"show","c":"integrity","d":"show","e":"integrity","f":"show"}},
  {"id":"lw-1140","cat":"lead-by-example","type":"sort","persona":"Vijay","source":"home leadership","relearn":"Sharing the home load, visible and invisible, unasked, leads; waiting or excuses don't.","hook":"At home, sort each: leads by example, or leaves the load on others?","items":[{"id":"a","text":"Clearing up without being asked"},{"id":"b","text":"Waiting to be told before helping"},{"id":"c","text":"Tracking medicines and school forms"},{"id":"d","text":"Saying remembering things is 'her talent'"},{"id":"e","text":"Cooking openly, teased or not"},{"id":"f","text":"Helping only when guests are visiting"}],"bins":[{"id":"leads","label":"Leads at home","valence":"pos"},{"id":"leaves","label":"Leaves the load","valence":"neg"}],"key":{"a":"leads","b":"leaves","c":"leads","d":"leaves","e":"leads","f":"leaves"}},
  {"id":"lw-1141","cat":"lead-by-example","type":"sort","persona":"any","source":"steady vs flashy","relearn":"Steady, humble, consistent action leads; flashy one-offs and credit-seeking don't.","hook":"Sort each: steady leadership, or a flashy one-off?","items":[{"id":"a","text":"Being fair, quietly, every single day"},{"id":"b","text":"One grand gesture, then old habits return"},{"id":"c","text":"Leading without chasing credit"},{"id":"d","text":"Announcing loudly how fair you are"},{"id":"e","text":"Owning slips and correcting course"},{"id":"f","text":"A big post, then nothing changes"}],"bins":[{"id":"steady","label":"Steady leadership","valence":"pos"},{"id":"flashy","label":"Flashy one-off","valence":"neg"}],"key":{"a":"steady","b":"flashy","c":"steady","d":"flashy","e":"steady","f":"flashy"}},
  {"id":"lw-1142","cat":"lead-by-example","type":"sort","persona":"any","source":"roles by skill","relearn":"Assigning roles by skill and interest leads; assigning by gender keeps old defaults.","hook":"Sort each way of giving out roles: fair example, or gendered default?","items":[{"id":"a","text":"Picking the best speaker to present"},{"id":"b","text":"'Girls take notes, boys present'"},{"id":"c","text":"Letting interest decide who designs"},{"id":"d","text":"'Boys handle tech, girls decorate'"},{"id":"e","text":"Asking who wants to lead which part"},{"id":"f","text":"'She should serve, he should speak'"}],"bins":[{"id":"fair","label":"Fair example","valence":"pos"},{"id":"gendered","label":"Gendered default","valence":"neg"}],"key":{"a":"fair","b":"gendered","c":"fair","d":"gendered","e":"fair","f":"gendered"}},
  {"id":"lw-1143","cat":"lead-by-example","type":"sort","persona":"any","source":"online example","relearn":"Refusing to spread put-downs online and crediting others leads; forwarding or piling on doesn't.","hook":"Online, sort each move: leads by example, or spreads harm?","items":[{"id":"a","text":"Not forwarding a demeaning meme"},{"id":"b","text":"Reacting with a laughing emoji to it"},{"id":"c","text":"Crediting whose idea a post really was"},{"id":"d","text":"Forwarding it 'for a laugh'"},{"id":"e","text":"Saying 'this one's not it, let's not'"},{"id":"f","text":"Piling on with a meaner comment"}],"bins":[{"id":"leads","label":"Leads by example","valence":"pos"},{"id":"harm","label":"Spreads harm","valence":"neg"}],"key":{"a":"leads","b":"harm","c":"leads","d":"harm","e":"leads","f":"harm"}},
  {"id":"lw-1144","cat":"lead-by-example","type":"sort","persona":"Sneha","source":"voice and amplifying","relearn":"Using your voice and lifting quieter peers leads; shrinking or silencing others doesn't.","hook":"When girls get talked over, sort each move: leads, or doesn't?","items":[{"id":"a","text":"Saying your point clearly and calmly"},{"id":"b","text":"Staying silent to avoid seeming pushy"},{"id":"c","text":"'Let's hear Priya, she had a point'"},{"id":"d","text":"Talking over everyone to win the floor"},{"id":"e","text":"Crediting whoever raised the idea first"},{"id":"f","text":"Downplaying your win to not stand out"}],"bins":[{"id":"leads","label":"Leads the room","valence":"pos"},{"id":"not","label":"Doesn't lead","valence":"neg"}],"key":{"a":"leads","b":"not","c":"leads","d":"not","e":"leads","f":"not"}},
  {"id":"lw-1145","cat":"lead-by-example","type":"sort","persona":"any","source":"accountability","relearn":"Owning slips and apologising plainly leads; excuses and dodging don't.","hook":"After you slip up, sort each response: accountable, or dodging?","items":[{"id":"a","text":"'That came out wrong, I'm sorry'"},{"id":"b","text":"'I was only joking, relax'"},{"id":"c","text":"Correcting your behaviour next time"},{"id":"d","text":"Avoiding the person you hurt"},{"id":"e","text":"Naming the harm without excuses"},{"id":"f","text":"Pretending you never said it"}],"bins":[{"id":"own","label":"Accountable","valence":"pos"},{"id":"dodge","label":"Dodging","valence":"neg"}],"key":{"a":"own","b":"dodge","c":"own","d":"dodge","e":"own","f":"dodge"}},
  {"id":"lw-1146","cat":"lead-by-example","type":"match","persona":"any","source":"example moments","relearn":"Each everyday moment has a quiet, leading-by-example move that fits it.","hook":"Match each everyday moment to the leading-by-example move.","pairs":[{"left":"A 'girls' chore at home goes undone","right":"Quietly do it yourself, unasked"},{"left":"A teammate's idea is ignored, then copied","right":"Credit them out loud"},{"left":"A demeaning joke lands in the group","right":"Don't laugh; lightly redirect"},{"left":"Roles default by gender in a project","right":"Assign by skill and interest"},{"left":"A junior is mocked when no adult's around","right":"Treat them with the same respect"}]},
  {"id":"lw-1147","cat":"lead-by-example","type":"match","persona":"any","source":"performance vs real","relearn":"Each show-only move has a real, steady version that actually leads.","hook":"Match each performance to the real, steady version of it.","pairs":[{"left":"Helping only when guests can see","right":"Sharing the load every day"},{"left":"One grand gesture, then old habits","right":"Being fair consistently over time"},{"left":"Posting that you support equality","right":"Doing one fair act this week"},{"left":"Announcing how fair you are","right":"Leading quietly, no credit chased"},{"left":"Kind only while the teacher watches","right":"The same with no adult around"}]},
  {"id":"lw-1148","cat":"lead-by-example","type":"match","persona":"Vijay","source":"male allyship moves","relearn":"Each common situation has a strong, male-allyship move that leads by example.","hook":"Match each situation to the strong, lead-by-example move.","pairs":[{"left":"Friends tease you for cooking","right":"Keep cooking openly, unbothered"},{"left":"Relatives only ask your sister about marriage","right":"Redirect them to her goals"},{"left":"Boys say backing fairness is 'soft'","right":"Treat it as the mature thing"},{"left":"Women clear up while men sit","right":"Get up and help, unasked"},{"left":"A boy is mocked for crying","right":"Say crying is normal, move on"}]},
  {"id":"lw-1149","cat":"lead-by-example","type":"match","persona":"any","source":"styles","relearn":"There are many real ways to lead; each authentic style still leads by example.","hook":"Match each leadership style to how it leads by example.","pairs":[{"left":"Quiet and steady","right":"Models fairness day after day"},{"left":"Warm and including","right":"Pulls quieter voices into the room"},{"left":"Calm but firm","right":"Names what's unfair without heat"},{"left":"Fun and disarming","right":"Shifts the joke, not the person"},{"left":"Hands-on","right":"Just does the fair thing first"}]},
  {"id":"lw-1150","cat":"lead-by-example","type":"match","persona":"any","source":"first actions","relearn":"Each value can become one small, specific first action you actually do.","hook":"Match each value to a small first action that shows it.","pairs":[{"left":"Fairness","right":"Split a shared reward evenly"},{"left":"Respect","right":"Use the name someone asked for"},{"left":"Honesty","right":"Own a slip without excuses"},{"left":"Inclusion","right":"Invite a quiet peer to speak"},{"left":"Courage","right":"Don't laugh at a put-down"}]},
  {"id":"lw-1151","cat":"lead-by-example","type":"match","persona":"Sneha","source":"amplify moves","relearn":"Each overlooked-voice moment has an amplifying move that lifts the person.","hook":"Match each moment to the move that lifts an overlooked voice.","pairs":[{"left":"A quiet peer had a good idea first","right":"Name them when it comes up again"},{"left":"A friend may drop a 'boys' subject","right":"Take it alongside her, calmly"},{"left":"Girls keep getting talked over","right":"Hand the floor back to one of them"},{"left":"Your win overshadows a teammate's","right":"Share the credit out loud"},{"left":"A capable peer skips a chance","right":"Encourage her to put her name in"}]},
  {"id":"lw-1152","cat":"lead-by-example","type":"match","persona":"Arjun","source":"respect moves","relearn":"Each disrespect moment has a quiet move that resets the norm.","hook":"Match each moment to the quiet move that models respect.","pairs":[{"left":"Boys use a wrong name for a peer 'in fun'","right":"Always use the name they asked for"},{"left":"A rumour spreads about an absent girl","right":"Say it's not true and let it drop"},{"left":"A shy classmate is mocked off-camera","right":"Treat them the same as always"},{"left":"A put-down is excused as 'a joke'","right":"Say 'that one's not it', calmly"},{"left":"An old joke of yours stung someone","right":"Apologise plainly, no excuses"}]},
  {"id":"lw-1153","cat":"lead-by-example","type":"strike-rewrite","persona":"any","source":"actions over speeches","relearn":"What you actually do, not what you preach, is the example people copy.","hook":"\"As long as I say the right things, that's leading by example.\"","myth":{"un":"Saying the right things about fairness is leading by example.","re":"People copy what you do, not what you announce; sharing the chore beats lecturing about it.","why":"A gap between your words and your actions teaches the actions, every time."}},
  {"id":"lw-1154","cat":"lead-by-example","type":"strike-rewrite","persona":"Vijay","source":"male allyship myth","relearn":"A boy leading on equality is strength and maturity, and it frees boys too.","hook":"A myth boys hear about fairness.","myth":{"un":"A boy who supports equality is weak or betraying his side.","re":"Leading on equality is strength and maturity, and it frees boys from rigid roles too.","why":"Standing for fairness under pressure takes real strength, and equality lightens the load on boys as well."}},
  {"id":"lw-1155","cat":"lead-by-example","type":"strike-rewrite","persona":"any","source":"talk vs do myth","relearn":"Telling others to be fair changes little; doing your share yourself, unasked, leads.","hook":"A myth about how change happens at home.","myth":{"un":"Telling everyone the chores should be equal is enough to fix it.","re":"Doing your fair share yourself, visibly and unasked, shifts the home norm far more than a speech.","why":"People follow what they see you do, not what you tell them to do; the example is the lesson."}},
  {"id":"lw-1156","cat":"lead-by-example","type":"strike-rewrite","persona":"any","source":"performance myth","relearn":"A one-off post or grand gesture isn't leadership; consistent action is.","hook":"A myth about looking like a leader.","myth":{"un":"One big gesture or a supportive post makes you a leader.","re":"A one-off gesture fades; consistent, humble fairness over time is what actually leads.","why":"An example only sets a norm when people can count on it again and again, not just once."}},
  {"id":"lw-1157","cat":"lead-by-example","type":"strike-rewrite","persona":"any","source":"watched myth","relearn":"Integrity is acting fair even when no one's watching, not only for an audience.","hook":"A myth about when being good matters.","myth":{"un":"Being fair only matters when people are watching.","re":"Integrity means your conduct matches your values even when no one is watching.","why":"The example others trust is the one that holds up off-camera, with no audience and no reward."}},
  {"id":"lw-1158","cat":"lead-by-example","type":"strike-rewrite","persona":"any","source":"roles myth","relearn":"Roles should follow skill and interest, not gender; modelling that resets the default.","hook":"A myth about who does what in a group.","myth":{"un":"Some tasks are just naturally for girls and others for boys.","re":"Roles should follow skill and interest, not gender, and modelling that resets the group's default.","why":"Sorting tasks by gender wastes talent and teaches a false rule; sorting by skill leads better work and a fairer norm."}},
  {"id":"lw-1159","cat":"lead-by-example","type":"strike-rewrite","persona":"Sneha","source":"grandstanding myth","relearn":"Leadership is steady and respectful; grandstanding and chasing credit aren't the win.","hook":"A myth about what leading looks like.","myth":{"un":"Leading means being the loudest and grabbing the credit.","re":"Leading by example is steady and respectful; the win is the norm shifting, not the credit.","why":"Loud credit-grabbing centres you, while a quiet shifted norm is the change that actually lasts."}},
  {"id":"lw-1160","cat":"lead-by-example","type":"strike-rewrite","persona":"any","source":"one-person myth","relearn":"One person leading by example and lifting one other genuinely shifts the room.","hook":"A myth that keeps people from starting.","myth":{"un":"One person can't change anything, so why bother leading.","re":"One person leading by example and lifting one other person genuinely shifts the room.","why":"Norms move when one steady example gives others permission to follow; change starts with one."}},
  {"id":"lw-1161","cat":"lead-by-example","type":"match","persona":"Vijay","source":"home shares","relearn":"Each home task has a fair, lead-by-example share a boy can quietly take on.","hook":"Match each home task to the fair share you can model.","pairs":[{"left":"Dishes pile up after dinner","right":"Clear them yourself, unasked"},{"left":"Younger ones need help with homework","right":"Sit and help them too"},{"left":"Someone must track the medicines","right":"Take that on, not just chores"},{"left":"Guests are served, hosts keep working","right":"Pitch in so all rest together"},{"left":"Laundry is treated as 'her job'","right":"Do your own and more"}]},
  {"id":"lw-1170","cat":"lift-as-you-climb","type":"branch","persona":"Vijay","source":"lift as you climb","relearn":"Mentor the junior who's too shy to ask; lift the one coming up behind you.","hook":"Your juniors at the coaching centre look up to you. A first-gen boy is too shy to ask doubts.","options":[{"text":"Sit with him after class and walk through his doubts","consequence":"He starts asking questions and his marks climb.","outcome":"mentor","best":true},{"text":"Let him figure it out like you had to","consequence":"Mentoring an overlooked junior is the heart of leading."}],"debrief":"Spending time on a shy junior's doubts is real, quiet leadership."},
  {"id":"lw-1171","cat":"lift-as-you-climb","type":"branch","persona":"Sneha","source":"lift as you climb","relearn":"When an ignored idea gets repeated and praised, name who said it first.","hook":"In the class committee, your friend's plan is ignored, then a louder boy says it and gets clapped.","options":[{"text":"Say 'good, that's exactly what Asha proposed earlier'","consequence":"Asha gets the credit, and people start hearing her.","outcome":"amplify","best":true},{"text":"Let it slide to keep the peace","consequence":"Naming whose idea it was is a simple, powerful lift."}],"debrief":"Crediting the original voice when it's repeated is everyday leadership."},
  {"id":"lw-1172","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Back a capable girl into the 'not for girls' role and rehearse it with her.","hook":"A talented girl in your group assumes the stage-anchor role 'isn't for girls' and won't try.","options":[{"text":"Encourage her to anchor and rehearse it with her","consequence":"She anchors well and a fake rule quietly breaks.","outcome":"open-door","best":true},{"text":"Pick a boy since he volunteered","consequence":"Backing her into a steered-away role opens a real door."}],"debrief":"Encouraging someone toward a role they were steered from is leadership."},
  {"id":"lw-1173","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"When you're praised for a team win, name who did what.","hook":"Your project tops the class. The teacher assumes you did it alone and praises only you.","options":[{"text":"Say it was a team effort and name who did what","consequence":"Your teammates feel seen and trust you more.","outcome":"credit","best":true},{"text":"Enjoy the spotlight quietly","consequence":"Naming contributors lifts them and marks a real leader."}],"debrief":"Sharing credit openly lifts your team and builds lasting trust."},
  {"id":"lw-1174","cat":"lift-as-you-climb","type":"branch","persona":"Vijay","source":"lift as you climb","relearn":"Offer the leadership-camp seat to the classmate who'd gain the most.","hook":"One free seat at a district leadership camp is offered to you. A quieter classmate would gain more.","options":[{"text":"Suggest the classmate who'd benefit most","consequence":"You open a door and grow a future leader.","outcome":"share","best":true},{"text":"Take the seat; you were asked first","consequence":"Passing on a chance, when you can, is how gaps close."}],"debrief":"Deliberately passing on an opportunity is exactly how gaps close."},
  {"id":"lw-1175","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Bring the new girl who eats alone into your group.","hook":"A new girl joins mid-term, knows no one, and eats lunch alone every day.","options":[{"text":"Pull her into your group and introduce her around","consequence":"She settles in and later does the same for others.","outcome":"include","best":true},{"text":"Assume she prefers being alone","consequence":"A small welcome can change someone's whole year."}],"debrief":"Welcoming someone in is a quiet lift that often gets paid forward."},
  {"id":"lw-1176","cat":"lift-as-you-climb","type":"branch","persona":"Sneha","source":"lift as you climb","relearn":"Help your friend campaign for captain and say out loud that she can win.","hook":"Your friend wants to contest as school captain but everyone says 'a girl won't win here'.","options":[{"text":"Back her, help her campaign, and say so out loud","consequence":"She runs a real race and others rethink the 'rule'.","outcome":"back","best":true},{"text":"Quietly agree it's a long shot","consequence":"Backing a capable candidate openly can shift a whole room."}],"debrief":"Publicly backing a capable friend can break a 'she can't win' belief."},
  {"id":"lw-1177","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Teach the struggling classmate the study method that worked for you.","hook":"You've learned a skill that helps you ace exams. A struggling classmate keeps failing the same way.","options":[{"text":"Teach them the method without being asked","consequence":"Their marks rise and you both grow.","outcome":"teach","best":true},{"text":"Keep your edge to yourself","consequence":"Sharing what you know lifts others and costs you nothing real."}],"debrief":"Teaching what you've learned lifts others; knowledge isn't a fixed pie."},
  {"id":"lw-1178","cat":"lift-as-you-climb","type":"branch","persona":"Arjun","source":"lift as you climb","relearn":"Ask your family to actually hear your sister's point, not brush it off.","hook":"At home, your younger sister's opinion on a family decision gets brushed off as 'too young'.","options":[{"text":"Ask the room to actually hear her point","consequence":"She's heard and learns her voice counts.","outcome":"amplify","best":true},{"text":"Stay out of it; it's not your place","consequence":"Making space for a brushed-off voice at home is leadership too."}],"debrief":"Amplifying a brushed-off voice at home is leadership, not interference."},
  {"id":"lw-1179","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Help your friend apply for the scholarship he's sure he won't get.","hook":"A gifted friend won't apply for a scholarship, certain he'll be rejected.","options":[{"text":"Encourage him and help him fill the form","consequence":"He applies, and whatever happens, he grows.","outcome":"encourage","best":true},{"text":"Agree he'd probably not get it","consequence":"A nudge plus help can change whether someone even tries."}],"debrief":"Encouraging a doubting friend to apply, and helping, lifts him to try."},
  {"id":"lw-1180","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Suggest rotating the class-rep role so newer people get a turn.","hook":"You're picked to represent the class again. The same three people always get picked.","options":[{"text":"Propose a rotation so newer people get a turn","consequence":"More classmates get a chance to lead.","outcome":"rotate","best":true},{"text":"Take it; you're good at it","consequence":"Sharing turns spreads leadership instead of hoarding it."}],"debrief":"Proposing a rotation spreads chances instead of hoarding the spotlight."},
  {"id":"lw-1181","cat":"lift-as-you-climb","type":"branch","persona":"Vijay","source":"lift as you climb","relearn":"Get the junior who coded a key part named on the win post and photo.","hook":"Your team wins a hackathon. A junior coded a key part but is left off the photo and the post.","options":[{"text":"Make sure his name is on the post and photo","consequence":"He feels seen and stays motivated to build.","outcome":"credit","best":true},{"text":"It's a small thing; let it go","consequence":"Getting an overlooked contributor named is a real lift."}],"debrief":"Making sure a quiet contributor is named keeps them in the game."},
  {"id":"lw-1182","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Back the girl who wants to play football and offer to join practice.","hook":"A classmate wants to take up football, but the group teases her that it's a 'boys' game'.","options":[{"text":"Back her and say you'll join her at practice","consequence":"She keeps playing and the teasing loses its grip.","outcome":"back","best":true},{"text":"Laugh along so you're not the odd one","consequence":"Backing someone against teasing helps them stay the course."}],"debrief":"Standing with someone against teasing helps them keep going."},
  {"id":"lw-1183","cat":"lift-as-you-climb","type":"branch","persona":"Counsellor","source":"lift as you climb","relearn":"Help the student steered out of science see her aptitude and options.","hook":"A bright student tells you she'll drop science because 'girls do humanities in our family'.","options":[{"text":"Help her see her aptitude and her real options","consequence":"She keeps her options open and chooses for herself.","outcome":"open-door","best":true},{"text":"Respect the family pattern and say nothing","consequence":"Helping her see real options is the heart of mentoring."}],"debrief":"Helping a steered-away student see her real options is true mentoring."},
  {"id":"lw-1184","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Stop the cut-offs and let the softer-spoken teammate finish her point.","hook":"In a debate practice, a softer-spoken teammate keeps getting cut off mid-sentence.","options":[{"text":"Pause the room and hand the point back to her","consequence":"She finishes, and the team hears a strong argument.","outcome":"amplify","best":true},{"text":"Let the louder voices run; it's faster","consequence":"Handing a point back to a cut-off voice amplifies them."}],"debrief":"Pausing to hand a point back to a cut-off teammate amplifies them."},
  {"id":"lw-1185","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Co-lead the assembly with a nervous junior, then let her solo.","hook":"You always lead the assembly. A nervous but capable junior has never had the chance.","options":[{"text":"Co-lead with her, then let her solo next time","consequence":"She gains confidence and a new leader emerges.","outcome":"mentor","best":true},{"text":"Keep leading; the assembly runs smoothly","consequence":"Stepping back to grow someone is leadership, not loss."}],"debrief":"Stepping back so someone new can lead grows the next leader."},
  {"id":"lw-1186","cat":"lift-as-you-climb","type":"branch","persona":"Sneha","source":"lift as you climb","relearn":"Calmly correct who actually built the winning idea when it's claimed.","hook":"Your group idea wins a prize. A boy in the team starts saying it was 'basically his idea'.","options":[{"text":"Calmly set the record straight on who built what","consequence":"The real contributors get their due, fairly.","outcome":"credit","best":true},{"text":"Let him have it to avoid a fight","consequence":"Quietly correcting credit so the real authors are seen is fair leadership."}],"debrief":"Setting the record straight on credit, calmly, protects the real authors."},
  {"id":"lw-1187","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Agree to mentor the junior and set a small weekly time to help.","hook":"A junior asks you to mentor her for a contest. You're busy and could easily say no.","options":[{"text":"Say yes and set a small weekly time to help","consequence":"She prepares well and you build a real bond.","outcome":"mentor","best":true},{"text":"Say you're too busy this time","consequence":"Giving a little steady time to a mentee is a lasting lift."}],"debrief":"Saying yes to a mentee, even briefly each week, is a lasting lift."},
  {"id":"lw-1188","cat":"lift-as-you-climb","type":"branch","persona":"any","source":"lift as you climb","relearn":"Pass the useful internship contact to the peer who needs the break more.","hook":"Your seniors hand you a useful contact for an internship. A peer needs that break more.","options":[{"text":"Share the contact with the peer who needs it","consequence":"You widen a door instead of guarding it.","outcome":"share","best":true},{"text":"Keep the contact; connections are everything","consequence":"Sharing a useful contact lifts someone and costs you little."}],"debrief":"Sharing a useful contact widens the door; opportunity isn't a fixed pie."},
  {"id":"lw-1189","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"amplify voice","relearn":"Handing the mic back to a quieter voice amplifies them.","hook":"You want to amplify a quieter teammate's point in the meeting.","setup":"Pass them the mic. Say:","yourLine":[{"text":"\"Meera raised something earlier, Meera, can you say more?\"","best":true},{"text":"Move on without them"}]},
  {"id":"lw-1190","cat":"lift-as-you-climb","type":"role-play","persona":"Vijay","source":"male allyship","relearn":"Naming that helping others is strength shuts down the 'weak' jibe.","hook":"A friend mocks you for helping a girl prepare for the maths olympiad.","setup":"Own it calmly. Say:","yourLine":[{"text":"\"Helping someone good get better is just smart, not weak.\"","best":true},{"text":"\"Fine, I'll stop, it's not worth the teasing.\""}]},
  {"id":"lw-1191","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"encouragement","relearn":"Genuine encouragement plus backing helps someone step up.","hook":"Someone doubts they belong in the role they'd be great at.","setup":"Back them genuinely. Say:","yourLine":[{"text":"\"You'd be great at this, and I'll back you if you go for it.\"","best":true},{"text":"\"It's probably not for you, honestly.\""}]},
  {"id":"lw-1192","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"name the quiet contributor","relearn":"Naming the quiet person whose work went unseen is how you lift, not just thank.","hook":"A teacher thanks the 'whole group', but Reha did the hardest part and stayed silent.","setup":"Set it straight. Say:","yourLine":[{"text":"\"Honestly, Reha worked out the tough part, that win is hers.\"","best":true},{"text":"Nod along and let the vague 'whole group' stand"}]},
  {"id":"lw-1193","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"opportunity","relearn":"Offering someone a bigger role breaks a limiting pattern.","hook":"A teammate is always handed the 'background' tasks, never the lead.","setup":"Open a bigger door. Say:","yourLine":[{"text":"\"You should lead the next part, you've more than earned it.\"","best":true},{"text":"Leave the pattern as it is"}]},
  {"id":"lw-1194","cat":"lift-as-you-climb","type":"role-play","persona":"Sneha","source":"amplify","relearn":"Crediting the first author in the chat amplifies the right person.","hook":"In a group chat, a girl's suggestion is ignored, then a boy repeats it.","setup":"Set it straight. Type:","yourLine":[{"text":"\"Yes, that's what Divya suggested above, good call to her.\"","best":true},{"text":"Just react to the boy's message"}]},
  {"id":"lw-1195","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"encouragement","relearn":"Encouraging her to try, with an offer to help, lifts her in.","hook":"A junior nearly skips a contest she'd do well in, sure she'll lose.","setup":"Nudge her in. Say:","yourLine":[{"text":"\"Even trying teaches you loads, go for it, I'll help you prep.\"","best":true},{"text":"\"Maybe sit this one out if you're unsure.\""}]},
  {"id":"lw-1196","cat":"lift-as-you-climb","type":"role-play","persona":"Arjun","source":"share load","relearn":"Taking the load yourself, unasked, lifts and models sharing.","hook":"Your mother is doing all the cleanup again after a family dinner.","setup":"Lead by lifting. Say:","yourLine":[{"text":"\"Sit, Ma, I've got the dishes, the others can clear the table.\"","best":true},{"text":"Slip away before anyone notices"}]},
  {"id":"lw-1197","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"mentor","relearn":"Saying yes to mentoring, with a real time, is a true lift.","hook":"A nervous junior asks if you'll show her how you prep for interviews.","setup":"Say yes warmly. Say:","yourLine":[{"text":"\"Of course, let's do a practice round this weekend.\"","best":true},{"text":"\"I'm pretty busy, just look it up online.\""}]},
  {"id":"lw-1198","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"credit","relearn":"Naming a co-creator when you're over-credited keeps it fair.","hook":"Your teacher praises your 'solo' poster that a friend actually co-designed.","setup":"Correct it kindly. Say:","yourLine":[{"text":"\"Thank you, but Sana co-designed it, the layout was her idea.\"","best":true},{"text":"Smile and accept the praise"}]},
  {"id":"lw-1199","cat":"lift-as-you-climb","type":"role-play","persona":"Vijay","source":"back up","relearn":"Saying out loud that she's capable backs her into the role.","hook":"A capable girl is talked over when she volunteers to captain the team.","setup":"Back her aloud. Say:","yourLine":[{"text":"\"She volunteered first and she's good, let's hear her plan.\"","best":true},{"text":"Wait for someone else to speak"}]},
  {"id":"lw-1200","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"share opportunity","relearn":"Offering a chance to who needs it more, with help, opens a door.","hook":"A scholarship form lands on your desk; a friend qualifies and needs it more.","setup":"Pass it on. Say:","yourLine":[{"text":"\"This suits you better than me, want me to help you apply?\"","best":true},{"text":"Quietly keep it for yourself"}]},
  {"id":"lw-1201","cat":"lift-as-you-climb","type":"role-play","persona":"any","source":"mentor","relearn":"Asking a mentee to help the next person multiplies the lift.","hook":"A junior thanks you and asks how he can ever repay your help.","setup":"Pass the lift forward. Say:","yourLine":[{"text":"\"Don't repay me, just help the next person who's stuck.\"","best":true},{"text":"\"Just remember it was me who helped you.\""}]},
  {"id":"lw-1202","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"make room","relearn":"Sometimes lifting others means talking less so a quieter voice can land.","hook":"Lensy: lifting others sometimes means saying less so someone quieter is heard. Could you?","prompt":"What do you think?","options":["I can try","Make room","Talk less, hear more"],"affirm":"Holding back your own turn so a quieter person gets heard is one of the realest ways to lift."},
  {"id":"lw-1203","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"lift across difference","relearn":"The biggest lift often goes to someone whose path looks nothing like yours.","hook":"Lensy: is there someone whose path looks nothing like yours that you could back?","prompt":"Think of it.","options":["Yes, there is","I'll look out","Across difference"],"affirm":"Backing someone whose background or path differs from yours is where lifting matters most."},
  {"id":"lw-1204","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"cost of silence","relearn":"Not lifting someone has a cost too: a good voice stays unheard.","hook":"Lensy: when no one speaks up for an overlooked person, something is lost too. Feel that?","prompt":"What do you think?","options":["Yes","Silence costs","A voice is lost"],"affirm":"Choosing not to lift isn't neutral; a capable person stays unseen and the room is poorer for it."},
  {"id":"lw-1205","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"future self","relearn":"Picture the older you others trust to lift them; that's who today's choices build.","hook":"Lensy: picture yourself older, the one juniors come to for a leg-up. Like that you?","prompt":"What do you think?","options":["Yes, that's me","I'd want that","Worth building toward"],"affirm":"The leader others trust to lift them isn't born; small fair choices now are exactly what build that you."},
  {"id":"lw-1206","cat":"lift-as-you-climb","type":"reflect","persona":"Vijay","source":"male allyship","relearn":"A boy lifting others on equality is strength, never weakness.","hook":"Lensy: a boy helping a girl rise, is that weakness or strength to you?","prompt":"Sit with it.","options":["Strength","Definitely strength","Maturity"],"affirm":"Choosing to lift, whatever your gender, is strength and maturity."},
  {"id":"lw-1207","cat":"lift-as-you-climb","type":"reflect","persona":"Sneha","source":"own voice","relearn":"You can lift others while you rise, not only yourself.","hook":"Lensy: where could you lift another girl this week, not just yourself?","prompt":"Picture it.","options":["My study group","A junior","A friend"],"affirm":"Lifting others alongside your own climb makes the whole room rise."},
  {"id":"lw-1208","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"not a pie","relearn":"Helping others get ahead builds teams; it doesn't set you back.","hook":"Lensy: does helping someone get ahead actually set you back?","prompt":"What do you feel?","options":["No, it doesn't","It builds trust","We both rise"],"affirm":"Leadership isn't a fixed pie, lifting others builds trust and teams."},
  {"id":"lw-1209","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"one chance","relearn":"You can share a chance instead of keeping every one.","hook":"Lensy: think of one chance you could share instead of keeping.","prompt":"Name one.","options":["A contact","A seat","A platform"],"affirm":"Even one shared chance can open a door someone needed."},
  {"id":"lw-1210","cat":"lift-as-you-climb","type":"reflect","persona":"Arjun","source":"integrity","relearn":"You can pick one quiet voice to amplify this week.","hook":"Lensy: who's the quiet person you could amplify this week?","prompt":"Picture them.","options":["A classmate","A sibling","A teammate"],"affirm":"Choosing one quiet voice to amplify is real, doable leadership."},
  {"id":"lw-1211","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"mentor","relearn":"Someone who believed in you can inspire who you lift next.","hook":"Lensy: was there someone whose belief in you changed things?","prompt":"Remember them.","options":["Yes","A teacher","A friend"],"affirm":"Remembering who believed in you can shape who you'll lift next."},
  {"id":"lw-1212","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"credit","relearn":"Knowing how it feels uncredited makes you credit others well.","hook":"Lensy: how does it feel when your work goes uncredited?","prompt":"Sit with it.","options":["Not great","Unseen","Worth fixing"],"affirm":"Knowing that feeling makes you the one who credits others well."},
  {"id":"lw-1213","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"first step","relearn":"Naming one person to lift makes it a real first step.","hook":"Lensy: who is the one person you'll lift first?","prompt":"Pick one.","options":["I know who","A junior","A friend"],"affirm":"Naming one person to lift turns a value into a real first move."},
  {"id":"lw-1214","cat":"lift-as-you-climb","type":"reflect","persona":"any","source":"steered away","relearn":"Spotting who was steered away starts you opening their door.","hook":"Lensy: who got steered away from something they'd be great at?","prompt":"Picture them.","options":["A friend","My sister","A classmate"],"affirm":"Spotting who was steered away is the start of opening their door."},
  {"id":"lw-1215","cat":"lift-as-you-climb","type":"sort","persona":"any","source":"lift vs spotlight-grab","relearn":"Mentoring, amplifying and crediting lift; hogging the mic, claiming credit and gatekeeping hold people down.","hook":"Sort: lifts the room, or grabs the spotlight?","items":[{"id":"a","text":"Mentoring a junior"},{"id":"b","text":"Hogging the mic"},{"id":"c","text":"Amplifying a quiet point"},{"id":"d","text":"Claiming a team's idea"},{"id":"e","text":"Sharing your contacts"},{"id":"f","text":"Gatekeeping a chance"}],"bins":[{"id":"lifts","label":"Lifts the room","valence":"pos"},{"id":"grabs","label":"Grabs the spotlight","valence":"neg"}],"key":{"a":"lifts","b":"grabs","c":"lifts","d":"grabs","e":"lifts","f":"grabs"}},
  {"id":"lw-1216","cat":"lift-as-you-climb","type":"sort","persona":"any","source":"real vs performative lift","relearn":"Backing, mentoring and crediting consistently is real lifting; a one-off post or empty praise is just display.","hook":"Sort: a real lift, or just for show?","items":[{"id":"a","text":"Mentoring her every week"},{"id":"b","text":"One post then nothing"},{"id":"c","text":"Helping him prep the form"},{"id":"d","text":"Praising loudly, helping never"},{"id":"e","text":"Crediting her by name"},{"id":"f","text":"A hashtag, no follow-up"}],"bins":[{"id":"real","label":"A real lift","valence":"pos"},{"id":"show","label":"Just for show","valence":"neg"}],"key":{"a":"real","b":"show","c":"real","d":"show","e":"real","f":"show"}},
  {"id":"lw-1217","cat":"lift-as-you-climb","type":"sort","persona":"any","source":"whose-idea credit","relearn":"Naming the first author, asking her to expand and citing her lifts; repeating as your own or staying silent doesn't.","hook":"Sort: credits the real author, or buries her?","items":[{"id":"a","text":"'That was Riya's idea'"},{"id":"b","text":"Repeating it as your own"},{"id":"c","text":"'Riya, say more on that'"},{"id":"d","text":"Letting the credit drift"},{"id":"e","text":"Tagging her in the post"},{"id":"f","text":"Quietly taking the praise"}],"bins":[{"id":"credits","label":"Credits the author","valence":"pos"},{"id":"buries","label":"Buries her","valence":"neg"}],"key":{"a":"credits","b":"buries","c":"credits","d":"buries","e":"credits","f":"buries"}},
  {"id":"lw-1218","cat":"lift-as-you-climb","type":"sort","persona":"any","source":"share vs hoard opportunity","relearn":"Passing on seats, contacts and turns shares opportunity; keeping every chance for yourself hoards it.","hook":"Sort: shares the chance, or hoards it?","items":[{"id":"a","text":"Offering a spare seat"},{"id":"b","text":"Keeping every chance"},{"id":"c","text":"Passing on a contact"},{"id":"d","text":"Always taking the lead role"},{"id":"e","text":"Rotating who represents"},{"id":"f","text":"Guarding a useful tip"}],"bins":[{"id":"share","label":"Shares the chance","valence":"pos"},{"id":"hoard","label":"Hoards it","valence":"neg"}],"key":{"a":"share","b":"hoard","c":"share","d":"hoard","e":"share","f":"hoard"}},
  {"id":"lw-1219","cat":"lift-as-you-climb","type":"sort","persona":"Vijay","source":"male allyship strength","relearn":"Helping a girl rise, sharing the load and backing her up is strength; mocking it or opting out is not leadership.","hook":"Sort: a strong lift by a boy, or a cop-out?","items":[{"id":"a","text":"Coaching her for the olympiad"},{"id":"b","text":"Mocking a boy who helps"},{"id":"c","text":"Doing dishes unasked"},{"id":"d","text":"'Equality's not my problem'"},{"id":"e","text":"Backing her for captain"},{"id":"f","text":"Laughing at a put-down"}],"bins":[{"id":"strong","label":"A strong lift","valence":"pos"},{"id":"cop","label":"A cop-out","valence":"neg"}],"key":{"a":"strong","b":"cop","c":"strong","d":"cop","e":"strong","f":"cop"}},
  {"id":"lw-1220","cat":"lift-as-you-climb","type":"sort","persona":"any","source":"mentor moves","relearn":"Encouraging, practising together and sharing what you learned mentors; dismissing, comparing or withholding doesn't.","hook":"Sort: mentors someone, or shuts them down?","items":[{"id":"a","text":"'You can do this, let's prep'"},{"id":"b","text":"'It's not for you'"},{"id":"c","text":"Practising a round together"},{"id":"d","text":"'I did it faster than you'"},{"id":"e","text":"Sharing your study method"},{"id":"f","text":"Hiding what worked for you"}],"bins":[{"id":"mentors","label":"Mentors them","valence":"pos"},{"id":"shuts","label":"Shuts them down","valence":"neg"}],"key":{"a":"mentors","b":"shuts","c":"mentors","d":"shuts","e":"mentors","f":"shuts"}},
  {"id":"lw-1221","cat":"lift-as-you-climb","type":"sort","persona":"any","source":"who-rises measure","relearn":"A lifted teammate, a heard voice and a grown mentee mean leadership; a solo win that left others behind doesn't.","hook":"Sort: a win that lifts, or a win that leaves people behind?","items":[{"id":"a","text":"A mentee who now leads"},{"id":"b","text":"A solo win, team unseen"},{"id":"c","text":"A quiet voice now heard"},{"id":"d","text":"Credit taken from others"},{"id":"e","text":"A teammate you backed rose"},{"id":"f","text":"A door you shut to stay ahead"}],"bins":[{"id":"lifts","label":"Lifts others too","valence":"pos"},{"id":"behind","label":"Leaves them behind","valence":"neg"}],"key":{"a":"lifts","b":"behind","c":"lifts","d":"behind","e":"lifts","f":"behind"}},
  {"id":"lw-1222","cat":"lift-as-you-climb","type":"match","persona":"any","source":"lift toolkit","relearn":"Mentoring, amplifying, sharing, crediting and backing each lift someone in a concrete way.","hook":"Match the lift to what it does.","pairs":[{"left":"Mentor","right":"Grows a beginner's skill"},{"left":"Amplify","right":"Gets a quiet voice heard"},{"left":"Share a seat","right":"Opens a closed chance"},{"left":"Credit","right":"Names the real author"},{"left":"Back up","right":"Helps someone hold the role"}]},
  {"id":"lw-1223","cat":"lift-as-you-climb","type":"match","persona":"any","source":"lift in action","relearn":"Each everyday move is a different way to lift the people around you.","hook":"Match the move to the lift it is.","pairs":[{"left":"'That was her idea'","right":"Amplifying"},{"left":"'Let's prep together'","right":"Mentoring"},{"left":"'You take the lead next'","right":"Sharing opportunity"},{"left":"'It was a team effort'","right":"Sharing credit"},{"left":"'You can do this'","right":"Encouraging"}]},
  {"id":"lw-1224","cat":"lift-as-you-climb","type":"match","persona":"any","source":"myth to flip","relearn":"Each tired myth has a truer flip about how lifting others really works.","hook":"Match the myth to its flip.","pairs":[{"left":"Help others, fall behind","right":"Lifting builds trust and teams"},{"left":"Need a title to lead","right":"Quiet everyday leading is real"},{"left":"One person can't change","right":"One lift can shift a room"},{"left":"Equality is women's job","right":"It's everyone's job"},{"left":"A boy ally is weak","right":"Leading on equality is strength"}]},
  {"id":"lw-1225","cat":"lift-as-you-climb","type":"match","persona":"Sneha","source":"values lift","relearn":"Leading from your own values shows up as specific, lifting actions you can name.","hook":"Match the value to how it lifts.","pairs":[{"left":"Fairness","right":"Crediting the real author"},{"left":"Courage","right":"Backing a long-shot friend"},{"left":"Generosity","right":"Passing on a chance"},{"left":"Patience","right":"Mentoring week by week"},{"left":"Humility","right":"Sharing a team win"}]},
  {"id":"lw-1226","cat":"lift-as-you-climb","type":"match","persona":"any","source":"who you lift","relearn":"Different overlooked people need different lifts to get their chance.","hook":"Match the person to the lift they need.","pairs":[{"left":"A shy junior","right":"A mentor's steady time"},{"left":"A talked-over girl","right":"Her point amplified"},{"left":"A doubting friend","right":"Encouragement to try"},{"left":"A steered-away student","right":"A door reopened"},{"left":"An uncredited teammate","right":"Their name on the win"}]},
  {"id":"lw-1227","cat":"lift-as-you-climb","type":"match","persona":"Vijay","source":"boys lifting","relearn":"A boy leading on equality lifts others in concrete, everyday ways, never by mocking or opting out.","hook":"Match the boy's move to the lift.","pairs":[{"left":"Coaching her for maths","right":"Mentoring a peer"},{"left":"Dishes unasked","right":"Sharing the load"},{"left":"'Let's hear her plan'","right":"Backing her voice"},{"left":"'Helping is smart'","right":"Modelling allyship"},{"left":"Naming the junior coder","right":"Sharing credit"}]},
  {"id":"lw-1228","cat":"lift-as-you-climb","type":"match","persona":"any","source":"lift vs grab","relearn":"For each lift there's a spotlight-grab that does the opposite to the same person.","hook":"Match the lift to its opposite grab.","pairs":[{"left":"Amplify her idea","right":"Repeat it as yours"},{"left":"Share the seat","right":"Keep every chance"},{"left":"Credit the team","right":"Take sole credit"},{"left":"Mentor a junior","right":"Guard your edge"},{"left":"Rotate the lead","right":"Always take it"}]},
  {"id":"lw-1229","cat":"lift-as-you-climb","type":"spot","persona":"any","source":"spotlight-grab","relearn":"Lifting credits and shares the chance; grabbing claims credit and hogs it.","hook":"Spot the two lines that grab the spotlight instead of lifting others.","scene":[{"id":"a","text":"'Great point, Asha, say more.'","trick":false},{"id":"b","text":"'Actually that was my idea, not hers.'","trick":true},{"id":"c","text":"'Let's rotate who presents.'","trick":false},{"id":"d","text":"'I'll just take the credit, easier.'","trick":true},{"id":"e","text":"'You should lead this one.'","trick":false}],"why":"The two caught lines claim others' credit and hog the chance, the opposite of lifting."},
  {"id":"lw-1230","cat":"lift-as-you-climb","type":"spot","persona":"any","source":"fake allyship","relearn":"Real lifting is consistent action; a post or empty praise is just display.","hook":"Spot the two lines that are display, not real lifting.","scene":[{"id":"a","text":"'I'll mentor her every week.'","trick":false},{"id":"b","text":"'I posted about it, that's enough.'","trick":true},{"id":"c","text":"'Let me help you fill the form.'","trick":false},{"id":"d","text":"'I praise her, but I never actually help.'","trick":true},{"id":"e","text":"'Your name goes on the win too.'","trick":false}],"why":"The two caught lines are show without follow-through, real lifting is consistent action."},
  {"id":"lw-1231","cat":"lift-as-you-climb","type":"spot","persona":"Vijay","source":"male allyship red flags","relearn":"A boy's allyship is strength; calling it weak or 'not his job' is the myth.","hook":"Spot the two lines that treat a boy's allyship as weakness.","scene":[{"id":"a","text":"'Helping her get better is just smart.'","trick":false},{"id":"b","text":"'You're soft for coaching a girl.'","trick":true},{"id":"c","text":"'I'll back her for captain.'","trick":false},{"id":"d","text":"'Equality's not a boy's problem.'","trick":true},{"id":"e","text":"'I've got the dishes, sit down.'","trick":false}],"why":"The two caught lines frame male allyship as weak or not his job, both are the myth, not the model."},
  {"id":"lw-1232","cat":"lift-as-you-climb","type":"spot","persona":"any","source":"credit theft","relearn":"Crediting the real author lifts them; claiming their work buries them.","hook":"Spot the two lines that bury who really did the work.","scene":[{"id":"a","text":"'The layout was Sana's idea.'","trick":false},{"id":"b","text":"'Basically I did the whole thing.'","trick":true},{"id":"c","text":"'Anil coded the key part.'","trick":false},{"id":"d","text":"'No need to name the juniors.'","trick":true},{"id":"e","text":"'It was a team effort, honestly.'","trick":false}],"why":"The two caught lines erase real contributors, crediting them is the lift."},
  {"id":"lw-1233","cat":"lift-as-you-climb","type":"spot","persona":"any","source":"hoarding chances","relearn":"Sharing seats and contacts lifts others; hoarding every chance doesn't.","hook":"Spot the two lines that hoard opportunity instead of sharing it.","scene":[{"id":"a","text":"'You take the seat, you'd gain more.'","trick":false},{"id":"b","text":"'I'll keep every chance for myself.'","trick":true},{"id":"c","text":"'Let's pass this contact to her.'","trick":false},{"id":"d","text":"'I always take the lead, full stop.'","trick":true},{"id":"e","text":"'Your turn to represent us.'","trick":false}],"why":"The two caught lines guard chances for one person, sharing them is how gaps close."},
  {"id":"lw-1234","cat":"lift-as-you-climb","type":"spot","persona":"any","source":"talking over","relearn":"Amplifying a quiet voice lifts it; talking over or dismissing it silences it.","hook":"Spot the two lines that silence a quieter voice instead of amplifying it.","scene":[{"id":"a","text":"'Riya, can you finish your point?'","trick":false},{"id":"b","text":"'Yeah yeah, anyway, as I was saying...'","trick":true},{"id":"c","text":"'Let's actually hear her plan.'","trick":false},{"id":"d","text":"'She's too quiet to bother with.'","trick":true},{"id":"e","text":"'Good call, that was her idea first.'","trick":false}],"why":"The two caught lines cut off or dismiss a quiet voice, amplifying it is the lift."},
  {"id":"lw-1235","cat":"lift-as-you-climb","type":"spot","persona":"Sneha","source":"discouraging","relearn":"Backing a capable girl lifts her; discouraging her shuts her down.","hook":"Spot the two lines that shut a capable girl down instead of backing her.","scene":[{"id":"a","text":"'You'd be brilliant at captain, run.'","trick":false},{"id":"b","text":"'A girl won't win here, don't bother.'","trick":true},{"id":"c","text":"'I'll help you campaign, properly.'","trick":false},{"id":"d","text":"'Leave the big roles to the boys.'","trick":true},{"id":"e","text":"'You earned the lead, take it.'","trick":false}],"why":"The two caught lines discourage a capable girl, backing her is the leadership move."},
  {"id":"lw-1236","cat":"lift-as-you-climb","type":"spot","persona":"any","source":"zero-sum myth","relearn":"Lifting others builds teams; leadership is not a fixed pie.","hook":"Spot the two lines that treat leadership as a fixed pie.","scene":[{"id":"a","text":"'Helping you costs me nothing real.'","trick":false},{"id":"b","text":"'If you rise, I fall behind.'","trick":true},{"id":"c","text":"'Lifting you builds our whole team.'","trick":false},{"id":"d","text":"'I won't teach you, you'll beat me.'","trick":true},{"id":"e","text":"'We both grow when I share this.'","trick":false}],"why":"The two caught lines assume a fixed pie, lifting others actually builds trust and teams."},
  {"id":"lw-1237","cat":"lift-as-you-climb","type":"strike-rewrite","persona":"any","source":"myth: help others fall behind","relearn":"Helping others get ahead builds teams; you don't fall behind.","hook":"Myth-flip: lift as you climb.","myth":{"un":"Helping others get ahead means you'll fall behind.","re":"Lifting others builds trust and stronger teams, leadership isn't a fixed pie.","why":"When you mentor and share, people rise with you and your standing grows, not shrinks."}},
  {"id":"lw-1238","cat":"lift-as-you-climb","type":"strike-rewrite","persona":"any","source":"abundance not scarcity","relearn":"Lifting a rival doesn't cost your spot; it grows the whole group's strength.","hook":"\"If I help a rival shine, I'm just handing them my spot.\"","myth":{"un":"Lifting someone who competes with me costs me my place.","re":"Opportunity isn't a fixed pie; backing a strong peer builds a team that carries you too.","why":"People remember who lifted them, and strong teammates raise everyone's results."}},
  {"id":"lw-1239","cat":"lift-as-you-climb","type":"strike-rewrite","persona":"Vijay","source":"myth: boy ally is weak","relearn":"A boy lifting others on equality is strength, not weakness or betrayal.","hook":"Myth-flip: lift as you climb.","myth":{"un":"A boy who helps girls get ahead is weak or betraying his side.","re":"Leading on equality is strength and maturity, and it frees boys too.","why":"Choosing to lift others takes more courage than mocking them, and equality isn't a loss for boys."}},
  {"id":"lw-1240","cat":"lift-as-you-climb","type":"strike-rewrite","persona":"any","source":"myth: one person can't","relearn":"One person lifting one other really does shift the room.","hook":"Myth-flip: lift as you climb.","myth":{"un":"One person can't change anything, so why lift anyone?","re":"One person leading by example and lifting one other genuinely shifts the room.","why":"Lift one person and they often lift the next, that's how change actually spreads."}},
  {"id":"lw-1241","cat":"lift-as-you-climb","type":"strike-rewrite","persona":"any","source":"myth: allyship is posting","relearn":"Real lifting is consistent action, not a single supportive post.","hook":"Myth-flip: lift as you climb.","myth":{"un":"Lifting others just means posting something supportive online.","re":"Real lifting is mentoring, amplifying and showing up consistently, not a one-off post.","why":"A hashtag fades by morning; steady backing of a real person is what changes their path."}},
  {"id":"lw-1242","cat":"lift-as-you-climb","type":"strike-rewrite","persona":"any","source":"myth: credit is finite","relearn":"Sharing credit grows trust in you; recognition isn't finite.","hook":"Myth-flip: lift as you climb.","myth":{"un":"If you credit others, there's less recognition left for you.","re":"Sharing credit makes people trust and follow you, recognition isn't a fixed pot.","why":"Leaders who name their team are remembered as bigger, not smaller, for it."}},
  {"id":"lw-1243","cat":"lift-as-you-climb","type":"strike-rewrite","persona":"any","source":"myth: they chose to opt out","relearn":"A steered-away person often needs encouragement, not an assumption she opted out.","hook":"Myth-flip: lift as you climb.","myth":{"un":"If a capable girl skips a role, she just chose to, no need to encourage her.","re":"Often she was steered away, and a genuine nudge plus backing reopens the door.","why":"Encouragement and support change whether someone even tries, that's the lift."}},
  {"id":"lw-1244","cat":"lift-as-you-climb","type":"strike-rewrite","persona":"any","source":"myth: mentoring wastes time","relearn":"Mentoring a junior isn't wasted time; it builds teams and trust.","hook":"Myth-flip: lift as you climb.","myth":{"un":"Mentoring a junior is a waste of time you could spend getting ahead.","re":"Time spent lifting a junior builds a stronger team and a leader people follow.","why":"The hour you give a mentee comes back as trust, skill in the team, and your own growth."}},
  {"id":"lw-900","cat":"the-gaps","type":"sort","hook":"Sort: an everyday sign of a real gap, or already fair?","items":[{"id":"a","text":"Mum cooks for everyone after her office shift"},{"id":"b","text":"Dad and son split the dishes nightly"},{"id":"c","text":"Only the daughter is asked to serve guests"},{"id":"d","text":"Both kids do equal chores"},{"id":"e","text":"Sister skips tuition to mind siblings"},{"id":"f","text":"The family shares childcare on weekends"}],"bins":[{"id":"gap","label":"Sign of a gap","valence":"neg"},{"id":"fair","label":"Already fair","valence":"pos"}],"key":{"a":"gap","b":"fair","c":"gap","d":"fair","e":"gap","f":"fair"},"relearn":"When care and chores land only on women and girls, that's the unpaid-care gap at home.","persona":"any","source":"unpaid care (verified)"},
  {"id":"lw-901","cat":"the-gaps","type":"sort","hook":"Sort: a measured fact about the gaps, or a denial myth?","items":[{"id":"a","text":"Under a quarter of women are in the paid workforce"},{"id":"b","text":"\"Women just prefer to stay home\""},{"id":"c","text":"Women average hours more unpaid care daily"},{"id":"d","text":"\"They could work if they really wanted\""},{"id":"e","text":"Boardrooms are still mostly men"},{"id":"f","text":"\"There are no barriers left for women\""}],"bins":[{"id":"fact","label":"Measured fact","valence":"pos"},{"id":"deny","label":"Denial myth","valence":"neg"}],"key":{"a":"fact","b":"deny","c":"fact","d":"deny","e":"fact","f":"deny"},"relearn":"Low participation, the care load and male-dominated boardrooms are measured, not chosen.","persona":"any","source":"participation / leadership (verified)"},
  {"id":"lw-902","cat":"the-gaps","type":"sort","hook":"Sort: closes the leadership gap, or keeps it open?","items":[{"id":"a","text":"Reserving a third of seats for women"},{"id":"b","text":"\"Politics is no place for women\""},{"id":"c","text":"Mentoring a junior woman for a lead role"},{"id":"d","text":"Only ever picking men to present"},{"id":"e","text":"Naming a woman as project head on merit"},{"id":"f","text":"Talking over her in every meeting"}],"bins":[{"id":"close","label":"Closes it","valence":"pos"},{"id":"keep","label":"Keeps it open","valence":"neg"}],"key":{"a":"close","b":"keep","c":"close","d":"keep","e":"close","f":"keep"},"relearn":"Reserved seats, mentoring and merit-based picks close the leadership gap; exclusion keeps it.","persona":"any","source":"leadership gap / Women's Reservation Act"},
  {"id":"lw-903","cat":"the-gaps","type":"sort","hook":"Sort: a structural cause of the pay gap, or a 'just choice' myth?","items":[{"id":"a","text":"The unpaid-care load eating women's hours"},{"id":"b","text":"\"Women simply pick lower-paying jobs\""},{"id":"c","text":"Bias against hiring mothers"},{"id":"d","text":"\"It's their free choice, nothing more\""},{"id":"e","text":"Fewer promotions offered to women"},{"id":"f","text":"\"Nobody is holding them back\""}],"bins":[{"id":"cause","label":"Structural cause","valence":"pos"},{"id":"choice","label":"'Just choice' myth","valence":"neg"}],"key":{"a":"cause","b":"choice","c":"cause","d":"choice","e":"cause","f":"choice"},"relearn":"Bias and the care load drive much of the pay gap; it isn't simply women's 'choice'.","persona":"any","source":"pay gap (verified)"},
  {"id":"lw-904","cat":"the-gaps","type":"sort","hook":"Sort: who carries the unpaid-care load in most Indian homes?","items":[{"id":"a","text":"Cooking three meals a day"},{"id":"b","text":"Nursing a sick grandparent"},{"id":"c","text":"Helping kids with homework nightly"},{"id":"d","text":"Doing the day's washing and cleaning"},{"id":"e","text":"Driving the family car once a week"},{"id":"f","text":"Fixing a leaking tap on Sunday"}],"bins":[{"id":"women","label":"Usually women","valence":"neg"},{"id":"shared","label":"Often shared/men","valence":"neutral"}],"key":{"a":"women","b":"women","c":"women","d":"women","e":"shared","f":"shared"},"relearn":"The daily, invisible care work lands mostly on women, far more than men.","persona":"any","source":"unpaid care (verified)"},
  {"id":"lw-905","cat":"the-gaps","type":"sort","hook":"Sort: a fixable system, or 'just how things are'?","items":[{"id":"a","text":"Workplace creches so mothers can stay employed"},{"id":"b","text":"\"Women leaving work is just natural\""},{"id":"c","text":"Paid leave shared by both parents"},{"id":"d","text":"\"You can't change how families work\""},{"id":"e","text":"Pay audits to catch unequal pay"},{"id":"f","text":"\"The gap will close on its own someday\""}],"bins":[{"id":"fix","label":"Fixable system","valence":"pos"},{"id":"fate","label":"'Just fate' myth","valence":"neg"}],"key":{"a":"fix","b":"fate","c":"fix","d":"fate","e":"fix","f":"fate"},"relearn":"Creches, shared leave and pay audits fix the gaps; 'it's just natural' is the myth.","persona":"any","source":"fixable, not fate"},
  {"id":"lw-906","cat":"the-gaps","type":"sort","hook":"Sort: an honest read of the gaps, or a way to dismiss them?","items":[{"id":"a","text":"\"The gaps are real but shrinking\""},{"id":"b","text":"\"Talking about it is just complaining\""},{"id":"c","text":"\"Data shows where to act\""},{"id":"d","text":"\"Equality already happened, move on\""},{"id":"e","text":"\"Both bias and care load matter\""},{"id":"f","text":"\"It's one-sided to even raise it\""}],"bins":[{"id":"honest","label":"Honest read","valence":"pos"},{"id":"dismiss","label":"Dismissal","valence":"neg"}],"key":{"a":"honest","b":"dismiss","c":"honest","d":"dismiss","e":"honest","f":"dismiss"},"relearn":"Naming measured gaps to act on them is honest, not complaining or one-sided.","persona":"any","source":"naming the gaps"},
  {"id":"lw-907","cat":"the-gaps","type":"sort","hook":"Vijay sorts: does this make the gap better or worse?","items":[{"id":"a","text":"A brother cooking so his sister can study"},{"id":"b","text":"\"Housework is below a man\""},{"id":"c","text":"Dad attending the parent meeting"},{"id":"d","text":"Only sons sent for higher studies"},{"id":"e","text":"Backing a sister's job application"},{"id":"f","text":"\"Her salary doesn't matter\""}],"bins":[{"id":"better","label":"Closes the gap","valence":"pos"},{"id":"worse","label":"Widens it","valence":"neg"}],"key":{"a":"better","b":"worse","c":"better","d":"worse","e":"better","f":"worse"},"relearn":"Boys sharing care and backing women's study and work shrinks the gap, not their standing.","persona":"Vijay","source":"male allyship (links what-allyship-is)"},
  {"id":"lw-908","cat":"the-gaps","type":"sort","hook":"Sort: a true cost of the gaps, or a false claim?","items":[{"id":"a","text":"Talented women's skills going unused"},{"id":"b","text":"\"Closing gaps costs men their jobs\""},{"id":"c","text":"Families poorer on one income"},{"id":"d","text":"\"Equality just means men suffer\""},{"id":"e","text":"Girls dropping out to do care work"},{"id":"f","text":"\"There is no real cost to anyone\""}],"bins":[{"id":"true","label":"Real cost","valence":"pos"},{"id":"false","label":"False claim","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"The gaps cost families and talent; equality lifts everyone, it isn't a loss for men.","persona":"any","source":"not zero-sum (links g26)"},
  {"id":"lw-909","cat":"the-gaps","type":"sort","hook":"Sort: a place women are under-represented, or already balanced?","items":[{"id":"a","text":"High-court judges"},{"id":"b","text":"Primary-school teachers"},{"id":"c","text":"Company board members"},{"id":"d","text":"Nurses in hospitals"},{"id":"e","text":"State legislators"},{"id":"f","text":"Front-line nursing staff"}],"bins":[{"id":"under","label":"Few women","valence":"neg"},{"id":"balanced","label":"Many women","valence":"neutral"}],"key":{"a":"under","b":"balanced","c":"under","d":"balanced","e":"under","f":"balanced"},"relearn":"Women are scarce in judging, boards and legislatures, the rooms where power sits.","persona":"any","source":"leadership gap"},
  {"id":"lw-910","cat":"the-gaps","type":"sort","hook":"Sort: this belief helps you lead on the gaps, or holds you back?","items":[{"id":"a","text":"\"The gaps are fixable if we act\""},{"id":"b","text":"\"One person can't change anything\""},{"id":"c","text":"\"My everyday choices matter\""},{"id":"d","text":"\"It's not my problem to solve\""},{"id":"e","text":"\"I can lift one person this week\""},{"id":"f","text":"\"Nothing I do will help\""}],"bins":[{"id":"lead","label":"Helps you lead","valence":"pos"},{"id":"stuck","label":"Holds you back","valence":"neg"}],"key":{"a":"lead","b":"stuck","c":"lead","d":"stuck","e":"lead","f":"stuck"},"relearn":"Believing the gaps are fixable and your choices count is what turns into leadership.","persona":"any","source":"agency (bridge to leadership)"},
  {"id":"lw-911","cat":"the-gaps","type":"sort","hook":"Sort: a fact backed by data, or an opinion dressed as fact?","items":[{"id":"a","text":"Women carry more unpaid care, by survey"},{"id":"b","text":"\"Women are naturally worse at work\""},{"id":"c","text":"Boards are mostly men, by count"},{"id":"d","text":"\"Men just deserve to earn more\""},{"id":"e","text":"Fewer women hold top legal posts"},{"id":"f","text":"\"Leadership isn't in women's nature\""}],"bins":[{"id":"data","label":"Backed by data","valence":"pos"},{"id":"opinion","label":"Bias as 'fact'","valence":"neg"}],"key":{"a":"data","b":"opinion","c":"data","d":"opinion","e":"data","f":"opinion"},"relearn":"The gaps come from counts and surveys; 'women are naturally worse' is bias, not data.","persona":"any","source":"data vs bias"},
  {"id":"lw-912","cat":"the-gaps","type":"sort","hook":"Sneha sorts: a barrier she faces, or a fair hurdle everyone faces?","items":[{"id":"a","text":"Told marriage matters more than her degree"},{"id":"b","text":"A tough entrance exam she must crack"},{"id":"c","text":"Relatives doubting a girl needs a career"},{"id":"d","text":"Limited seats in a popular course"},{"id":"e","text":"Curfew rules only for the daughter"},{"id":"f","text":"High fees the whole family must plan for"}],"bins":[{"id":"gender","label":"Gender barrier","valence":"neg"},{"id":"shared","label":"Faced by all","valence":"neutral"}],"key":{"a":"gender","b":"shared","c":"gender","d":"shared","e":"gender","f":"shared"},"relearn":"Some hurdles fall on girls just for being girls; naming them is how you start to lead.","persona":"Sneha","source":"double standard (the gaps, lived)"},
  {"id":"lw-913","cat":"the-gaps","type":"sort","hook":"Sort: a sign the leadership gap is closing, or that it's stuck?","items":[{"id":"a","text":"A woman elected village sarpanch"},{"id":"b","text":"\"Let a man chair it, he's senior\""},{"id":"c","text":"A girl made school head prefect"},{"id":"d","text":"Only boys nominated for captain"},{"id":"e","text":"A woman heading the science club"},{"id":"f","text":"\"She can take notes, he'll lead\""}],"bins":[{"id":"closing","label":"Gap closing","valence":"pos"},{"id":"stuck","label":"Gap stuck","valence":"neg"}],"key":{"a":"closing","b":"stuck","c":"closing","d":"stuck","e":"closing","f":"stuck"},"relearn":"Women and girls actually leading rooms, from panchayats to clubs, is the gap closing.","persona":"any","source":"leadership gap (everyday)"},
  {"id":"lw-920","cat":"the-gaps","type":"match","hook":"Match each fact to the gap it describes.","pairs":[{"left":"Women earn less for similar work","right":"The pay gap"},{"left":"283 minutes of unpaid care a day","right":"The care gap"},{"left":"Few women in boards and benches","right":"The leadership gap"},{"left":"Under a quarter of women in paid jobs","right":"The participation gap"},{"left":"A third of seats reserved by law","right":"A fix in progress"}],"relearn":"Pay, care, leadership and participation are four measured gaps, with fixes underway.","persona":"any","source":"unpaid care / participation (verified)"},
  {"id":"lw-921","cat":"the-gaps","type":"match","hook":"Match the myth to the truth that answers it.","pairs":[{"left":"\"The pay gap is just choice\"","right":"Bias and care load drive much of it"},{"left":"\"Care work isn't real work\"","right":"It's huge, essential, unpaid labour"},{"left":"\"Women dislike leadership\"","right":"Barriers, not interest, keep them out"},{"left":"\"Equality means men lose\"","right":"It lifts everyone, men included"},{"left":"\"One person can't help\"","right":"One person lifting one shifts a room"}],"relearn":"Each tired myth about the gaps has a true, evidence-based answer.","persona":"any","source":"myth-flips (verified)"},
  {"id":"lw-922","cat":"the-gaps","type":"match","hook":"Match the everyday action to the gap it chips away at.","pairs":[{"left":"Brother shares the cooking","right":"The care gap"},{"left":"Equal pay for the same role","right":"The pay gap"},{"left":"Nominating a woman to lead","right":"The leadership gap"},{"left":"Backing a girl's first job","right":"The participation gap"},{"left":"Encouraging her into engineering","right":"A steered-away career path"}],"relearn":"Small, everyday choices map directly onto the real gaps and shrink them.","persona":"any","source":"levers (everyday)"},
  {"id":"lw-923","cat":"the-gaps","type":"match","hook":"Match the cause to the gap it helps create.","pairs":[{"left":"Hiring bias against mothers","right":"Pay and promotion gap"},{"left":"Care load left to women","right":"Less time for paid work"},{"left":"Steering girls from STEM","right":"Fewer women in tech"},{"left":"Curfews only for daughters","right":"Narrower chances to lead"},{"left":"\"Boys present, girls note\"","right":"A blocked path to visibility"}],"relearn":"Bias, the care load and gendered steering are the engines behind the gaps.","persona":"any","source":"structural causes"},
  {"id":"lw-924","cat":"the-gaps","type":"match","hook":"Match the policy or law to what it's meant to fix.","pairs":[{"left":"Women's Reservation Act","right":"Few women in legislatures"},{"left":"Equal-pay rules","right":"Unequal pay for equal work"},{"left":"Maternity and parental leave","right":"Mothers pushed out of jobs"},{"left":"Beti Bachao Beti Padhao","right":"Girls denied schooling"},{"left":"Workplace creches","right":"No childcare while working"}],"relearn":"India has named fixes for each gap, from reserved seats to childcare at work.","persona":"any","source":"Women's Reservation Act 2023 / BBBP (verified)"},
  {"id":"lw-925","cat":"the-gaps","type":"match","hook":"Vijay matches: the worry to the truth that answers it.","pairs":[{"left":"\"Supporting this makes me weak\"","right":"Leading on equality is strength"},{"left":"\"It's betraying other guys\"","right":"It's everyone's job, not a side"},{"left":"\"I'll fall behind helping her\"","right":"Lifting others isn't a fixed pie"},{"left":"\"Chores aren't a man's role\"","right":"Sharing care leads by example"},{"left":"\"Equality is a loss for men\"","right":"It frees boys from rigid roles"}],"relearn":"Every fear about backing equality has a true answer: it's strength, shared, and frees men too.","persona":"Vijay","source":"male allyship reframe (verified)"},
  {"id":"lw-926","cat":"the-gaps","type":"match","hook":"Match the room to who usually still leads it.","pairs":[{"left":"The boardroom","right":"Mostly men"},{"left":"The kitchen at home","right":"Mostly women"},{"left":"The legislature","right":"Far fewer women"},{"left":"The unpaid care at home","right":"Largely women"},{"left":"The panchayat with reserved seats","right":"More women, by law"}],"relearn":"Power rooms skew male while care skews female, until laws like reservation shift it.","persona":"any","source":"leadership / care gap (verified)"},
  {"id":"lw-940","cat":"the-gaps","type":"strike-rewrite","hook":"\"Once a woman has kids, of course her pay drops, that's just life.\"","myth":{"un":"A mother's pay dropping is just natural and unavoidable.","re":"The 'motherhood penalty' is bias and unshared care, not a law of nature; fathers' pay rarely falls.","why":"Shared care and fairer leave shrink the gap that opens after kids."},"relearn":"The motherhood pay penalty comes from bias and care load, not nature.","persona":"any","source":"motherhood penalty (verified)"},
  {"id":"lw-941","cat":"the-gaps","type":"strike-rewrite","hook":"\"If men did housework it'd just be a hobby, not a real shift.\"","myth":{"un":"Men doing housework is a nice extra, not a real change.","re":"When men share care evenly, women's paid-work hours and the home norm both shift for good.","why":"The care gap is the engine behind much of the pay and time gap."},"relearn":"Men sharing care isn't a hobby; it directly closes women's time and pay gap.","persona":"Arjun","source":"unpaid care / men's share (verified)"},
  {"id":"lw-942","cat":"the-gaps","type":"strike-rewrite","hook":"\"A woman who leads firmly is just bossy, that's why people don't pick them.\"","myth":{"un":"Women don't get picked to lead because firm ones come off as bossy.","re":"The same firmness is read as 'strong' in a man and 'bossy' in a woman; that double standard is the barrier, not her.","why":"Naming the double bind is how a group stops penalising women for leading."},"relearn":"The 'bossy' label is a double standard on leadership, not a real flaw.","persona":"Sneha","source":"likeability double-bind"},
  {"id":"lw-943","cat":"the-gaps","type":"strike-rewrite","hook":"\"Gender stuff is all about women; it's got nothing for guys.\"","myth":{"un":"Gender equality is only about women and offers boys nothing.","re":"The same rigid roles that hold women back also box boys in, 'be tough, never cry'; loosening them frees boys too.","why":"Boys gain room to feel and ask for help when the old script eases."},"relearn":"Rigid gender roles box boys in too; equality gives them room to breathe.","persona":"Vijay","source":"rigid roles harm boys"},
  {"id":"lw-944","cat":"the-gaps","type":"strike-rewrite","hook":"\"Women hardly even work, so there's no real gap.\"","myth":{"un":"Women hardly work, so there's no real gap.","re":"Under a quarter are in paid jobs partly because of the care load.","why":"Unpaid care at home is real work that crowds out paid work."},"relearn":"Low paid-work participation reflects the care load, not a lack of effort.","persona":"any","source":"participation (verified)"},
  {"id":"lw-945","cat":"the-gaps","type":"strike-rewrite","hook":"\"There's no leadership gap, women just don't apply.\"","myth":{"un":"There's no leadership gap, women just don't apply.","re":"Boards, benches and legislatures are still mostly men.","why":"Even where women apply, bias thins them out near the top."},"relearn":"The leadership gap is measured in real rooms, not down to who applies.","persona":"any","source":"leadership gap"},
  {"id":"lw-946","cat":"the-gaps","type":"strike-rewrite","hook":"\"These gaps are made-up statistics.\"","myth":{"un":"These gender gaps are just made-up statistics.","re":"They're measured by surveys and counts you can check.","why":"Time-use surveys and headcounts aren't invented, they're recorded."},"relearn":"The gaps are measured and verifiable; calling them invented is itself the myth.","persona":"any","source":"data, not invented"},
  {"id":"lw-947","cat":"the-gaps","type":"strike-rewrite","hook":"\"A man doing chores looks weak.\"","myth":{"un":"A man who shares the housework looks weak.","re":"Sharing the load is maturity and leadership by example.","why":"It quietly resets the home norm better than any lecture."},"relearn":"Sharing care is strength and example-setting, not weakness.","persona":"Vijay","source":"male allyship (links lead-by-example)"},
  {"id":"lw-948","cat":"the-gaps","type":"strike-rewrite","hook":"\"Reserving seats for women is unfair to men.\"","myth":{"un":"Reserving seats for women is unfair to men.","re":"It corrects a long, measured shortfall of women in power.","why":"Levelling a tilted field isn't a loss; it's overdue balance."},"relearn":"Reserved seats counter a real leadership gap; it's repair, not unfairness.","persona":"any","source":"Women's Reservation Act 2023 (verified)"},
  {"id":"lw-949","cat":"the-gaps","type":"strike-rewrite","hook":"\"Helping a junior get ahead means I fall behind.\"","myth":{"un":"Helping a junior get ahead means I fall behind.","re":"Lifting others builds trust and teams; it's not a fixed pie.","why":"Leaders are measured by who rises with them."},"relearn":"Helping others rise isn't a loss; leadership isn't a fixed pie.","persona":"any","source":"lift as you climb (links signature cat)"},
  {"id":"lw-950","cat":"the-gaps","type":"strike-rewrite","hook":"\"If she really wanted to work, she would.\"","myth":{"un":"If she really wanted to work, she just would.","re":"Care duties and curfews block many women before they start.","why":"Wanting a job doesn't remove the load others won't share."},"relearn":"Barriers, not willpower, keep many women out of paid work.","persona":"any","source":"participation / care load"},
  {"id":"lw-951","cat":"the-gaps","type":"strike-rewrite","hook":"\"Gender equality is a women's issue, not ours.\"","myth":{"un":"Gender equality is a women's issue, not ours.","re":"It's everyone's job; engaging boys is a top lever for it.","why":"Norms shift fastest when the whole room owns them."},"relearn":"Equality is everyone's job, and bringing boys in is one of the strongest levers.","persona":"Vijay","source":"everyone's job (HeForShe)"},
  {"id":"lw-952","cat":"the-gaps","type":"strike-rewrite","hook":"\"The gaps will just close on their own.\"","myth":{"un":"The gaps will close on their own with time.","re":"They close when people and policies act, not by waiting.","why":"Progress so far came from effort, laws and example, not drift."},"relearn":"The gaps close through action and policy, not by waiting them out.","persona":"any","source":"fixable, not fate"},
  {"id":"lw-953","cat":"the-gaps","type":"strike-rewrite","hook":"\"One student can't do anything about gaps this big.\"","myth":{"un":"One student can't do anything about gaps this big.","re":"One person leading by example and lifting one other shifts the room.","why":"Rooms change person by person, and you're a person in yours."},"relearn":"One person leading and lifting one other genuinely shifts the room.","persona":"any","source":"agency (myth-flip 8)"},
  {"id":"lw-960","cat":"the-gaps","type":"reflect","hook":"Lensy: in village councils with reserved seats, women leaders raised spending on water and schools. Surprised?","prompt":"What do you think?","options":["Makes sense","A bit","Not really"],"affirm":"Studies of reserved panchayat seats found women leaders shifted priorities toward water, roads and schools.","relearn":"Where women led reserved councils, spending on water and schools rose.","persona":"any","source":"panchayat reservation studies (verified)"},
  {"id":"lw-961","cat":"the-gaps","type":"reflect","hook":"Lensy: men who share care report closer bonds with their kids and less burnout at home. Worth it for them too?","prompt":"What do you think?","options":["Yes","For everyone","Hadn't thought of it"],"affirm":"Sharing care isn't only fair to women; men who do it report closer kids and a calmer home, so everyone gains.","relearn":"Sharing care helps men too: closer family bonds, not just fairness.","persona":"Arjun","source":"shared care / men's gain"},
  {"id":"lw-962","cat":"the-gaps","type":"reflect","hook":"Lensy: of all the places you spend time, where could you most easily nudge things fairer?","prompt":"Pick one.","options":["At home","In class","With friends","Online"],"affirm":"Your closest circle, home, class, friends, online, is exactly where your nudge actually lands.","relearn":"Start where your reach is real: home, class, friends, your own feed.","persona":"any","source":"circle of influence"},
  {"id":"lw-963","cat":"the-gaps","type":"reflect","hook":"Lensy: which root cause do you think feeds the gaps the most?","prompt":"Pick one.","options":["Unequal care at home","Bias in hiring","Steering girls' choices early"],"affirm":"All three feed the gaps; spotting which one you see most lets you aim your effort where it bites.","relearn":"Care load, hiring bias and early steering are root causes you can target.","persona":"any","source":"root causes"},
  {"id":"lw-964","cat":"the-gaps","type":"reflect","hook":"Lensy: think of the unpaid care in your own home. Who carries most of it?","prompt":"What comes to mind?","options":["Mum mostly","It's getting shared","I want to help more"],"affirm":"Noticing who carries the load at home is the first honest step toward sharing it.","relearn":"Seeing the care imbalance at home is where leading on it begins.","persona":"any","source":"unpaid care (lived)"},
  {"id":"lw-965","cat":"the-gaps","type":"reflect","hook":"Lensy: have you ever seen a girl talked over or steered away from something she was good at?","prompt":"What do you remember?","options":["Yes, often","Once or twice","I'll watch for it"],"affirm":"Spotting where the gaps play out in real life is what makes you ready to lead on them.","relearn":"The gaps show up in everyday moments you can learn to notice.","persona":"any","source":"awareness"},
  {"id":"lw-966","cat":"the-gaps","type":"reflect","hook":"Lensy: someone says the gaps are 'over-exaggerated.' What sits with you?","prompt":"Your honest take?","options":["The data says otherwise","I'd want to check facts","I'd hear them out, then share"],"affirm":"Meeting a denial with facts and good faith is exactly how you lead on this.","relearn":"The gaps are measured; answering doubt with evidence and calm is leadership.","persona":"any","source":"data vs denial"},
  {"id":"lw-967","cat":"the-gaps","type":"reflect","hook":"Lensy: equality is sometimes called a 'women's issue.' Where do you stand?","prompt":"What do you think?","options":["It's everyone's","Boys matter here too","I'm in either way"],"affirm":"Owning equality as everyone's job, your job too, is the heart of leading on it.","relearn":"Equality is everyone's job; that ownership is where leadership starts.","persona":"any","source":"everyone's job"},
  {"id":"lw-968","cat":"the-gaps","type":"reflect","hook":"Vijay: a friend says backing equality makes a guy look weak. What feels true to you?","prompt":"Your gut?","options":["It's actually strength","It's just maturity","I'd back it anyway"],"affirm":"Backing equality is strength and maturity; standing by that is real leadership.","relearn":"Leading on equality is strength, not weakness, for boys and men.","persona":"Vijay","source":"male allyship reframe"},
  {"id":"lw-969","cat":"the-gaps","type":"reflect","hook":"Lensy: 'one person can't change a gap this big.' Does that ring true to you?","prompt":"What do you feel?","options":["No, I can start small","One room at a time","I'll lift one person"],"affirm":"Starting small and lifting one person is exactly how big gaps begin to close.","relearn":"One person leading and lifting one other really does shift the room.","persona":"any","source":"agency (myth-flip 8)"},
  {"id":"lw-970","cat":"the-gaps","type":"reflect","hook":"Sneha: relatives say a degree matters less than marriage for a girl. What's your honest read?","prompt":"What sits with you?","options":["My education matters","Both can wait their turn","I lead from my values"],"affirm":"Your education and your choices are yours; leading from your own values is real strength.","relearn":"A girl's education and ambitions are real; she leads best from her own values.","persona":"Sneha","source":"double standard / lead from values"},
  {"id":"lw-971","cat":"the-gaps","type":"reflect","hook":"Lensy: which feels like the most useful first thing to understand about the gaps?","prompt":"Pick what resonates.","options":["They're real, not invented","They're caused, not chosen","They're fixable, not fate"],"affirm":"Real, caused and fixable are all true, and any one of them is a strong place to start.","relearn":"The gaps are real, caused by systems, and fixable, three true anchors.","persona":"any","source":"the three anchors"},
  {"id":"lw-972","cat":"the-gaps","type":"reflect","hook":"Lensy: if you could shrink one gap in your own school or street, which would you pick?","prompt":"Where would you start?","options":["Who leads clubs","Who does the chores","Who gets encouraged"],"affirm":"Anywhere you choose to start is real; the point is you picked a place to lead.","relearn":"The gaps live in everyday places you can choose to lead on.","persona":"any","source":"local agency"},
  {"id":"lw-973","cat":"the-gaps","type":"reflect","hook":"Lensy: how does it feel to learn the gaps are measured and fixable, not just 'how things are'?","prompt":"What comes up?","options":["Hopeful","Motivated","A bit fired up"],"affirm":"That feeling, whatever it is, is the spark that turns understanding into action.","relearn":"Knowing the gaps are fixable is meant to move you toward acting on them.","persona":"any","source":"realism + hope"},
  {"id":"lw-974","cat":"the-gaps","type":"reflect","hook":"Arjun: at home you already share the cooking and cleaning. How does leading by example sit with you?","prompt":"Your take?","options":["It feels natural","It sets a norm","I'd do more"],"affirm":"Sharing the load visibly is quiet leadership; living it is exactly how the norm shifts.","relearn":"Sharing care visibly at home is real, everyday leadership on the gaps.","persona":"Arjun","source":"lead by example (lived)"},
  {"id":"lw-975","cat":"the-gaps","type":"reflect","hook":"Lensy: leading on the gaps doesn't have to be loud. Which way fits you?","prompt":"Pick one.","options":["Quietly model it","Speak up in the moment","Back others to lead"],"affirm":"There's no single way to lead on the gaps; modelling, speaking up and backing others all genuinely count.","relearn":"Leading on the gaps comes in many styles; pick the one that's really you.","persona":"any","source":"leadership styles"},
  {"id":"lw-976","cat":"the-gaps","type":"reflect","hook":"Lensy: what's one tiny thing you could do this week that touches a real gap?","prompt":"What comes to mind?","options":["Share a chore","Back someone's voice","Encourage a friend"],"affirm":"Any small, real action this week is leadership; the size doesn't matter, the doing does.","relearn":"A real plan is one small, specific action you'll actually do this week.","persona":"any","source":"first action"},
  {"id":"lw-980","cat":"the-gaps","type":"role-play","hook":"An uncle says: \"There's no pay gap, women just pick easy jobs.\" What do you say back?","setup":"Family dinner, an uncle is sure the pay gap is a myth. You want to answer with facts, kindly.","yourLine":[{"text":"\"Actually, women earn less for the same work, it's mostly bias and care load.\"","best":true},{"text":"\"Yeah, maybe you're right, I'm not sure.\""},{"text":"\"Whatever, can we just eat.\""}],"persona":"any","source":"pay gap (verified)","relearn":"Women earn less for the same work; it's mostly bias and the care load."},
  {"id":"lw-981","cat":"the-gaps","type":"role-play","hook":"A classmate says: \"Housework isn't real work.\" How do you respond?","setup":"A group chat about home. A friend brushes off all the cooking and care his mum does.","yourLine":[{"text":"\"It's hours of real work every day, it just isn't paid or counted.\"","best":true},{"text":"\"Haha I guess, never thought about it.\""},{"text":"\"Anyway, what's for the trip plan.\""}],"persona":"any","source":"unpaid care (verified)","relearn":"Housework is hours of real, daily labour, just unpaid and uncounted."},
  {"id":"lw-982","cat":"the-gaps","type":"role-play","hook":"Vijay's friend: \"You're always taking the girls' side now.\" What do you say?","setup":"Vijay keeps backing his classmates' equal share. A friend calls it picking a side.","yourLine":[{"text":"\"It's not sides, fairness helps everyone, and standing for it is just being decent.\"","best":true},{"text":"\"Fine, I'll stay out of it then.\""},{"text":"\"You're right, my bad, forget it.\""}],"persona":"Vijay","source":"male allyship reframe","relearn":"Backing fairness isn't picking a side; it helps everyone and it's just decent."},
  {"id":"lw-983","cat":"the-gaps","type":"role-play","hook":"Someone says: \"Reserving seats for women is just unfair.\" Your reply?","setup":"A debate-club warm-up. A peer argues the Women's Reservation Act is reverse unfairness.","yourLine":[{"text":"\"It fixes a long shortfall of women in power, that's balancing, not unfair.\"","best":true},{"text":"\"Maybe, I haven't really decided.\""},{"text":"\"Let's not argue about politics.\""}],"persona":"any","source":"Women's Reservation Act 2023 (verified)","relearn":"Reserved seats balance a long shortfall of women in power; that's repair, not unfairness."},
  {"id":"lw-984","cat":"the-gaps","type":"role-play","hook":"A teammate: \"Helping her present means you'll look less good.\" What do you say?","setup":"A group project. A teammate warns that backing a quieter member will cost you credit.","yourLine":[{"text":"\"Lifting her makes the whole team stronger, that's not a loss for me.\"","best":true},{"text":"\"Hmm, maybe I should just do it myself then.\""},{"text":"\"Yeah, good point, I'll take the lead instead.\""}],"persona":"any","source":"lift as you climb","relearn":"Lifting a teammate makes the whole team stronger; it's not a loss for you."},
  {"id":"lw-985","cat":"the-gaps","type":"role-play","hook":"Sneha hears: \"Why study so hard, you'll just get married.\" Her answer?","setup":"A relative questions Sneha's late-night studying for boards. She answers from her values.","yourLine":[{"text":"\"My education is mine, whatever else comes, and I'm not trading it away.\"","best":true},{"text":"\"I suppose, maybe it doesn't matter much.\""},{"text":"\"I don't know, you might be right.\""}],"persona":"Sneha","source":"double standard / lead from values","relearn":"A girl's education is hers to keep; she leads best from her own values."},
  {"id":"lw-986","cat":"the-gaps","type":"role-play","hook":"A friend: \"Equality is women's business, why do you care?\" Your line?","setup":"You keep raising fairness at home and school. A friend asks why it's even your concern.","yourLine":[{"text":"\"It's everyone's business, and boys speaking up is one of the strongest levers.\"","best":true},{"text":"\"True, it's not really my thing.\""},{"text":"\"I guess I'll leave it to them then.\""}],"persona":"any","source":"everyone's job (HeForShe)","relearn":"Equality is everyone's business; boys speaking up is one of the strongest levers."},
  {"id":"lw-987","cat":"the-gaps","type":"role-play","hook":"Someone shrugs: \"One person can't change anything anyway.\" What do you say?","setup":"You suggest sharing chores fairly at home. A sibling says nothing you do will matter.","yourLine":[{"text":"\"One person living it shifts the room, I'd rather start than wait.\"","best":true},{"text":"\"Yeah, you're probably right, why bother.\""},{"text":"\"Fine, I'll drop it I guess.\""}],"persona":"any","source":"agency (myth-flip 8)","relearn":"One person living the change shifts the room; starting beats waiting."},
  {"id":"lw-990","cat":"the-gaps","type":"spot","hook":"Spot the two lines that DENY the real, measured gaps.","scene":[{"id":"a","text":"Women carry far more unpaid care at home","trick":false},{"id":"b","text":"\"There's honestly no pay gap left\"","trick":true},{"id":"c","text":"Boards and benches are still mostly men","trick":false},{"id":"d","text":"\"Women just aren't built to lead\"","trick":true},{"id":"e","text":"A law now reserves seats for women","trick":false}],"why":"Both flagged lines deny measured facts: the pay gap is real, and the leadership gap is barriers, not biology.","relearn":"The gaps are measured; flat denials like these are the myth.","persona":"any","source":"data vs denial"},
  {"id":"lw-991","cat":"the-gaps","type":"spot","hook":"Spot the two lines that blame women for the gaps instead of the system.","scene":[{"id":"a","text":"Bias makes hiring mothers harder","trick":false},{"id":"b","text":"\"They just don't try hard enough\"","trick":true},{"id":"c","text":"The care load eats women's work hours","trick":false},{"id":"d","text":"\"It's pure laziness, nothing else\"","trick":true},{"id":"e","text":"Steering girls from STEM narrows careers","trick":false}],"why":"The flagged lines pin the gap on women's effort; the real causes are bias, care load and steering.","relearn":"The gaps are structural; 'they don't try' is victim-blaming, not a cause.","persona":"any","source":"structural vs blame"},
  {"id":"lw-992","cat":"the-gaps","type":"spot","hook":"Spot the two lines that frame equality as men losing out.","scene":[{"id":"a","text":"Sharing care frees boys from rigid roles","trick":false},{"id":"b","text":"\"Equality just means men suffer\"","trick":true},{"id":"c","text":"Fairer homes make families stronger","trick":false},{"id":"d","text":"\"Every gain for her is a loss for me\"","trick":true},{"id":"e","text":"Equality lifts everyone, men included","trick":false}],"why":"The flagged lines treat equality as zero-sum; in truth it's not a loss for men, it lifts everyone.","relearn":"Equality isn't men losing out; it lifts everyone, men included.","persona":"any","source":"not zero-sum (links g26)"},
  {"id":"lw-993","cat":"the-gaps","type":"spot","hook":"Spot the two lines that wave away unpaid care as 'not work.'","scene":[{"id":"a","text":"Cooking and cleaning is hours of daily labour","trick":false},{"id":"b","text":"\"Housework isn't really work\"","trick":true},{"id":"c","text":"Care work holds families and the economy up","trick":false},{"id":"d","text":"\"She just sits at home all day\"","trick":true},{"id":"e","text":"Unpaid care is invisible in GDP but real","trick":false}],"why":"The flagged lines dismiss real, exhausting labour; unpaid care is huge, essential work women mostly do.","relearn":"Unpaid care is real, essential work, not 'just sitting at home.'","persona":"any","source":"unpaid care (verified)"},
  {"id":"lw-994","cat":"the-gaps","type":"spot","hook":"Spot the two lines that treat leading on equality as weakness or betrayal.","scene":[{"id":"a","text":"Backing equality shows real strength","trick":false},{"id":"b","text":"\"A guy who supports this is weak\"","trick":true},{"id":"c","text":"It's everyone's job, not a side to pick","trick":false},{"id":"d","text":"\"You're betraying the boys by helping\"","trick":true},{"id":"e","text":"Standing for fairness is just maturity","trick":false}],"why":"The flagged lines paint male allyship as weakness or betrayal; leading on equality is strength and maturity.","relearn":"Leading on equality is strength, not weakness or betrayal, for boys and men.","persona":"Vijay","source":"male allyship reframe (verified)"},
  {"id":"lw-995","cat":"the-gaps","type":"spot","hook":"Spot the two lines that fake-blame women's 'choices' for the pay gap.","scene":[{"id":"a","text":"Women earn less even for the same work","trick":false},{"id":"b","text":"\"They just pick the easy, low-pay jobs\"","trick":true},{"id":"c","text":"Bias slows women's promotions","trick":false},{"id":"d","text":"\"No one's stopping them, it's all choice\"","trick":true},{"id":"e","text":"The care load limits hours for paid work","trick":false}],"why":"The flagged lines blame 'choice'; much of the pay gap is bias and the unpaid-care load.","relearn":"Much of the pay gap is bias and care load, not women's free 'choice.'","persona":"any","source":"pay gap (verified)"},
  {"id":"lw-996","cat":"the-gaps","type":"spot","hook":"Spot the two lines that spread fatalism about the gaps.","scene":[{"id":"a","text":"The gaps close when people and policy act","trick":false},{"id":"b","text":"\"One person can't change anything\"","trick":true},{"id":"c","text":"Progress so far came from real effort","trick":false},{"id":"d","text":"\"It's hopeless, just leave it alone\"","trick":true},{"id":"e","text":"Lifting one person can shift a room","trick":false}],"why":"The flagged lines preach helplessness; the gaps are fixable and one person genuinely shifts a room.","relearn":"The gaps are fixable through action; fatalism is the myth, not the truth.","persona":"any","source":"agency (myth-flip 8)"},
  {"id":"lw-997","cat":"the-gaps","type":"spot","hook":"Spot the two lines that claim the gaps are already fully closed.","scene":[{"id":"a","text":"Gaps have shrunk but clearly remain","trick":false},{"id":"b","text":"\"It's all completely equal now\"","trick":true},{"id":"c","text":"Women are still scarce in top roles","trick":false},{"id":"d","text":"\"There's nothing left to fix\"","trick":true},{"id":"e","text":"Surveys still measure a real care gap","trick":false}],"why":"The flagged lines declare equality finished; measured gaps in pay, leadership and care still remain.","relearn":"Real gaps remain; 'it's all equal now' is a comforting myth, not fact.","persona":"any","source":"realism (verified)"},
  {"id":"lw-9a0","cat":"the-gaps","type":"branch","hook":"In the group project, boys keep presenting and girls take notes. You'd...","options":[{"text":"Suggest splitting roles by skill, not gender","consequence":"The team rethinks it; a quiet girl presents well.","best":true},{"text":"Say nothing, not your problem","consequence":"The pattern repeats; the same voices go unheard."},{"text":"Loudly call the boys sexist","consequence":"People get defensive and the point is lost."}],"debrief":"Assigning roles by skill, said calmly, leads the room without shaming.","relearn":"Roles by skill and interest, not gender, is leadership by example.","persona":"any","source":"lead by example / call-in"},
  {"id":"lw-9a1","cat":"the-gaps","type":"branch","hook":"After dinner the clean-up all lands on your sister while you relax. You'd...","options":[{"text":"Get up and share the clean-up, unasked","consequence":"The norm shifts; others start pitching in too.","best":true},{"text":"Promise to help 'next time'","consequence":"Nothing changes; she carries it again tonight."},{"text":"Announce how progressive you are","consequence":"It's about your image, not sharing the load."}],"debrief":"Sharing the load visibly and unasked leads better than talking about it.","relearn":"Sharing care yourself, visibly and unasked, shifts the home norm.","persona":"any","source":"unpaid care / lead by example"},
  {"id":"lw-9a2","cat":"the-gaps","type":"branch","hook":"A capable classmate won't try for science-fair lead: 'girls don't do it.' You'd...","options":[{"text":"Encourage her and offer to back her","consequence":"She applies, leads well; others see it's possible.","best":true},{"text":"Agree it's not for her","consequence":"A talented leader is lost; the stereotype holds."},{"text":"Apply yourself so it's not 'wasted'","consequence":"She stays sidelined; the steering repeats."}],"debrief":"Backing an overlooked person toward a role they'd skip is lifting as you climb.","relearn":"Encourage capable, overlooked people toward chances they'd skip.","persona":"any","source":"lift as you climb"},
  {"id":"lw-9a3","cat":"the-gaps","type":"branch","hook":"An uncle insists 'the pay gap is a myth.' The table goes quiet. You'd...","options":[{"text":"Calmly share the facts, in good faith","consequence":"He listens; a couple of cousins nod along.","best":true},{"text":"Let it slide for peace","consequence":"The myth stands and spreads next dinner."},{"text":"Mock him publicly","consequence":"He digs in, embarrassed, and tunes out."}],"debrief":"A calm, good-faith call-in changes minds better than silence or shaming.","relearn":"A respectful call-in changes minds better than silence or public shaming.","persona":"any","source":"call in not out"},
  {"id":"lw-9a4","cat":"the-gaps","type":"branch","hook":"A woman's idea is ignored, then a man repeats it and gets praise. You'd...","options":[{"text":"Say 'that was her idea earlier'","consequence":"Credit lands where it's due; she's heard.","best":true},{"text":"Stay quiet to avoid awkwardness","consequence":"Her contribution stays invisible, as usual."},{"text":"Tell her privately, nothing aloud","consequence":"She feels seen, but the room misses who led."}],"debrief":"Crediting the person whose idea it was lifts a talked-over voice in the moment.","relearn":"Amplify: credit the person whose idea it was when it's ignored then repeated.","persona":"any","source":"lift as you climb / amplify"},
  {"id":"lw-9a5","cat":"the-gaps","type":"branch","hook":"Vijay's friends laugh at a 'women can't lead' joke and look to him. He'd...","options":[{"text":"Not laugh, lightly say 'nah, not it'","consequence":"The joke fizzles; the group's norm resets.","best":true},{"text":"Laugh along to fit in","consequence":"The put-down gets reinforced as fine."},{"text":"Furiously lecture them","consequence":"They tune out and tease him for over-reacting."}],"debrief":"Not laughing, plus a light line, sets a better norm without grandstanding.","relearn":"Not laughing at a demeaning joke quietly sets a different, better norm.","persona":"Vijay","source":"lead by example / call-in"},
  {"id":"lw-9a6","cat":"the-gaps","type":"branch","hook":"The gaps are real and you feel like one teen can't matter. You'd...","options":[{"text":"Pick one small action this week, and do it","consequence":"You lift one person; small, real, it sticks.","best":true},{"text":"Wait for a title or platform","consequence":"The 'right moment' never comes; nothing starts."},{"text":"Post a fiery story, then move on","consequence":"Feels like action, changes nothing in your room."}],"debrief":"A real plan is one small action you'll actually do, not a wait for a stage.","relearn":"A real plan is one small action this week; you don't need a title to lead.","persona":"any","source":"your leadership style / agency"},
  {"id":"lw-9a7","cat":"the-gaps","type":"branch","hook":"A friend is steered toward 'safe girl subjects' by family. She asks you. You'd...","options":[{"text":"Back her interest, help her make the case","consequence":"She raises it calmly; her family hears her.","best":true},{"text":"Tell her to just obey","consequence":"A steered-away path closes; her talent unused."},{"text":"Tell her to defy them and storm out","consequence":"It blows up; her real goal gets buried."}],"debrief":"Back her interest and help her persuade family, not confront them.","relearn":"Encourage people toward roles they were steered from, and back them respectfully.","persona":"any","source":"lift as you climb / respect family"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1438","type":"strike-rewrite","hook":"\"Allyship means speaking for people who can't speak for themselves.\"","myth":{"un":"Allyship means speaking for people who can't speak for themselves.","re":"Allyship means making space so people are heard in their own words, not speaking over them.","why":"People affected know their lives best; an ally amplifies, never replaces, their voice."},"relearn":"Allyship amplifies people's own voice; it never speaks over them.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1439","type":"strike-rewrite","hook":"\"If I'm not the one treated unfairly, it's not my place to say anything.\"","myth":{"un":"If it's not happening to me, it's not my place to say anything.","re":"You don't have to be the target to be an ally; using your standing to back others is the job.","why":"Those least at risk can often speak up most safely, so silence wastes real power to help."},"relearn":"You needn't be the target to be an ally; back others with the standing you have.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1440","type":"strike-rewrite","hook":"\"Being an ally means rescuing people who are struggling.\"","myth":{"un":"Being an ally means rescuing people who are struggling.","re":"Allyship stands with people and follows their lead; it doesn't 'rescue' them as if helpless.","why":"Treating people as helpless takes their agency; standing alongside respects it."},"relearn":"Allyship stands with people and follows their lead; it doesn't 'rescue' them.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1441","type":"strike-rewrite","hook":"\"A real ally agrees with everything and never asks questions.\"","myth":{"un":"A real ally agrees with everything and never asks questions.","re":"An ally mostly listens and learns, and is willing to be corrected without taking offence.","why":"Listening and accepting correction is how an ally keeps helping instead of just performing."},"relearn":"An ally listens, learns, and takes correction without sulking.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1442","type":"strike-rewrite","hook":"\"You're only an ally if you get it perfect every time.\"","myth":{"un":"You're only an ally if you never get anything wrong.","re":"Allyship is showing up, owning slip-ups, and trying again, not flawless performance.","why":"Fear of mistakes keeps people silent; owning a slip and continuing is what allies do."},"relearn":"Allyship is showing up and owning mistakes, not being flawless.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1443","type":"strike-rewrite","hook":"\"Allyship is a feeling; being good on the inside is enough.\"","myth":{"un":"Being a good person on the inside is enough; allyship is just a feeling.","re":"Allyship is what you actually do, listening, amplifying, showing up, not just how you feel.","why":"Private good intentions help no one until they become consistent, visible action."},"relearn":"Allyship is action over time, not a private good feeling.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1444","type":"strike-rewrite","hook":"\"Allyship is only for big public moments, not everyday ones.\"","myth":{"un":"Allyship only counts in big public moments, not small everyday ones.","re":"The everyday moments, a fair turn at the board, a name said right, are where allyship lives.","why":"Norms are built from small repeated acts far more than from rare dramatic ones."},"relearn":"Allyship lives in small everyday acts, not just big public moments.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1445","type":"strike-rewrite","hook":"\"Supporting equality means I have to put myself down.\"","myth":{"un":"Supporting equality means I have to put myself or my own kind down.","re":"Backing fairness lifts others without lowering you; respect isn't a thing you run out of.","why":"Equality widens the circle of who's respected; it never demands you respect yourself less."},"relearn":"Backing fairness lifts others without putting yourself down.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-998","type":"strike-rewrite","hook":"\"An ally has to take charge and lead the group.\"","myth":{"un":"An ally has to take charge and lead the group.","re":"Often the best ally move is to step back and hand the lead to the person who was overlooked.","why":"Stepping back to let an overlooked person lead builds them up far more than taking over."},"relearn":"Sometimes allyship means stepping back so an overlooked person can lead.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-999","type":"strike-rewrite","hook":"\"If no one thanks you, your allyship didn't count.\"","myth":{"un":"If no one thanks you for it, your allyship didn't really count.","re":"Allyship done for credit isn't allyship; the point is the person helped, not the thanks.","why":"Chasing thanks turns help into performance; the change you made stands without applause."},"relearn":"Allyship isn't for thanks; the point is the person you helped, not the credit.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1000","type":"strike-rewrite","hook":"\"Quietly correcting my own friends would be disloyal.\"","myth":{"un":"Quietly correcting my own friends would be disloyal to them.","re":"Telling a friend privately when something wasn't fair is loyalty, it helps them be better.","why":"Real friends want to be told kindly when they've slipped, not left to keep slipping."},"relearn":"Privately telling a friend something wasn't fair is loyalty, not betrayal.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1001","type":"strike-rewrite","hook":"\"Allyship is something women do for women.\"","myth":{"un":"Allyship on gender is something women do for women.","re":"Allyship is everyone's job; a boy backing a classmate's fair turn is doing exactly this work.","why":"Equality moves faster when it's shared work, not handed to the group most affected."},"relearn":"Allyship is everyone's work, not only women's.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1002","type":"strike-rewrite","hook":"\"If I share the credit, people will think I did less.\"","myth":{"un":"If I share the credit, people will think I contributed less.","re":"Naming who helped marks you as someone people trust and want to work with, not as lesser.","why":"Credit-sharing builds a reputation for fairness that opens more doors than hoarding it."},"relearn":"Sharing credit marks you as trustworthy; it doesn't make you look like you did less.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1003","type":"strike-rewrite","hook":"\"Real allies never feel awkward about speaking up.\"","myth":{"un":"If you feel awkward speaking up, you're not cut out to be an ally.","re":"Most people feel awkward the first times; allyship is doing the small thing anyway.","why":"Waiting to feel fearless means never starting; courage is acting through the awkwardness."},"relearn":"Feeling awkward is normal; allyship is the small act done anyway.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1004","type":"strike-rewrite","hook":"\"Listening isn't really doing anything.\"","myth":{"un":"Just listening isn't really doing anything to help.","re":"Listening first, really hearing what someone needs, is what makes the next action useful.","why":"Help aimed without listening often misses; listening is the work that makes help land."},"relearn":"Listening first is real work; it's what makes your help actually fit.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1005","type":"strike-rewrite","hook":"\"A good ally just fixes it without asking what's wanted.\"","myth":{"un":"A good ally just fixes the problem without asking what the person wants.","re":"Asking 'what would help?' first respects the person; uninvited 'fixing' can make it worse.","why":"People know their own situation; acting without asking can override what they actually need."},"relearn":"Ask 'what would help?' first; uninvited fixing can backfire.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1006","type":"strike-rewrite","hook":"\"You can only be an ally to people exactly like you.\"","myth":{"un":"You can only really be an ally to people who are just like you.","re":"Allyship across difference, backing someone whose life differs from yours, is the heart of it.","why":"The point of allyship is using your standing for people who don't share it, not just your own."},"relearn":"Allyship across difference is the heart of it, not a limit on it.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1007","type":"strike-rewrite","hook":"\"If I support girls' chances, boys lose out.\"","myth":{"un":"If I support girls getting equal chances, boys must lose out.","re":"Fairer chances aren't a fixed pie; widening who can take part grows opportunity for everyone.","why":"Equal access creates bigger, fairer teams and classrooms, not a loss for one group."},"relearn":"Equal chances aren't a fixed pie; widening access grows opportunity for all.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1008","type":"strike-rewrite","hook":"\"Allyship means agreeing in public and dropping it in private.\"","myth":{"un":"Allyship means agreeing in public but you can drop it in private.","re":"Real allyship is the same when no one's watching, in the group chat and the friend circle too.","why":"Norms shift only when fairness holds in private rooms, not just where it looks good."},"relearn":"Real allyship holds in private too, not only where it looks good.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1009","type":"strike-rewrite","hook":"\"It's the school's job to fix this, not mine.\"","myth":{"un":"Fixing unfairness is the institution's job, not any one person's.","re":"Rules help, but the everyday culture is set by ordinary people choosing fairness, like you.","why":"Institutions move slowly; the room you're in changes when individuals model fairness now."},"relearn":"Rules matter, but everyday fairness is set by ordinary people, including you.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1010","type":"strike-rewrite","hook":"\"Being an ally is risky, so it's safer to stay neutral.\"","myth":{"un":"Staying neutral is always the safer, smarter choice than allyship.","re":"Quiet allyship, a kind word, a fair turn, is usually low-risk; and safety routes exist if not.","why":"Most ally moves are small and safe; when a situation is unsafe you bring others in, not back off."},"relearn":"Most allyship is small and safe; when it isn't, you bring others in.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1011","type":"strike-rewrite","hook":"\"You need confidence and charisma to be an ally.\"","myth":{"un":"You need to be confident and charismatic to be an ally.","re":"Quiet, steady people make excellent allies; consistency matters far more than charisma.","why":"Allyship rewards showing up reliably, which any temperament can do, loud or quiet."},"relearn":"Quiet, steady people make excellent allies; consistency beats charisma.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1012","type":"strike-rewrite","hook":"\"If I'm an ally once, I've done my part.\"","myth":{"un":"Once you've been an ally a single time, you've done your part.","re":"Allyship is a habit you keep, not a box you tick once; the next moment still asks for you.","why":"One-off gestures fade; it's the repeated showing-up that shifts how a room treats people."},"relearn":"Allyship is an ongoing habit, not a one-time box ticked.","source":"allyship reframe"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1013","type":"reflect","hook":"Lensy: an ally's first move is usually to listen. Does that fit how you'd start?","prompt":"What do you think?","options":["Yes, listen first","I can try that","Makes sense"],"affirm":"Listening first means your help actually fits what the person needs. That's real allyship.","relearn":"Allyship usually starts with listening, not jumping in.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1014","type":"reflect","hook":"Lensy: you don't need a stage to be an ally, just the room you're in. Sit right?","prompt":"What do you think?","options":["Yes","The room I'm in","I can start there"],"affirm":"The classroom, the group chat, the home you're in, that's exactly where allyship happens.","relearn":"Allyship happens in the everyday room you're already in.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"Vijay","id":"lw-1015","type":"reflect","hook":"Lensy: a boy backing equality being read as strength, why does that matter to you?","prompt":"What do you think?","options":["It frees boys too","It brings everyone in","It's just fair"],"affirm":"When a boy leading on fairness is read as strength, half the room joins the work. That's huge.","relearn":"A boy leading on fairness is strength, and it frees boys too.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1016","type":"reflect","hook":"Lensy: think of one person who'd notice if you had their back. Picture them?","prompt":"Got someone in mind?","options":["Yes","A classmate","A friend"],"affirm":"Having one person's back, consistently, is where allyship becomes real instead of a word.","relearn":"Allyship gets real when you have one specific person's back.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1017","type":"reflect","hook":"Lensy: an ally amplifies, repeats a good point and names who said it. Could you?","prompt":"What do you think?","options":["Yes","I can name them","Worth a try"],"affirm":"Naming whose idea it was, when it gets ignored then repeated, is one of the kindest ally moves.","relearn":"Amplifying means repeating a point and crediting who said it.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1018","type":"reflect","hook":"Lensy: allyship is following the lead of the person affected, not running ahead. Feel that?","prompt":"What do you think?","options":["Yes","Follow their lead","I get it"],"affirm":"Asking 'what would help?' and following their lead keeps your help on their terms, not yours.","relearn":"Good allies follow the lead of the person affected.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1019","type":"reflect","hook":"Lensy: which feels most like you, listening, amplifying, or steadily showing up?","prompt":"Pick one.","options":["Listening","Amplifying","Showing up","All three"],"affirm":"Listening, amplifying, or showing up, any of these is an ally the room needs. They all count.","relearn":"Listening, amplifying and showing up are all real allyship.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1020","type":"reflect","hook":"Lensy: an ally can get it wrong and still be an ally if they own it. Ease the pressure?","prompt":"What do you think?","options":["Yes","A bit","Good to know"],"affirm":"You don't have to be perfect. Owning a slip and trying again is exactly what allies do.","relearn":"Allies can slip up, own it, and keep going.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"Sneha","id":"lw-1021","type":"reflect","hook":"Lensy: Sneha leads from her own values, not a borrowed style. One value you'd lead from?","prompt":"Name one to yourself.","options":["Fairness","Kindness","Honesty","Courage"],"affirm":"Leading from a value that's truly yours is what makes your allyship steady and your own.","relearn":"Authentic allyship leads from your own values.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"Arjun","id":"lw-1022","type":"reflect","hook":"Lensy: Arjun calls a friend in quietly rather than shaming them. Does that fit you?","prompt":"What do you think?","options":["Yes","Quietly, privately","I'd try that"],"affirm":"A quiet, good-faith word to a friend changes minds far better than calling them out in public.","relearn":"Calling a friend in quietly works better than shaming them.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1023","type":"reflect","hook":"Lensy: sharing credit costs you nothing and builds trust. Change how you see it?","prompt":"What do you think?","options":["Yes","Costs nothing","I'll share it"],"affirm":"Naming who helped makes people trust you and want to work with you. Credit isn't a fixed pie.","relearn":"Sharing credit builds trust; it's not a fixed pie.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1024","type":"reflect","hook":"Lensy: allyship isn't a one-time badge, it's a habit you keep choosing. Sit with that.","prompt":"What do you think?","options":["Makes sense","It's ongoing","A habit, not a badge"],"affirm":"Allyship isn't a title you earn once; it's small fair choices you keep making, day after day.","relearn":"Allyship is an ongoing habit, not a one-time badge you collect.","source":"reflect / ongoing"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1025","type":"reflect","hook":"Lensy: which would be hardest for you, speaking up, stepping back, or just listening?","prompt":"Be honest with yourself.","options":["Speaking up","Stepping back","Listening"],"affirm":"Knowing your hard part is useful, it's the muscle worth growing. Any honest answer is a good start.","relearn":"Knowing your hardest ally move is a real first step.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1026","type":"reflect","hook":"Lensy: allyship is standing with people, not above them. Does 'with, not above' land?","prompt":"What do you think?","options":["Yes","With, not above","Big difference"],"affirm":"Standing with people, led by them, is allyship. Standing above them, 'saving' them, isn't.","relearn":"Allyship stands with people, not above them.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1027","type":"reflect","hook":"Lensy: what kind of ally do you want to be known as, quietly?","prompt":"Pick what fits.","options":["Reliable","Fair","The one who listens","Still figuring it out"],"affirm":"However you'd want to be known, even still figuring it out, you're already thinking like an ally.","relearn":"Picturing the ally you want to be is itself a start.","source":"reflect / allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1028","type":"role-play","hook":"Say the line that leads.","setup":"In a group project, Meena's idea gets ignored, then Rahul says it and gets praise. You speak.","yourLine":[{"text":"\"That was Meena's idea earlier, good we're going with it.\"","best":true},{"text":"\"Cool, Rahul, nice thinking.\""},{"text":"Say nothing and move on."}],"relearn":"Crediting the person whose idea it was is a key ally move.","source":"role-play / ally voice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1029","type":"role-play","hook":"Say the line that leads.","setup":"A friend jokes the girls on the team should 'just take notes'. You want to push back kindly.","yourLine":[{"text":"\"Let's pick roles by who's good at what, not boy-girl.\"","best":true},{"text":"Laugh along so it's not awkward."},{"text":"\"Whatever, let's just start.\""}],"relearn":"Assign roles by skill, not gender, and say so.","source":"role-play / ally voice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1030","type":"role-play","hook":"Say the line that leads.","setup":"Priya keeps getting talked over in the club meeting. You notice and want to make space.","yourLine":[{"text":"\"Hang on, Priya was mid-point, let's hear her.\"","best":true},{"text":"Talk louder yourself to fix the energy."},{"text":"Hope someone else steps in."}],"relearn":"Make space and hand the floor back to who was cut off.","source":"role-play / ally voice"},
  {"cat":"what-allyship-is","persona":"Vijay","id":"lw-1031","type":"role-play","hook":"Say the line that leads.","setup":"Your friend says supporting equality is 'a girls' thing, not for guys like us'. You answer.","yourLine":[{"text":"\"Nah, fairness is everyone's job, takes guts to back it.\"","best":true},{"text":"\"Yeah, leave that stuff to them.\""},{"text":"Change the subject."}],"relearn":"Allyship is everyone's job, and backing it is strength.","source":"role-play / ally voice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1032","type":"role-play","hook":"Say the line that leads.","setup":"A classmate says she might skip the coding contest, 'it's more a boys' thing'. You encourage her.","yourLine":[{"text":"\"You're good at this, I'd back you to enter.\"","best":true},{"text":"\"Yeah, maybe it's not your scene.\""},{"text":"\"Up to you, no pressure.\""}],"relearn":"Encourage overlooked people toward chances they'd skip.","source":"role-play / ally voice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1033","type":"role-play","hook":"Say the line that leads.","setup":"In the group chat, someone forwards a demeaning 'joke' about girls. You want to set a norm.","yourLine":[{"text":"\"Not funny for me, let's drop these.\"","best":true},{"text":"React with a laughing emoji to fit in."},{"text":"Stay silent and scroll past."}],"relearn":"A calm 'not funny for me' quietly resets the norm.","source":"role-play / ally voice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1034","type":"role-play","hook":"Say the line that leads.","setup":"A teammate did most of the work but the teacher's about to credit only you. You speak up.","yourLine":[{"text":"\"Most of this was Anil's work, he should get the credit.\"","best":true},{"text":"Accept the praise quietly."},{"text":"\"It was a team effort\" and leave it vague."}],"relearn":"Name who did the work; sharing credit builds trust.","source":"role-play / ally voice"},
  {"cat":"what-allyship-is","persona":"Arjun","id":"lw-1035","type":"role-play","hook":"Say the line that leads.","setup":"Arjun's friend keeps using a slur 'as a joke'. Arjun wants to call him in, not shame him.","yourLine":[{"text":"\"Hey, just between us, that word lands badly, can we not?\"","best":true},{"text":"Call him out loudly in front of everyone."},{"text":"Let it slide to keep the peace."}],"relearn":"Call a friend in privately and in good faith.","source":"role-play / ally voice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1036","type":"branch","hook":"A girl on your team is repeatedly interrupted in the meeting. What do you do?","options":[{"text":"Say 'let's let her finish' and hand her the floor.","consequence":"She finishes; turns get fairer.","best":true},{"text":"Interrupt the interrupter to make your own point.","consequence":"It becomes a clash; her point is still lost."},{"text":"Wait and hope the teacher notices.","consequence":"No one steps in; she gives up."}],"debrief":"Make space and hand the floor back, calmly.","relearn":"Hand the floor back to who was cut off.","source":"branch / ally choice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1037","type":"branch","hook":"Your friend posts a hashtag for equality but mocks a classmate in person. What do you do?","options":[{"text":"Privately tell him the in-person part matters more.","consequence":"No audience, he starts matching words to actions.","best":true},{"text":"Reply under his post calling out the hypocrisy.","consequence":"He gets defensive and digs in."},{"text":"Decide the post is enough and say nothing.","consequence":"Words and actions stay split."}],"debrief":"Allyship is consistent action, raised privately, not a hashtag.","relearn":"Raise it privately; allyship is action, not a hashtag.","source":"branch / ally choice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1038","type":"branch","hook":"A capable classmate won't apply for the science scholarship, 'not for people like her'. What do you do?","options":[{"text":"Encourage her, offer to help with the form.","consequence":"Backed, she applies, a chance she'd have skipped.","best":true},{"text":"Tell her she's wrong and walk off.","consequence":"She feels lectured, not backed, and skips it."},{"text":"Apply yourself and leave her to decide alone.","consequence":"She reads the silence as a no."}],"debrief":"Back overlooked people toward chances, with real support.","relearn":"Mentor and back overlooked people toward chances.","source":"branch / ally choice"},
  {"cat":"what-allyship-is","persona":"Vijay","id":"lw-1039","type":"branch","hook":"At home, your sister does all the chores while you're free. What do you do?","options":[{"text":"Pick up a fair share yourself, unasked, and keep at it.","consequence":"The load evens; example beats a lecture.","best":true},{"text":"Tell your parents she should get help.","consequence":"It reads as complaining; nothing changes."},{"text":"Decide it's just how the house runs.","consequence":"The uneven load, and its message, stay."}],"debrief":"Share the load yourself, unasked; example beats telling.","relearn":"Share the load yourself, unasked.","source":"branch / ally choice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1040","type":"branch","hook":"A friend tells a demeaning joke about girls and the group laughs. What do you do?","options":[{"text":"Don't laugh, say lightly 'that one's not for me'.","consequence":"Laughter dips; a fairer norm gets set.","best":true},{"text":"Loudly shame him in front of everyone.","consequence":"He gets defensive; the group rallies to him."},{"text":"Laugh so you don't stand out.","consequence":"Your laugh is a vote; it becomes the norm."}],"debrief":"Don't laugh; a calm line resets the norm better than shaming.","relearn":"A calm line resets the norm better than shaming.","source":"branch / ally choice"},
  {"cat":"what-allyship-is","persona":"Sneha","id":"lw-1041","type":"branch","hook":"You overhear a teammate told 'leadership isn't really a girl thing'. What do you do?","options":[{"text":"Back her: 'She's already leading this, and well.'","consequence":"Her standing lifts; the put-down slides off.","best":true},{"text":"Argue statistics at the person who said it.","consequence":"It turns into a debate; she's still small."},{"text":"Say nothing to avoid the awkwardness.","consequence":"The put-down lands; she doubts herself."}],"debrief":"Back the person directly; you needn't win a debate.","relearn":"Back the person directly, no debate needed.","source":"branch / ally choice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1042","type":"branch","hook":"A senior gives the visible tasks to boys and note-taking to girls. What do you do?","options":[{"text":"Suggest assigning tasks by skill and offer to rotate.","consequence":"Roles get shared by skill; the default shifts.","best":true},{"text":"Refuse to do anything the senior assigns.","consequence":"You're seen as difficult; the split stays."},{"text":"Go along with it to avoid trouble.","consequence":"The gendered split hardens into 'normal'."}],"debrief":"Propose roles by skill and model rotating them.","relearn":"Propose roles by skill, not gender.","source":"branch / ally choice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1043","type":"branch","hook":"You want to be an ally without taking over. A quieter classmate has a strong idea. What do you do?","options":[{"text":"Repeat her idea, credit her, then step back.","consequence":"Her idea lands with her name on it.","best":true},{"text":"Present her idea as your own to push it through.","consequence":"It passes, but she's erased."},{"text":"Keep it to yourself so you don't overstep.","consequence":"A strong idea, and her chance, go unheard."}],"debrief":"Amplify and credit her, then step back.","relearn":"Amplify and credit; then step back.","source":"branch / ally choice"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1056","type":"sort","hook":"Sort: which is the ally move, which misses?","items":[{"id":"a","text":"Asks 'what would help?' first"},{"id":"b","text":"Fixes it without asking"},{"id":"c","text":"Follows the person's lead"},{"id":"d","text":"Runs ahead with their own plan"},{"id":"e","text":"Repeats and credits her point"},{"id":"f","text":"Restates her idea as his own"}],"bins":[{"id":"ally","label":"Ally move","valence":"pos"},{"id":"miss","label":"Misses","valence":"neg"}],"key":{"a":"ally","b":"miss","c":"ally","d":"miss","e":"ally","f":"miss"},"relearn":"Asking, following the lead and crediting are ally moves; fixing uninvited or taking credit miss.","source":"ally moves"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1057","type":"sort","hook":"Sort: strength, or the old myth?","items":[{"id":"a","text":"A boy backing a fair turn"},{"id":"b","text":"'Equality is only girls' job'"},{"id":"c","text":"Sharing chores unasked at home"},{"id":"d","text":"'Supporting it makes you weak'"},{"id":"e","text":"Crediting a talked-over voice"},{"id":"f","text":"'Helping others holds you back'"}],"bins":[{"id":"strength","label":"Strength","valence":"pos"},{"id":"myth","label":"Old myth","valence":"neg"}],"key":{"a":"strength","b":"myth","c":"strength","d":"myth","e":"strength","f":"myth"},"relearn":"Backing fairness, sharing load and crediting voices are strength; the put-downs are old myths.","source":"strength vs myth"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1058","type":"sort","hook":"Sort: speak up now, or step back?","items":[{"id":"a","text":"Hand the floor to who got cut off"},{"id":"b","text":"Credit whose idea it was"},{"id":"c","text":"Let the quieter person lead"},{"id":"d","text":"Say 'that joke's not for me'"},{"id":"e","text":"Stop talking so she can finish"},{"id":"f","text":"Make room and listen first"}],"bins":[{"id":"speak","label":"Speak up","valence":"tell"},{"id":"back","label":"Step back","valence":"pos"}],"key":{"a":"speak","b":"speak","c":"back","d":"speak","e":"back","f":"back"},"relearn":"Sometimes allyship means speaking up; sometimes stepping back, both are ally moves.","source":"speak vs step back"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1059","type":"sort","hook":"Sort: safe ally move, or be careful?","items":[{"id":"a","text":"A kind word backing a classmate"},{"id":"b","text":"Confronting a stranger alone"},{"id":"c","text":"Crediting someone's idea calmly"},{"id":"d","text":"Stepping into a fight by yourself"},{"id":"e","text":"Bringing in a trusted adult"},{"id":"f","text":"Cornering someone to argue it out"}],"bins":[{"id":"safe","label":"Safe move","valence":"pos"},{"id":"care","label":"Be careful","valence":"uhoh"}],"key":{"a":"safe","b":"care","c":"safe","d":"care","e":"safe","f":"care"},"relearn":"Quiet backing and bringing in others are safe; confronting alone is when to be careful, safety first.","source":"safe allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1060","type":"sort","hook":"Sort each into what kind of action it is.","items":[{"id":"a","text":"Hearing someone out fully"},{"id":"b","text":"Repeating and crediting a point"},{"id":"c","text":"Turning up again next week"},{"id":"d","text":"Asking what would actually help"},{"id":"e","text":"Naming who did the real work"},{"id":"f","text":"Sticking around when it's hard"}],"bins":[{"id":"listen","label":"Listen","valence":"neutral"},{"id":"amplify","label":"Amplify","valence":"neutral"},{"id":"showup","label":"Show up","valence":"neutral"}],"key":{"a":"listen","b":"amplify","c":"showup","d":"listen","e":"amplify","f":"showup"},"relearn":"Listening, amplifying and showing up are the three core ally actions, each one counts.","source":"ally toolkit"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1073","type":"sort","hook":"Sort: lifts the room, or holds it down?","items":[{"id":"a","text":"Sharing credit with the team"},{"id":"b","text":"Hoarding the spotlight"},{"id":"c","text":"Mentoring someone overlooked"},{"id":"d","text":"Talking over a quieter voice"},{"id":"e","text":"Backing a friend's fair turn"},{"id":"f","text":"Letting a put-down slide"}],"bins":[{"id":"lifts","label":"Lifts the room","valence":"pos"},{"id":"holds","label":"Holds it down","valence":"neg"}],"key":{"a":"lifts","b":"holds","c":"lifts","d":"holds","e":"lifts","f":"holds"},"relearn":"Sharing credit, mentoring and backing fair turns lift a room; hoarding and silence hold it down.","source":"lifts vs holds"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1061","type":"match","hook":"Match each myth to the truth that flips it.","pairs":[{"left":"'Need a title to lead'","right":"Quiet everyday leadership is real"},{"left":"'Equality is women's job'","right":"It's everyone's job"},{"left":"'Backing it is weak'","right":"It's strength and maturity"},{"left":"'Allyship is a hashtag'","right":"It's consistent action"},{"left":"'Helping others sets you back'","right":"Leadership isn't a fixed pie"}],"relearn":"Each tired myth about allyship has a truth that flips it, learn the pairs.","source":"myth flips"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1062","type":"match","hook":"Match the moment to the ally move it calls for.","pairs":[{"left":"Her idea gets ignored","right":"Credit her when it's repeated"},{"left":"She's talked over","right":"Hand the floor back to her"},{"left":"A demeaning joke lands","right":"Calmly say 'not for me'"},{"left":"She'll skip a big chance","right":"Encourage and back her"},{"left":"A friend slips up","right":"Call him in, privately"}],"relearn":"Each everyday moment has a quiet ally move that fits it.","source":"ally in the moment"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1063","type":"match","hook":"Match the word to what allyship means by it.","pairs":[{"left":"Amplify","right":"Repeat and credit a voice"},{"left":"Mentor","right":"Back someone toward a chance"},{"left":"Call in","right":"Correct a friend kindly, in private"},{"left":"Lead by example","right":"Share the load yourself, unasked"},{"left":"Stand with","right":"Follow the person's own lead"}],"relearn":"Amplify, mentor, call in, lead by example and stand with, the real meanings of allyship.","source":"ally vocabulary"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1064","type":"match","hook":"Match what a good ally does to why it works.","pairs":[{"left":"Listens first","right":"So the help actually fits"},{"left":"Shares credit","right":"Builds trust, not a smaller share"},{"left":"Calls in privately","right":"Changes minds without shaming"},{"left":"Steps back","right":"Lets the overlooked person lead"},{"left":"Shows up again","right":"Norms shift by repetition"}],"relearn":"Every ally move has a reason it works, listening, crediting, calling in, stepping back, returning.","source":"why it works"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1065","type":"match","hook":"Match the half-move to what makes it real allyship.","pairs":[{"left":"Posting once","right":"Acting again and again"},{"left":"Agreeing in public","right":"Holding it in private too"},{"left":"Feeling supportive","right":"Doing something visible"},{"left":"Saving people","right":"Standing with them, led by them"},{"left":"Taking charge","right":"Making space for them"}],"relearn":"Allyship is the fuller move: consistent, private-too, active, led by them, making space.","source":"real vs half"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1066","type":"match","hook":"Match each persona's move to the leadership it shows.","pairs":[{"left":"Vijay shares chores unasked","right":"Lead by example as strength"},{"left":"Sneha leads from her values","right":"Authentic leadership"},{"left":"Arjun calls a friend in","right":"Persuasion over shaming"},{"left":"A teammate credits an idea","right":"Amplifying a voice"},{"left":"You back an overlooked friend","right":"Lifting as you climb"}],"relearn":"Different people, the same quiet leadership: example, values, calling in, amplifying, lifting.","source":"styles of allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1067","type":"spot","hook":"Spot the 2 that are performance, not real allyship.","scene":[{"id":"a","text":"Listening to those affected","trick":false},{"id":"b","text":"Posting once for the likes","trick":true},{"id":"c","text":"Showing up week after week","trick":false},{"id":"d","text":"Claiming credit for 'caring'","trick":true},{"id":"e","text":"Amplifying a quieter voice","trick":false}],"why":"A one-off post for likes and claiming credit are performance; real allyship is steady action.","relearn":"Performative posts aren't allyship; consistent action is.","source":"active vs performative"},
  {"cat":"what-allyship-is","persona":"Vijay","id":"lw-1068","type":"spot","hook":"Spot the 2 old myths hiding in here.","scene":[{"id":"a","text":"Backing fairness takes guts","trick":false},{"id":"b","text":"'Equality is only girls' work'","trick":true},{"id":"c","text":"Boys gain from equality too","trick":false},{"id":"d","text":"'A boy backing it is weak'","trick":true},{"id":"e","text":"Allyship is everyone's job","trick":false}],"why":"'Equality is only girls' work' and 'a boy backing it is weak' are the old myths, not truths.","relearn":"Allyship is everyone's job and male allyship is strength, the myths say otherwise.","source":"myths to catch"},
  {"cat":"what-allyship-is","persona":"Arjun","id":"lw-1069","type":"spot","hook":"Spot the 2 lines that shame instead of call in.","scene":[{"id":"a","text":"'Just between us, can we not say that?'","trick":false},{"id":"b","text":"'Everyone look at what he just said!'","trick":true},{"id":"c","text":"'That didn't sit right with me.'","trick":false},{"id":"d","text":"'You're a terrible person, full stop.'","trick":true},{"id":"e","text":"'Can we keep it fair, yeah?'","trick":false}],"why":"Public shaming and writing someone off entrench them; a quiet, good-faith word changes minds.","relearn":"Call in privately and in good faith; public shaming entrenches.","source":"call in not out"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1070","type":"spot","hook":"Spot the 2 moves that erase the person you mean to help.","scene":[{"id":"a","text":"Repeating her idea, with her name","trick":false},{"id":"b","text":"Presenting her idea as your own","trick":true},{"id":"c","text":"Asking what she'd want first","trick":false},{"id":"d","text":"Deciding for her without asking","trick":true},{"id":"e","text":"Following her lead on it","trick":false}],"why":"Taking her idea and deciding for her erase her; allyship credits her and follows her lead.","relearn":"Allyship credits people and follows their lead, it never erases them.","source":"don't erase"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1071","type":"spot","hook":"Spot the 2 that ignore safety, when to be careful.","scene":[{"id":"a","text":"Bringing in a trusted adult","trick":false},{"id":"b","text":"Confronting a stranger alone","trick":true},{"id":"c","text":"A calm word backing a friend","trick":false},{"id":"d","text":"Wading into a fight by yourself","trick":true},{"id":"e","text":"Calling 181, 112 or 1098 if unsafe","trick":false}],"why":"Most allyship is small and safe; confronting alone is the risky move, bring others in, safety first.","relearn":"Safety first: when it's unsafe, bring others in, not confront alone.","source":"safety-aware allyship"},
  {"cat":"what-allyship-is","persona":"any","id":"lw-1072","type":"spot","hook":"Spot the 2 that are display, not the real thing.","scene":[{"id":"a","text":"Agreeing in public, dropping it in private","trick":true},{"id":"b","text":"Holding fairness even in the group chat","trick":false},{"id":"c","text":"One hashtag, then nothing","trick":true},{"id":"d","text":"Backing a classmate again next week","trick":false},{"id":"e","text":"Naming who really did the work","trick":false}],"why":"Agreeing only in public and a one-off hashtag are display; real allyship holds in private and repeats.","relearn":"Real allyship is consistent and holds in private, not just for show.","source":"display vs real"},
  {"id":"lw-1350","type":"reflect","hook":"Lensy: when you picture leading, which feels most like you?","prompt":"Pick one.","options":["Steady in the background","Out front, speaking","One-to-one with a friend","Building the team"],"affirm":"Every one of those is a real way to lead: yours counts, whatever it looks like.","relearn":"Leadership has many shapes; the one that fits you is real and valuable.","source":"authentic style","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1351","type":"reflect","hook":"Lensy: a leader you admire, what is it about how they lead?","prompt":"What pulls you?","options":["They listen first","They stay calm","They lift others","They keep promises"],"affirm":"What you admire is a clue to the leader you already are becoming.","relearn":"The traits you admire in others point to your own emerging style.","source":"role-model reflection","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1352","type":"reflect","hook":"Lensy: would you rather lead by what you say or by what you do?","prompt":"Lean one way.","options":["By doing","By saying","A bit of both","Depends on the room"],"affirm":"Both move people: leading from how you actually act is yours to choose.","relearn":"You can lead by example, by voice, or both; the mix is yours to set.","source":"say vs do","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1353","type":"reflect","hook":"Lensy: one small thing you could lead on this week, at home?","prompt":"Picture it.","options":["Share a chore unasked","Cook one meal","Speak kindly in a tense moment","Back a sibling's choice"],"affirm":"Naming one small home action is how a real leadership plan starts.","relearn":"A real plan is one small, specific action you'll actually do this week.","source":"plan · home action","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1354","type":"reflect","hook":"Lensy: who's one person you could lift this month?","prompt":"Bring them to mind.","options":["A shy classmate","A talked-over friend","A younger sibling","A quiet teammate"],"affirm":"Leadership is measured by who rises with you: picking one person is a real start.","relearn":"Real leadership is measured by who rises with you; start with one person.","source":"lift one person","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1355","type":"reflect","hook":"Lensy: when you lead, what value do you most want to stand for?","prompt":"Pick your anchor.","options":["Fairness","Honesty","Kindness","Courage"],"affirm":"Leading from your own value is what makes it last: this anchor is yours.","relearn":"Lead from your own values, not a borrowed style; that's what makes it sustainable.","source":"values anchor","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1356","type":"reflect","hook":"Lensy: a leader doesn't have to have every answer. How does that sit?","prompt":"What do you feel?","options":["A relief","Makes sense","I can do that","Still learning"],"affirm":"You can lead while still learning: not knowing everything never disqualifies you.","relearn":"You can lead while still learning; you needn't have every answer.","source":"permission to learn","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1357","type":"reflect","hook":"Lensy: which feels harder for you, speaking up or lifting others up?","prompt":"Be honest.","options":["Speaking up","Lifting others","Both, sometimes","Neither, lately"],"affirm":"Knowing your harder edge is exactly where your growth as a leader begins.","relearn":"Knowing which part is harder for you shows where to grow next.","source":"self-knowledge","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1358","type":"reflect","hook":"Lensy: a quiet leader can change a room as much as a loud one. Agree?","prompt":"What do you think?","options":["Yes","Often, yes","Quiet works too","Both can"],"affirm":"Quiet, steady example shifts norms: no megaphone required for real leadership.","relearn":"Quiet everyday leadership shifts a room as much as a loud one.","source":"quiet leadership","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1359","type":"reflect","hook":"Lensy, to a boy: leading on fairness is strength, not picking a side. How's that land?","prompt":"What do you feel?","options":["It's strength","Makes sense","I'm in","Still thinking"],"affirm":"A boy leading on equality is strength and maturity, and it frees you too.","relearn":"A boy leading on equality is strength, not betrayal or weakness.","persona":"Vijay","source":"male allyship as strength","cat":"your-leadership-style"},
  {"id":"lw-1360","type":"reflect","hook":"Lensy: you can lead in a way that respects your family, not against them. Reassuring?","prompt":"What do you think?","options":["Yes","With respect","That fits me","Good to know"],"affirm":"Quiet example and a kind word let you lead while honouring the people you love.","relearn":"You can lead for fairness in ways that respect family and community.","source":"India · respectful leadership","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1361","type":"reflect","hook":"Lensy: which 'first step' feels most doable for you tomorrow?","prompt":"Pick one.","options":["Credit someone's idea","Share a task fairly","Invite a quiet voice in","Skip a mean joke"],"affirm":"Any of these, done once, is a real leadership step: pick the one that's yours.","relearn":"A first step is one concrete action you'll do, not a grand vow.","source":"plan · first step","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1362","type":"reflect","hook":"Lensy: copying a 'leader type' you saw online vs leading as yourself, which lasts?","prompt":"Your take.","options":["As myself","Being real lasts","My own way","A bit of both"],"affirm":"Leading as yourself is what you can keep up: borrowed styles wear off fast.","relearn":"Your own style outlasts a copied one; authenticity is sustainable.","source":"authentic vs copied","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1363","type":"reflect","hook":"Lensy: a leader's job is to lift the room, not look the biggest. Sit right?","prompt":"What do you think?","options":["Yes","The room matters","Not about ego","Mostly yes"],"affirm":"Leading to lift the room, not your image, is the kind that actually changes things.","relearn":"Leading lifts the room; it isn't about looking the biggest.","source":"room over ego","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1364","type":"reflect","hook":"Lensy: where in your life do you already have a little influence?","prompt":"Name one.","options":["My friend group","My home","My class/team","My online space"],"affirm":"Start leading where you already have a voice: that's where change really begins.","relearn":"Lead first where you already have influence; that's where change starts.","source":"where to lead","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1365","type":"reflect","hook":"Lensy: is 'one person can't change anything' true, or a myth to flip?","prompt":"Your call.","options":["A myth","One person can","I can start","Worth flipping"],"affirm":"One person leading by example and lifting one other really does shift a room.","relearn":"'One person can't change anything' is the myth; one person shifts a room.","source":"agency","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1366","type":"reflect","hook":"Lensy: which would you rather be known for in ten years?","prompt":"Pick one.","options":["Fair to everyone","Lifted others up","Stayed honest","Made people braver"],"affirm":"That's a leadership legacy worth building, and it starts with this week.","relearn":"The leader you want to be known as is built by small actions, starting now.","source":"legacy reflection","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1367","type":"reflect","hook":"Lensy: leading can feel scary. Does that mean you're not ready?","prompt":"What do you think?","options":["No, that's normal","Scared and ready","I can still lead","Everyone feels it"],"affirm":"Feeling nervous and leading anyway is courage: fear never means 'not yet'.","relearn":"Nervousness doesn't mean you're not ready; leading scared is courage.","source":"fear ≠ unready","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1368","type":"reflect","hook":"Lensy: your style can change as you grow. Freeing or unsettling?","prompt":"Which is truer?","options":["Freeing","Makes sense","I can evolve","A bit of both"],"affirm":"Your way of leading can grow with you: you're not locked into one shape.","relearn":"Your leadership style can evolve as you grow; it isn't fixed.","source":"style evolves","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1369","type":"reflect","hook":"Lensy: India has its own changemakers across science, sport and reform. Inspiring?","prompt":"What do you think?","options":["Yes","Our own heroes","Inspiring","I can join them"],"affirm":"You stand in a long line of Indian changemakers: there's room for you in it.","relearn":"India has its own role models of leadership for fairness to draw on.","source":"India role models","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1370","type":"reflect","hook":"Lensy: would you rather lead a big crowd or change one small room well?","prompt":"Lean one way.","options":["One room, well","A big crowd","Start small","Wherever I'm needed"],"affirm":"Changing the room you're in is real leadership: scale is not the measure.","relearn":"Changing your own room well is real leadership; scale isn't the measure.","source":"scale of leading","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1371","type":"reflect","hook":"Lensy, Sneha: your voice and leadership reach well beyond 'a man's role'. How's that feel?","prompt":"What do you feel?","options":["True","About time","I'll lead","Watch me"],"affirm":"Your leadership isn't limited by anyone's idea of 'a girl's place': lead fully.","relearn":"Your leadership isn't bound by anyone's idea of 'a man's role'.","persona":"Sneha","source":"voice beyond a role","cat":"your-leadership-style"},
  {"id":"lw-1372","type":"reflect","hook":"Lensy: which mistake would you forgive in a leader more easily?","prompt":"Pick one.","options":["Trying and stumbling","Asking for help","Admitting they were wrong","Changing their mind"],"affirm":"The 'mistakes' you'd forgive are signs of an honest leader, including in yourself.","relearn":"Honest stumbles and changed minds are part of real leadership, not failure.","source":"forgiving a leader","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1373","type":"reflect","hook":"Lensy: after this game, what's one belief about leading that shifted for you?","prompt":"Pick one.","options":["No title needed","Allyship is for all","Lifting helps me too","I can start small"],"affirm":"Whatever shifted, you can carry it into one real action: that's the whole point.","relearn":"Carry a shifted belief into one real action; that's how a game becomes change.","source":"consolidation","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1374","type":"reflect","hook":"Lensy: would you rather your team trust you or fear you?","prompt":"Easy one, but pick.","options":["Trust me","Trust, clearly","Respect me","Trust wins"],"affirm":"Trust-based leading goes further than fear ever can: that instinct serves you well.","relearn":"Trust-based leadership lasts; fear-based control never builds a real team.","source":"trust over fear","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1375","type":"reflect","hook":"Lensy: a friend asks you to lead something and you doubt yourself. What helps most?","prompt":"Pick one.","options":["Start very small","Ask someone along","Remember why it matters","Just try once"],"affirm":"Any of those gets you moving: self-doubt is normal and never the final word.","relearn":"Self-doubt is normal; a small start or a buddy can carry you past it.","source":"past self-doubt","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1376","type":"reflect","hook":"Lensy: which kind of 'win' would feel best to you as a leader?","prompt":"Pick one.","options":["Someone you backed succeeds","A fairer room","Nobody left out","A teammate grew"],"affirm":"Every 'win' you'd pick is about lifting others: that's leadership at its best.","relearn":"The leader's real win is a person or a room lifted, not personal credit.","source":"defining the win","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1377","type":"reflect","hook":"Lensy: does your conduct when nobody's watching matter to leading?","prompt":"What do you think?","options":["Yes, a lot","That's integrity","It all counts","Mostly yes"],"affirm":"Integrity, acting on your values with no audience, is the quiet core of leading.","relearn":"Integrity means your conduct matches your values even with no audience.","source":"integrity","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1378","type":"reflect","hook":"Lensy: would you rather get credit, or share it?","prompt":"Lean one way.","options":["Share it","Share, mostly","Credit the team","Depends"],"affirm":"Sharing credit builds trust and teams, and your instinct here is a leader's.","relearn":"Sharing credit builds trust and teams; leadership isn't a fixed pie.","source":"share credit","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1379","type":"reflect","hook":"Lensy: pick a one-line motto to carry out of this game.","prompt":"Choose your line.","options":["Lift as you climb","Call in, not out","No title needed","Allyship is everyone's job"],"affirm":"Lived out, any of those makes you the quiet, steady leader this world needs.","relearn":"A short motto, actually lived, keeps your leadership pointed the right way.","source":"motto","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1380","type":"reflect","hook":"Lensy: a generation of quiet leaders and active allies, want in?","prompt":"What do you think?","options":["Count me in","Yes","Let's lead","I'm starting"],"affirm":"Every quiet leader and active ally helps build a fairer world, starting with you.","relearn":"Quiet leaders and active allies build a fairer world, starting with you.","source":"vision","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1381","type":"reflect","hook":"Lensy, Arjun: leading with integrity at home and school is yours to do, your way. Sit right?","prompt":"What do you feel?","options":["Yes","My way","I lead too","That's me"],"affirm":"You lead by living your values steadily, at home and at school, on your terms.","relearn":"You lead by living your values steadily, at home and at school, your way.","persona":"Arjun","source":"integrity · own way","cat":"your-leadership-style"},
  {"id":"lw-1382","type":"branch","hook":"You want to start leading on fairness but it feels huge.","options":[{"text":"Pick one small action you'll do this week","consequence":"Intention turns into a real, doable start.","outcome":"plan","best":true},{"text":"Wait until you can do something big","consequence":"One small, specific action beats waiting for a 'big' moment."}],"debrief":"A concrete small step is how leadership actually begins.","relearn":"A real plan is one small, specific action you'll do this week.","source":"plan · small start","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1383","type":"branch","hook":"Your study group keeps making the same girl take all the notes.","options":[{"text":"Propose rotating roles by who's keen, not by gender","consequence":"You model fair roles and shift the group's habit.","outcome":"model","best":true},{"text":"Say nothing; it's not your business","consequence":"Modelling fair roles quietly resets the norm for everyone."}],"debrief":"Assigning roles by skill and interest, and modelling it, is real leadership.","relearn":"Lead by assigning roles by skill and interest, not by gender.","source":"lead by example · roles","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1384","type":"branch","hook":"A capable friend won't apply for the class-rep role: 'that's not for me'.","options":[{"text":"Encourage her and offer to back her up","consequence":"You lift an overlooked person toward a real chance.","outcome":"lift","best":true},{"text":"Apply yourself instead and move on","consequence":"Mentoring an overlooked friend toward a chance is leadership's heart."}],"debrief":"Encouraging capable, overlooked people is exactly what lifting others means.","relearn":"Mentor and back capable-but-overlooked people toward chances they'd skip.","source":"lift · mentor","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1385","type":"branch","hook":"In a meeting, your idea lands only after a boy repeats it as his own.","options":[{"text":"Calmly name it: 'Glad it caught on. That was Meera's point earlier'","consequence":"You credit the real source and reset the room.","outcome":"amplify","best":true},{"text":"Let it slide to avoid awkwardness","consequence":"Crediting the original voice is leadership; staying silent erases it."}],"debrief":"Amplifying, crediting whose idea it really was, is core to lifting others.","relearn":"Amplify: credit the person whose idea it was when it's ignored then repeated.","source":"lift · amplify","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1386","type":"branch","hook":"You're choosing where to put your leadership energy this term.","options":[{"text":"Start in your own friend group and class","consequence":"You lead where your voice already carries.","outcome":"realistic","best":true},{"text":"Wait for a school-wide stage","consequence":"Lead first where you already have influence; that's where change starts."}],"debrief":"Your everyday circles are where your leadership is most real.","relearn":"Lead where you already have influence: home, group, class.","source":"where to lead","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1387","type":"branch","hook":"A boy in your group jokes that 'leading is a girl's hobby now'.","options":[{"text":"Take it on as a boy: 'Fairness is everyone's job. I'm in'","consequence":"You show male allyship as strength and bring boys in.","outcome":"strength","best":true},{"text":"Laugh along so it blows over","consequence":"A boy claiming the work as his is strength, and exactly what moves it."}],"debrief":"Boys leading on equality is one of the most powerful moves this game asks for.","relearn":"Leading on equality as a boy is strength, and it's needed.","persona":"Vijay","source":"male allyship","cat":"your-leadership-style"},
  {"id":"lw-1388","type":"branch","hook":"At home you notice your sister does all the cleanup after dinner.","options":[{"text":"Quietly start sharing it, unasked, every night","consequence":"Your visible example shifts the home norm without a lecture.","outcome":"example","best":true},{"text":"Announce that chores 'should' be shared, then forget","consequence":"Sharing the load visibly and unasked leads better than telling."}],"debrief":"Sharing the unequal load yourself, visibly and unasked, leads by example.","relearn":"Share the unequal load yourself, visibly and unasked; example beats telling.","source":"lead by example · home","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1389","type":"branch","hook":"A friend keeps making a demeaning joke. You want it to stop, kindly.","options":[{"text":"Privately: 'That one didn't sit right with me. Can we drop it?'","consequence":"A good-faith call-in changes his mind without a public fight.","outcome":"call-in","best":true},{"text":"Mock him about it in the group chat","consequence":"A private call-in changes minds; public shaming just entrenches."}],"debrief":"A respectful, private call-in changes minds better than a shaming call-out.","relearn":"A respectful, private call-in changes minds better than public shaming.","source":"call-in","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1390","type":"branch","hook":"You finish the game and want it to actually change something.","options":[{"text":"Commit to one action and one person you'll lift","consequence":"Your learning becomes a real difference this week.","outcome":"commit","best":true},{"text":"File it away as 'nice to know'","consequence":"One action and one person lifted turns learning into change."}],"debrief":"A concrete commitment is what turns a game into real leadership.","relearn":"Commit to one action and one person to lift; make it real.","source":"commitment","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1391","type":"branch","hook":"A teammate gets an idea wrong publicly; you want to lead, not embarrass them.","options":[{"text":"Add to it gently and credit what they got right","consequence":"You correct course while keeping their dignity intact.","outcome":"call-in","best":true},{"text":"Point out the mistake in front of everyone","consequence":"Building on people, not shaming them, is how leaders keep a team."}],"debrief":"Leading keeps people's dignity: build on them rather than expose them.","relearn":"Lead by building on people and keeping their dignity, not exposing them.","source":"dignity","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1392","type":"branch","hook":"You're nervous to lead anything because you might get it wrong.","options":[{"text":"Try one small thing and treat slip-ups as learning","consequence":"You start, and mistakes become part of growing.","outcome":"start","best":true},{"text":"Wait until you're sure you won't fail","consequence":"Leaders start before they feel perfect; mistakes are how you learn."}],"debrief":"You don't need to be flawless to lead: starting and learning is the way.","relearn":"You needn't be flawless to lead; start small and learn as you go.","source":"start imperfect","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1393","type":"branch","hook":"Your idea for a fairer rota could work, but you can't run it alone.","options":[{"text":"Invite one person to lead it with you","consequence":"Two leaders make it easier, better and more likely to stick.","outcome":"collective","best":true},{"text":"Try to push it through solo","consequence":"Inviting others to lead with you multiplies the effect."}],"debrief":"Inviting others in turns your idea into shared, lasting leadership.","relearn":"Inviting others to lead with you multiplies the effect.","source":"collective","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1394","type":"branch","hook":"A junior keeps getting talked over in your club; you have a little standing.","options":[{"text":"Use it to make space: 'Let's hear Ravi finish'","consequence":"You spend your standing to lift a quieter voice.","outcome":"amplify","best":true},{"text":"Keep your standing for yourself","consequence":"Spending your standing to make space is leadership, not a loss."}],"debrief":"Using your standing to make space for others is the heart of lifting.","relearn":"Spend your standing to make space for quieter voices; that's lifting.","source":"lift · make space","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1395","type":"branch","hook":"Praise comes your way for a project two friends actually carried.","options":[{"text":"Redirect it: 'Honestly, Aisha and Dev did the heavy lifting'","consequence":"You share credit and build their reputations.","outcome":"credit","best":true},{"text":"Accept it quietly; they'll understand","consequence":"Sharing credit builds trust and teams; hoarding it costs you both."}],"debrief":"Sharing credit lifts the people who earned it, and marks you as a leader.","relearn":"Share credit with the people who earned it; it builds trust and teams.","source":"share credit","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1396","type":"branch","hook":"You want to lead but worry your family will see it as 'showing off'.","options":[{"text":"Lead quietly by example and kind words, no grandstanding","consequence":"You lead in a way your family can respect, not resent.","outcome":"respect","best":true},{"text":"Drop the whole idea of leading","consequence":"Quiet example lets you lead while respecting family and community."}],"debrief":"Leading by example and call-in respects family while still shifting the norm.","relearn":"Lead by quiet example; it respects family and still shifts the norm.","persona":"any","source":"India · respectful","cat":"your-leadership-style"},
  {"id":"lw-1397","type":"branch","hook":"You see a heated, unsafe row brewing where someone could get hurt.","options":[{"text":"Don't confront alone: bring in a trusted adult or call 112","consequence":"You lead by keeping everyone, including you, safe.","outcome":"safety","best":true},{"text":"Step into the middle of it solo to 'lead'","consequence":"When it's unsafe, the leading move is to bring others in, not go alone."}],"debrief":"Real leadership puts safety first: when it's unsafe, bring others in.","relearn":"When it's unsafe, bring in a trusted adult or 112, never confront alone.","source":"safety first","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1398","type":"branch","hook":"Your plan to lead fizzled last month. You're tempted to give up.","options":[{"text":"Shrink it to one tiny action and try again","consequence":"A smaller, doable step restarts your momentum.","outcome":"restart","best":true},{"text":"Decide leading 'isn't for you'","consequence":"A smaller step restarts you; one stumble doesn't end your leading."}],"debrief":"One stumble isn't the end: shrink the step and begin again.","relearn":"One stumble isn't the end; shrink the step and begin again.","source":"restart","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1399","type":"branch","hook":"You're picking a 'leadership style' to copy from someone famous.","options":[{"text":"Build your own from your real values instead","consequence":"A style that's truly yours is one you can actually keep up.","outcome":"authentic","best":true},{"text":"Imitate their every move to seem like a leader","consequence":"Borrowed styles wear off; leading from your own values lasts."}],"debrief":"Leading from your own values is what makes your style sustainable.","relearn":"Build your style from your own values, not a copied one.","source":"authentic style","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1400","type":"role-play","hook":"You're rallying a friend to lead a fairer group project with you.","setup":"Invite them in. Say:","yourLine":[{"text":"\"Let's set the tone together: it's easier and better with two of us.\"","best":true},{"text":"\"I'll just handle the whole thing myself.\""}],"relearn":"Inviting others to lead with you multiplies the effect.","source":"collective","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1401","type":"role-play","hook":"A classmate's good idea just got ignored, then repeated by someone else.","setup":"Amplify her. Say:","yourLine":[{"text":"\"Quick one: that was Priya's idea a minute ago. Priya, want to add to it?\"","best":true},{"text":"\"Anyway, moving on.\""}],"relearn":"Amplify by crediting whose idea it really was when it's repeated.","source":"lift · amplify","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1402","type":"role-play","hook":"You're encouraging a capable friend to go for a role she keeps ducking.","setup":"Back her. Say:","yourLine":[{"text":"\"You'd be great at this: go for it, and I've got your back.\"","best":true},{"text":"\"Eh, maybe it's not your thing.\""}],"relearn":"Encourage and back capable people toward chances they'd otherwise skip.","source":"lift · mentor","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1403","type":"role-play","hook":"A friend keeps cracking a demeaning joke. You want to call him in, kindly.","setup":"Privately, say:","yourLine":[{"text":"\"Hey, that one didn't sit right with me. Can we not?\"","best":true},{"text":"\"You're disgusting, everyone should hear this.\""}],"relearn":"A private, good-faith call-in changes minds better than public shaming.","source":"call-in","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1404","type":"role-play","hook":"You're a boy and a mate teases you for 'taking the girls' side'.","setup":"Own it. Say:","yourLine":[{"text":"\"There aren't sides in fairness, and standing for it is the strong move.\"","best":true},{"text":"\"Fine, forget I said anything.\""}],"relearn":"A boy leading on equality is strength; there are no 'sides' in fairness.","persona":"Vijay","source":"male allyship","cat":"your-leadership-style"},
  {"id":"lw-1405","type":"role-play","hook":"Praise lands on you for work your teammate mostly did.","setup":"Share the credit. Say:","yourLine":[{"text":"\"Thanks, but honestly Sana drove most of this, she deserves the credit.\"","best":true},{"text":"\"Yeah, it was pretty much all me.\""}],"relearn":"Share credit with whoever earned it; it builds trust and teams.","source":"share credit","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1406","type":"role-play","hook":"A quieter friend is doubting whether she can lead anything at all.","setup":"Encourage her, your way. Say:","yourLine":[{"text":"\"You already lead: calm and fair. Pick one small thing and I'll help.\"","best":true},{"text":"\"Yeah, leading's probably not for everyone.\""}],"relearn":"Anyone can lead in their own style; a small first step makes it real.","persona":"Sneha","source":"encourage to lead","cat":"your-leadership-style"},
  {"id":"lw-1407","type":"sort","hook":"Sort: a real first step, or just a vague vow?","items":[{"id":"a","text":"Share dinner cleanup tonight, unasked"},{"id":"b","text":"\"I'll be a better person somehow\""},{"id":"c","text":"Credit one talked-over voice this week"},{"id":"d","text":"\"I'll change everything one day\""},{"id":"e","text":"Encourage one friend to apply by Friday"},{"id":"f","text":"\"I really should lead more\""}],"bins":[{"id":"step","label":"Real step","valence":"pos"},{"id":"vow","label":"Vague vow","valence":"uhoh"}],"key":{"a":"step","b":"vow","c":"step","d":"vow","e":"step","f":"vow"},"relearn":"A real plan is one small, specific action; a vague vow is not a plan.","source":"plan vs vow","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1408","type":"sort","hook":"Sort: that's leading well, or that's grandstanding?","items":[{"id":"a","text":"Quietly modelling fair roles"},{"id":"b","text":"Lecturing loudly for applause"},{"id":"c","text":"Crediting someone else's idea"},{"id":"d","text":"Dunking on a rival in public"},{"id":"e","text":"Sharing a chore unasked"},{"id":"f","text":"Leading only when filmed"}],"bins":[{"id":"lead","label":"Leading well","valence":"pos"},{"id":"grand","label":"Grandstanding","valence":"neg"}],"key":{"a":"lead","b":"grand","c":"lead","d":"grand","e":"lead","f":"grand"},"relearn":"Leading is steady and quiet; grandstanding is for the credit, not the room.","source":"lead vs grandstand","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1408b","type":"sort","hook":"Sort: a true belief about leading, or a myth to flip?","items":[{"id":"a","text":"Quiet everyday leadership is real"},{"id":"b","text":"\"You need a title to lead\""},{"id":"c","text":"Allyship is everyone's job"},{"id":"d","text":"\"Equality is only women's job\""},{"id":"e","text":"Lifting others builds your team"},{"id":"f","text":"\"Helping others means you fall behind\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"No title needed, allyship is for all, lifting builds teams; the rest are myths.","source":"myth-flip","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1409","type":"sort","hook":"Sort: which leadership style is each line?","items":[{"id":"a","text":"\"Watch what I do, not what I say\""},{"id":"b","text":"\"Let me boost your idea\""},{"id":"c","text":"\"I'll say the hard thing kindly\""},{"id":"d","text":"\"Let's all sync our plan\""},{"id":"e","text":"\"I'll quietly share the load\""},{"id":"f","text":"\"You'd be great: go for it\""}],"bins":[{"id":"example","label":"By example","valence":"neutral"},{"id":"lift","label":"By lifting","valence":"neutral"}],"key":{"a":"example","b":"lift","c":"example","d":"lift","e":"example","f":"lift"},"relearn":"Leading by example and leading by lifting others are both real styles.","source":"styles","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1410","type":"sort","hook":"Sort: call-in, or call-out?","items":[{"id":"a","text":"\"That didn't sit right: can we not?\" (privately)"},{"id":"b","text":"Screenshotting it to shame him online"},{"id":"c","text":"A quiet word, assuming good faith"},{"id":"d","text":"Mocking him in the group chat"},{"id":"e","text":"\"Let's talk, just us\""},{"id":"f","text":"Dragging him in front of the class"}],"bins":[{"id":"in","label":"Call-in","valence":"pos"},{"id":"out","label":"Call-out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"A private, good-faith call-in changes minds; public call-outs just shame.","source":"call-in vs out","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1411","type":"sort","hook":"Sort: leads safely, or pushes into danger?","items":[{"id":"a","text":"Brings in a trusted adult when it's unsafe"},{"id":"b","text":"Jumps into a violent row alone"},{"id":"c","text":"Calls 112 when someone's at risk"},{"id":"d","text":"Eggs the fight on to look brave"},{"id":"e","text":"Gets friends to step in together"},{"id":"f","text":"Confronts a dangerous person solo"}],"bins":[{"id":"safe","label":"Leads safely","valence":"pos"},{"id":"danger","label":"Into danger","valence":"neg"}],"key":{"a":"safe","b":"danger","c":"safe","d":"danger","e":"safe","f":"danger"},"relearn":"Safe leading brings others in; charging into danger alone isn't leadership.","source":"safety first","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1412","type":"sort","hook":"Sort: builds your team, or only your image?","items":[{"id":"a","text":"Sharing credit with the team"},{"id":"b","text":"Taking credit for others' work"},{"id":"c","text":"Mentoring someone newer"},{"id":"d","text":"Hoarding every good task"},{"id":"e","text":"Backing a rival's good idea"},{"id":"f","text":"Sidelining anyone who might shine"}],"bins":[{"id":"team","label":"Builds the team","valence":"pos"},{"id":"image","label":"Only your image","valence":"neg"}],"key":{"a":"team","b":"image","c":"team","d":"image","e":"team","f":"image"},"relearn":"Sharing credit and mentoring builds teams; hoarding only props up your image.","source":"team vs image","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1413","type":"sort","hook":"Sort: an authentic style, or a borrowed pose?","items":[{"id":"a","text":"Leading from your own values"},{"id":"b","text":"Copying an influencer's act"},{"id":"c","text":"Your natural calm under pressure"},{"id":"d","text":"Faking a 'boss' voice for show"},{"id":"e","text":"The way you really treat people"},{"id":"f","text":"Performing a style that isn't you"}],"bins":[{"id":"real","label":"Authentic","valence":"pos"},{"id":"pose","label":"Borrowed pose","valence":"uhoh"}],"key":{"a":"real","b":"pose","c":"real","d":"pose","e":"real","f":"pose"},"relearn":"Leading from your values is authentic; a copied pose won't last.","source":"authentic vs pose","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1414","type":"match","hook":"Match the leadership style to what it looks like.","pairs":[{"left":"By example","right":"Show it before you say it"},{"left":"By lifting","right":"Boost an overlooked person"},{"left":"By calling in","right":"A kind private word"},{"left":"By connecting","right":"Bring the right people together"},{"left":"By speaking up","right":"Name the unfair thing"}],"relearn":"Example, lifting, calling-in, connecting and speaking up are all real styles.","source":"styles","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1415","type":"match","hook":"Match each first action to the value it lives out.","pairs":[{"left":"Share a chore unasked","right":"Fairness at home"},{"left":"Credit a quiet voice","right":"Respect for others"},{"left":"Admit you were wrong","right":"Honesty"},{"left":"Lead while nervous","right":"Courage"},{"left":"Back a rival's idea","right":"Generosity"}],"relearn":"Each small action lives out a value: fairness, respect, honesty, courage, generosity.","source":"action ↔ value","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1416","type":"match","hook":"Match the myth to the truth that flips it.","pairs":[{"left":"\"Need a title to lead\"","right":"Quiet everyday leadership is real"},{"left":"\"Equality is women's job\"","right":"It's everyone's job"},{"left":"\"Helping others sets you back\"","right":"Lifting builds your team"},{"left":"\"Shaming changes people\"","right":"A good-faith call-in works better"},{"left":"\"One person can't matter\"","right":"One person shifts the room"}],"relearn":"Each leadership myth has a truth that flips it; agency and allyship are real.","source":"myth-flip","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1417","type":"match","hook":"Match the leader move to what it achieves.","pairs":[{"left":"Amplify an idea","right":"Credit goes to its real source"},{"left":"Mentor a beginner","right":"They reach for a bigger chance"},{"left":"Share credit","right":"The whole team is trusted more"},{"left":"Make space","right":"A quiet voice gets heard"},{"left":"Set the example","right":"The room's norm quietly shifts"}],"relearn":"Amplifying, mentoring, sharing credit, making space and example each lift a room.","source":"move ↔ effect","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1418","type":"match","hook":"Match the situation to the leader's best first move.","pairs":[{"left":"Idea ignored then copied","right":"Credit who said it first"},{"left":"Demeaning joke from a mate","right":"Quiet, private call-in"},{"left":"Unsafe row brewing","right":"Bring in a trusted adult"},{"left":"Friend ducking a role","right":"Encourage and back them"},{"left":"Roles split by gender","right":"Reassign by skill and interest"}],"relearn":"Each situation has a steady first move: credit, call-in, get help, encourage, reassign.","source":"situation ↔ move","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1419","type":"match","hook":"Match the trait to how a good leader shows it.","pairs":[{"left":"Integrity","right":"Same when no one's watching"},{"left":"Humility","right":"Shares the credit around"},{"left":"Courage","right":"Says the hard thing kindly"},{"left":"Steadiness","right":"Leads without grandstanding"},{"left":"Care","right":"Notices who's left out"}],"relearn":"Integrity, humility, courage, steadiness and care each show in everyday acts.","source":"trait ↔ act","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1420","type":"match","hook":"Match each leader to what India remembers them for.","pairs":[{"left":"Savitribai Phule","right":"Opened schooling for girls"},{"left":"Kalpana Chawla","right":"First Indian-origin woman in space"},{"left":"Mary Kom","right":"Boxing champion against the odds"},{"left":"B. R. Ambedkar","right":"Drafted a constitution of equality"},{"left":"P. T. Usha","right":"Trailblazing track athlete"}],"relearn":"India's own changemakers led for fairness across schooling, science and sport.","source":"India role models","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1421","type":"match","hook":"Match the weak move to the stronger leader move beside it.","pairs":[{"left":"Public shaming","right":"A private call-in"},{"left":"Hoarding credit","right":"Sharing credit"},{"left":"Talking over people","right":"Making space"},{"left":"Waiting for a stage","right":"Leading where you are"},{"left":"Copying a pose","right":"Leading from your values"}],"relearn":"Call-in, shared credit, making space, leading where you are, being real: all stronger.","source":"weak ↔ strong","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1422","type":"spot","hook":"Spot the 2 lines that are NOT a real plan, just empty vows.","scene":[{"id":"a","text":"\"I'll share cleanup tonight\"","trick":false},{"id":"b","text":"\"I'll be amazing someday\"","trick":true},{"id":"c","text":"\"I'll credit Riya in tomorrow's meeting\"","trick":false},{"id":"d","text":"\"I'll fix everything eventually\"","trick":true},{"id":"e","text":"\"I'll ask Dev to apply by Friday\"","trick":false}],"why":"'Someday' and 'eventually' aren't plans; a real step is small, specific and dated.","relearn":"A real plan is one small, specific action you'll actually do, not 'someday'.","source":"plan vs vow","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1423","type":"spot","hook":"Spot the 2 grandstanding moves hiding among the real leading.","scene":[{"id":"a","text":"Quietly shares a chore, unasked","trick":false},{"id":"b","text":"Only leads when the camera's on","trick":true},{"id":"c","text":"Credits a teammate's idea","trick":false},{"id":"d","text":"Dunks on a rival for applause","trick":true},{"id":"e","text":"Says the hard thing kindly","trick":false}],"why":"Leading-for-the-camera and public dunking are grandstanding, not leadership.","relearn":"Real leading is steady and quiet; performing for credit is grandstanding.","source":"lead vs grandstand","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1424","type":"spot","hook":"Spot the 2 call-OUT moves among these responses to a bad joke.","scene":[{"id":"a","text":"\"Can we drop that one?\" said privately","trick":false},{"id":"b","text":"Screenshots it to shame him online","trick":true},{"id":"c","text":"A quiet word, assuming good faith","trick":false},{"id":"d","text":"Mocks him loudly in the group chat","trick":true},{"id":"e","text":"\"Let's chat, just us two\"","trick":false}],"why":"Public screenshots and group mocking are shaming call-outs that entrench, not change.","relearn":"A private, good-faith call-in changes minds; public call-outs just shame.","source":"call-in vs out","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1425","type":"spot","hook":"Spot the 2 unsafe 'leadership' moves to avoid here.","scene":[{"id":"a","text":"Brings in a teacher when it turns ugly","trick":false},{"id":"b","text":"Jumps alone into a violent fight","trick":true},{"id":"c","text":"Calls 112 when someone's at risk","trick":false},{"id":"d","text":"Confronts a dangerous man by himself","trick":true},{"id":"e","text":"Gets friends to step in together","trick":false}],"why":"Going in alone against violence or danger isn't brave leading: it's unsafe.","relearn":"When it's unsafe, bring others in or call 112, never confront alone.","source":"safety first","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1426","type":"spot","hook":"Spot the 2 moves that put your image over your team.","scene":[{"id":"a","text":"Credits the people who did the work","trick":false},{"id":"b","text":"Takes sole credit for a team win","trick":true},{"id":"c","text":"Mentors someone newer than them","trick":false},{"id":"d","text":"Sidelines anyone who might outshine them","trick":true},{"id":"e","text":"Backs a rival's good idea","trick":false}],"why":"Grabbing credit and sidelining rising people serves your image, not the team.","relearn":"Lifting and sharing credit builds a team; hoarding only props up your image.","source":"team vs image","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1427","type":"spot","hook":"Spot the 2 lines that fake allyship instead of doing it.","scene":[{"id":"a","text":"Listens to the person affected first","trick":false},{"id":"b","text":"Posts one hashtag, then nothing","trick":true},{"id":"c","text":"Amplifies a silenced voice","trick":false},{"id":"d","text":"Brags about 'caring' for the likes","trick":true},{"id":"e","text":"Shows up again the next week","trick":false}],"why":"A one-off post and caring-for-likes are performance; real allyship is consistent action.","relearn":"Real allyship is listening, amplifying and showing up, not a one-off post.","source":"active vs performative","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1428","type":"spot","hook":"Spot the 2 lines that copy a pose instead of leading as yourself.","scene":[{"id":"a","text":"Leads calmly, the way you really are","trick":false},{"id":"b","text":"Fakes a harsh 'boss' voice for show","trick":true},{"id":"c","text":"Acts from your own values","trick":false},{"id":"d","text":"Mimics an influencer's every move","trick":true},{"id":"e","text":"Treats people the way you actually do","trick":false}],"why":"A faked voice and a copied act aren't leadership; an authentic style is what lasts.","relearn":"Lead from your own values; a borrowed pose won't hold up.","source":"authentic vs pose","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1429","type":"spot","hook":"Spot the 2 lines that frame a boy's allyship as weakness.","scene":[{"id":"a","text":"\"Standing for fairness is the strong move\"","trick":false},{"id":"b","text":"\"You're betraying the boys\"","trick":true},{"id":"c","text":"\"Equality is everyone's job\"","trick":false},{"id":"d","text":"\"Real men don't bother with this\"","trick":true},{"id":"e","text":"\"It frees you from rigid roles too\"","trick":false}],"why":"'Betraying the boys' and 'real men don't' are the myths; a boy leading is strength.","relearn":"A boy leading on equality is strength, not betrayal or weakness.","persona":"Vijay","source":"male allyship","cat":"your-leadership-style"},
  {"id":"lw-1430","type":"strike-rewrite","hook":"\"A real leader is born that way: you either have it or you don't.\"","myth":{"un":"A real leader is born that way. You either have it or you don't.","re":"Leadership is learned in small acts: sharing the load, lifting one person, keeping your word.","why":"People grow into leaders by practising, not by birth."},"relearn":"Leadership is learned in small everyday acts, not something you're born with.","source":"learned not born","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1431","type":"strike-rewrite","hook":"\"To lead, you have to be the loudest person in the room.\"","myth":{"un":"To lead, you have to be the loudest in the room.","re":"Quiet, steady example often leads better than the loudest voice.","why":"Norms shift through what people see modelled, not who shouts."},"relearn":"You needn't be the loudest; quiet, steady example is real leadership.","source":"quiet leadership","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1432","type":"strike-rewrite","hook":"\"A plan to lead has to be big to count.\"","myth":{"un":"A plan to lead has to be big to count.","re":"A real plan is one small, specific action you'll actually do this week.","why":"Big change is built from small steps that actually happen."},"relearn":"A real plan is one small, specific action you'll do, not something grand.","source":"small plan","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1433","type":"strike-rewrite","hook":"\"You should copy a famous leader's style to be taken seriously.\"","myth":{"un":"You should copy a famous leader's style to be taken seriously.","re":"Leading from your own values is what makes your leadership real and sustainable.","why":"A borrowed style wears off; your own you can keep up."},"relearn":"Lead from your own values, not a copied style; that's what lasts.","source":"authentic style","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1434","type":"strike-rewrite","hook":"\"If you're not in charge, you can't really lead.\"","myth":{"un":"If you're not in charge, you can't really lead.","re":"You can lead from anywhere: by example, by lifting one other person.","why":"Influence isn't a job title; it's how you act in the room."},"relearn":"You can lead from anywhere, no title needed: by example and by lifting others.","source":"no title needed","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1435","type":"strike-rewrite","hook":"\"Leading on fairness means you're against the boys.\"","myth":{"un":"Leading on fairness means you're against the boys.","re":"There are no 'sides' in fairness; a boy leading on it is strength, and it frees him too.","why":"Equality lifts everyone, men included: it's not a loss."},"relearn":"A boy leading on fairness is strength, not 'against the boys'.","persona":"Vijay","source":"male allyship","cat":"your-leadership-style"},
  {"id":"lw-1436","type":"strike-rewrite","hook":"\"A good leader never lets anyone see them unsure.\"","myth":{"un":"A good leader never lets anyone see them unsure.","re":"Admitting you don't know and asking for help is honest leadership, not weakness.","why":"Trust grows when a leader is real, not faking certainty."},"relearn":"Admitting you're unsure and asking for help is honest leadership.","source":"honest uncertainty","cat":"your-leadership-style","persona":"any"},
  {"id":"lw-1437","type":"strike-rewrite","hook":"\"One quiet person can't change a whole group.\"","myth":{"un":"One quiet person can't change a whole group.","re":"One person leading by example and lifting one other genuinely shifts the room.","why":"Norms change one steady example at a time."},"relearn":"One person leading by example and lifting one other shifts the room.","source":"agency","cat":"your-leadership-style","persona":"any"},
];

